// Original app text, pre-rendered Danish AI narration. No runtime TTS service.
export const VOICE_PACK = {"label":"Dansk voiceover","speaker":"Jeppe · dansk AI-stemme","speakerId":"jeppe-neural-v1","status":"complete","clips":{"v1-076ad18f8fb56148":{"src":"assets/voice/jeppe-neural-v1/v1-076ad18f8fb56148.mp3","text":"Pedalen trædes halvt ned, forbindelsen bevares delvist, gearet skiftes, og pedalen løftes hurtigt for blød overførsel."},"v1-177cf50bbb87f5d0":{"src":"assets/voice/jeppe-neural-v1/v1-177cf50bbb87f5d0.mp3","text":"Pedalen trædes i bund, forbindelsen forstærkes, gearet skiftes, og pedalen holdes nede for blød overførsel."},"v1-3f9165e0edc2d4c2":{"src":"assets/voice/jeppe-neural-v1/v1-3f9165e0edc2d4c2.mp3","text":"Mulighed 2."},"v1-55dac103f034b33b":{"src":"assets/voice/jeppe-neural-v1/v1-55dac103f034b33b.mp3","text":"Velkommen til Natkørsel. Se klippet. Find problemet, vælg reglen og placér bilen. Til sidst ser du et korrekt forløb. Du kan altid prøve igen."},"v1-3f94c7e0edc5b11f":{"src":"assets/voice/jeppe-neural-v1/v1-3f94c7e0edc5b11f.mp3","text":"Mulighed 3."},"v1-3f9b67e0edcb2cad":{"src":"assets/voice/jeppe-neural-v1/v1-3f9b67e0edcb2cad.mp3","text":"Mulighed 1."},"v1-7a87a635cfde1cb0":{"src":"assets/voice/jeppe-neural-v1/v1-7a87a635cfde1cb0.mp3","text":"I en bil med koblingspedal skal du forklare, hvad der sker under et gearskift. Hvilken rækkefølge følger koblingens funktion i Plan B?"},"v1-6f98918b20e3ae0c":{"src":"assets/voice/jeppe-neural-v1/v1-6f98918b20e3ae0c.mp3","text":"STOP består af to beslutninger: først fuld standsning, derefter sikker vigepligtsvurdering. Fuld standsning. B 13 kræver, at bilen står helt stille ved stoplinjen. Findes ingen stoplinje, standses før indkørsel i krydset. En meget langsom rullende bevægelse er ikke stop, selv når vejen ser tom ud. Stop løser ikke vigepligten. Efter fuldt stop har du stadig ubetinget vigepligt for kørende fra begge sider. Orienter dig efter biler, cyklister og knallerter. Kontrollér særskilt gående, og overhold pligterne ved svingning og fodgængerfelt. Kør kun frem, når der er plads, uden at andre påvirkes. Et ekstra stop kan kræves. Hvis stoplinjen ligger før et sted med frit udsyn, standser du først ved linjen og kører derefter langsomt frem. Stands igen, hvis det er nødvendigt for at orientere dig, men undgå at placere bilen i tværtrafikkens bane."},"v1-02dcf637695a37af":{"src":"assets/voice/jeppe-neural-v1/v1-02dcf637695a37af.mp3","text":"Bilen nærmer sig B 11 og hajtænder. En anden bil kommer fra venstre på den vej, der skal krydses."},"v1-0dea0c921f5f84c9":{"src":"assets/voice/jeppe-neural-v1/v1-0dea0c921f5f84c9.mp3","text":"Efter fodgængerfeltet"},"v1-1211858654e53474":{"src":"assets/voice/jeppe-neural-v1/v1-1211858654e53474.mp3","text":"Bilen nærmer sig et ureguleret fodgængerfelt. En gående står ved kanten og er tydeligt på vej ud i feltet."},"v1-dffb1bd35fdf8221":{"src":"assets/voice/jeppe-neural-v1/v1-dffb1bd35fdf8221.mp3","text":"Pedalen trædes i bund, forbindelsen afbrydes, gearet skiftes, og pedalen løftes langsomt for blød overførsel."},"v1-1272d2c7f6ea848c":{"src":"assets/voice/jeppe-neural-v1/v1-1272d2c7f6ea848c.mp3","text":"“Jeg lavede et administrativt stop. Stop & Søn kalder det flydende papirarbejde.”"},"v1-13a00922eda2324a":{"src":"assets/voice/jeppe-neural-v1/v1-13a00922eda2324a.mp3","text":"På fodgængerfeltet"},"v1-1956f90e2533f920":{"src":"assets/voice/jeppe-neural-v1/v1-1956f90e2533f920.mp3","text":"Forbi hajtænderne"},"v1-1911e97baf5394e6":{"src":"assets/voice/jeppe-neural-v1/v1-1911e97baf5394e6.mp3","text":"Blink i god tid, og begynd svinget roligt, så cyklisten ved, at bilen kører først."},"v1-2959a2b814f1a1f7":{"src":"assets/voice/jeppe-neural-v1/v1-2959a2b814f1a1f7.mp3","text":"Feltets afmærkning"},"v1-306ff7f36842c9bc":{"src":"assets/voice/jeppe-neural-v1/v1-306ff7f36842c9bc.mp3","text":"Ved højresving skal føreren orientere sig helt frem til svinget og holde tilbage for cyklister, der fortsætter ligeud. Blinklyset ændrer ikke vigepligten."},"v1-1d6c5b4b5cb140f0":{"src":"assets/voice/jeppe-neural-v1/v1-1d6c5b4b5cb140f0.mp3","text":"Fuld standsning, hvis der er trafik. Ellers orientering og langsom passage."},"v1-2143110b0024f142":{"src":"assets/voice/jeppe-neural-v1/v1-2143110b0024f142.mp3","text":"Giv et kort hornsignal ved feltet. Det fortæller den gående, at bilen kører først."},"v1-3d7d7e335cff87f4":{"src":"assets/voice/jeppe-neural-v1/v1-3d7d7e335cff87f4.mp3","text":"Midt i krydset"},"v1-406b193c0ee66aa2":{"src":"assets/voice/jeppe-neural-v1/v1-406b193c0ee66aa2.mp3","text":"“Jeg regnede med, at zebrastriberne var nattøj til asfalten.”"},"v1-3d9eedc0f2b3b9c2":{"src":"assets/voice/jeppe-neural-v1/v1-3d9eedc0f2b3b9c2.mp3","text":"Tilpas farten og stands om nødvendigt. Den gående skal kunne passere uden fare eller ulempe."},"v1-30bfa72555856166":{"src":"assets/voice/jeppe-neural-v1/v1-30bfa72555856166.mp3","text":"Hvilken regel skal føreren bruge?"},"v1-45cf841a16f47563":{"src":"assets/voice/jeppe-neural-v1/v1-45cf841a16f47563.mp3","text":"På cykelstien"},"v1-4d0137bef02b0cbc":{"src":"assets/voice/jeppe-neural-v1/v1-4d0137bef02b0cbc.mp3","text":"Den gående"},"v1-4cabacd53981aa8f":{"src":"assets/voice/jeppe-neural-v1/v1-4cabacd53981aa8f.mp3","text":"Bilens kørselsretning"},"v1-46d3dec3b567ef3e":{"src":"assets/voice/jeppe-neural-v1/v1-46d3dec3b567ef3e.mp3","text":"Vis retningen med blinklys i god tid. Derefter får du ret til at køre først."},"v1-58211fc7444c95a4":{"src":"assets/voice/jeppe-neural-v1/v1-58211fc7444c95a4.mp3","text":"Tværbilens vognbane"},"v1-591772dbd56ced15":{"src":"assets/voice/jeppe-neural-v1/v1-591772dbd56ced15.mp3","text":"Peg på det afgørende tegn i situationen."},"v1-50c84008390045c7":{"src":"assets/voice/jeppe-neural-v1/v1-50c84008390045c7.mp3","text":"“Jeg blinkede, så jeg antog, at universet havde accepteret min reservation.”"},"v1-5daf40fa8c94ddaf":{"src":"assets/voice/jeppe-neural-v1/v1-5daf40fa8c94ddaf.mp3","text":"Langsom passage ved linjen. Et overskueligt kryds kræver kun orientering."},"v1-6a37351bcdba44e3":{"src":"assets/voice/jeppe-neural-v1/v1-6a37351bcdba44e3.mp3","text":"Egen bils placering"},"v1-61a0c86a522e125b":{"src":"assets/voice/jeppe-neural-v1/v1-61a0c86a522e125b.mp3","text":"Efter stoplinjen"},"v1-650fbd71bc52f564":{"src":"assets/voice/jeppe-neural-v1/v1-650fbd71bc52f564.mp3","text":"Fortsæt med lav fart forbi kanten. Stands først, når den gående er midt i feltet."},"v1-65b7274fc234dc7b":{"src":"assets/voice/jeppe-neural-v1/v1-65b7274fc234dc7b.mp3","text":"Ved et ureguleret fodgængerfelt skal føreren tilpasse farten og om nødvendigt standse for en gående, der er på vej ud, så personen ikke udsættes for fare eller ulempe."},"v1-852c51c12f0f661d":{"src":"assets/voice/jeppe-neural-v1/v1-852c51c12f0f661d.mp3","text":"Vognbanens placering"},"v1-6ec2c604f9eba136":{"src":"assets/voice/jeppe-neural-v1/v1-6ec2c604f9eba136.mp3","text":"Bilens vognbane"},"v1-727145646f76ebc8":{"src":"assets/voice/jeppe-neural-v1/v1-727145646f76ebc8.mp3","text":"Hold tilbage for tværtrafikken. Den må ikke tvinges til at ændre fart eller placering."},"v1-766fb9d1db911c17":{"src":"assets/voice/jeppe-neural-v1/v1-766fb9d1db911c17.mp3","text":"Bilen nærmer sig B 13 i lav fart. Sidevejen er tom, men føreren ruller over stoplinjen."},"v1-98f6f1ad278bd5d6":{"src":"assets/voice/jeppe-neural-v1/v1-98f6f1ad278bd5d6.mp3","text":"Hajtænderne"},"v1-9ece1d68fe1267d4":{"src":"assets/voice/jeppe-neural-v1/v1-9ece1d68fe1267d4.mp3","text":"Peg på det afgørende problem i klippet."},"v1-95c00fbed7b6efab":{"src":"assets/voice/jeppe-neural-v1/v1-95c00fbed7b6efab.mp3","text":"B 13 betyder fuldt stop ved stoplinjen. Et tomt kryds ophæver ikke stoppligten; efter stoppet gælder den ubetingede vigepligt stadig."},"v1-95fe0179cf88028a":{"src":"assets/voice/jeppe-neural-v1/v1-95fe0179cf88028a.mp3","text":"Bilen vil dreje til højre over en cykelsti. Cyklisten fortsætter ligeud og er nået op langs bilens højre side."},"v1-a3ce774a5288435e":{"src":"assets/voice/jeppe-neural-v1/v1-a3ce774a5288435e.mp3","text":"Helt før stoplinjen"},"v1-a1d9858568084f2a":{"src":"assets/voice/jeppe-neural-v1/v1-a1d9858568084f2a.mp3","text":"På tværtrafikkens bane"},"v1-afbdf92b90e8c59a":{"src":"assets/voice/jeppe-neural-v1/v1-afbdf92b90e8c59a.mp3","text":"Placér bilen, mens den gående går ud i feltet."},"v1-ac3673d41d17cbeb":{"src":"assets/voice/jeppe-neural-v1/v1-ac3673d41d17cbeb.mp3","text":"Hold tilbage for trafik fra højre. Trafik fra venstre må afvente din passage."},"v1-b420911063b6dee1":{"src":"assets/voice/jeppe-neural-v1/v1-b420911063b6dee1.mp3","text":"Vejkantens placering"},"v1-bd84e1883e84aba5":{"src":"assets/voice/jeppe-neural-v1/v1-bd84e1883e84aba5.mp3","text":"Stoplinjen"},"v1-b020e2ff0df2e93c":{"src":"assets/voice/jeppe-neural-v1/v1-b020e2ff0df2e93c.mp3","text":"Bag hajtænderne"},"v1-b5a363da4b110b3e":{"src":"assets/voice/jeppe-neural-v1/v1-b5a363da4b110b3e.mp3","text":"Peg på det vigtigste problem i klippet."},"v1-cb66624afb09e2a0":{"src":"assets/voice/jeppe-neural-v1/v1-cb66624afb09e2a0.mp3","text":"Før cykelstien"},"v1-cc2c6a49769a55f0":{"src":"assets/voice/jeppe-neural-v1/v1-cc2c6a49769a55f0.mp3","text":"Hvilken regel beskriver situationen?"},"v1-bfc3eac00f2d5085":{"src":"assets/voice/jeppe-neural-v1/v1-bfc3eac00f2d5085.mp3","text":"Placér bilen, mens tværtrafikken passerer."},"v1-c9a025b62ff9b8ba":{"src":"assets/voice/jeppe-neural-v1/v1-c9a025b62ff9b8ba.mp3","text":"Placér bilen, mens cyklisten passerer ligeud."},"v1-cdae6205a7f48cf9":{"src":"assets/voice/jeppe-neural-v1/v1-cdae6205a7f48cf9.mp3","text":"Placér bilen, hvor det pligtige stop skal ske."},"v1-e0f9a13ec9517199":{"src":"assets/voice/jeppe-neural-v1/v1-e0f9a13ec9517199.mp3","text":"Cyklisten"},"v1-dd297d10f9b089ef":{"src":"assets/voice/jeppe-neural-v1/v1-dd297d10f9b089ef.mp3","text":"Før fodgængerfeltet"},"v1-d2231d295e5a97e0":{"src":"assets/voice/jeppe-neural-v1/v1-d2231d295e5a97e0.mp3","text":"“Jeg så hajtænderne. Jeg troede bare, de var kommunens tandlægeregning.”"},"v1-f933581d1a5dbcd1":{"src":"assets/voice/jeppe-neural-v1/v1-f933581d1a5dbcd1.mp3","text":"Inde i højresvinget"},"v1-e2217c53d5e406d0":{"src":"assets/voice/jeppe-neural-v1/v1-e2217c53d5e406d0.mp3","text":"Hvad kræver højresvinget?"},"v1-ed2506d8289eec3b":{"src":"assets/voice/jeppe-neural-v1/v1-ed2506d8289eec3b.mp3","text":"Orientér dig igen, og vent før svinget, til den ligeudkørende cyklist er passeret."},"v1-f3fb2b808fadedb6":{"src":"assets/voice/jeppe-neural-v1/v1-f3fb2b808fadedb6.mp3","text":"Ved B 11 og hajtænder har føreren ubetinget vigepligt. Bilen skal vente, så den krydsende trafik kan fortsætte uden at ændre fart eller placering."},"v1-0042ebbb92272a05":{"src":"assets/voice/jeppe-neural-v1/v1-0042ebbb92272a05.mp3","text":"Stiller mig midt på kørebanen uden synlighed."},"v1-fd995bf5b8472636":{"src":"assets/voice/jeppe-neural-v1/v1-fd995bf5b8472636.mp3","text":"Hvordan skal føreren reagere?"},"v1-feabaf6750079c97":{"src":"assets/voice/jeppe-neural-v1/v1-feabaf6750079c97.mp3","text":"Fuld standsning ved linjen. Derefter orientering og ubetinget vigepligt."},"v1-faa9721c88060b7e":{"src":"assets/voice/jeppe-neural-v1/v1-faa9721c88060b7e.mp3","text":"Brug det første spejlkig, og drej roligt, når cyklisten tidligere var bag bilen."},"v1-006758c717a09015":{"src":"assets/voice/jeppe-neural-v1/v1-006758c717a09015.mp3","text":"Må overskride 60, når vejen er tom."},"v1-01057d07de4524fe":{"src":"assets/voice/jeppe-neural-v1/v1-01057d07de4524fe.mp3","text":"Dækskaden kræver handling før kørsel."},"v1-010f9a6b28c44471":{"src":"assets/voice/jeppe-neural-v1/v1-010f9a6b28c44471.mp3","text":"P-skiven er den ene kollega, der faktisk logger tiden."},"v1-014f34d3b65b2323":{"src":"assets/voice/jeppe-neural-v1/v1-014f34d3b65b2323.mp3","text":"Ser kun mod bilerne bagfra."},"v1-026288692f44adfe":{"src":"assets/voice/jeppe-neural-v1/v1-026288692f44adfe.mp3","text":"Du skal følge signalet for din egen kørselsretning. Togets lange bremselængde og bundne spor kræver skærpet kontrol, også når der senere bliver grønt."},"v1-02cb3bc8ccf099f5":{"src":"assets/voice/jeppe-neural-v1/v1-02cb3bc8ccf099f5.mp3","text":"Standser før stoplinjen."},"v1-0316c279745353e8":{"src":"assets/voice/jeppe-neural-v1/v1-0316c279745353e8.mp3","text":"Hvad gælder præcis kl. 05.00? En 17-årig har gyldigt dansk B-kørekort og befinder sig i Danmark. Klokken skifter fra 04.59 til 05.00, og der er ingen ledsager i bilen."},"v1-0398a5f19690086a":{"src":"assets/voice/jeppe-neural-v1/v1-0398a5f19690086a.mp3","text":"Markere spørgsmålet og vende tilbage senere."},"v1-043ce36594683967":{"src":"assets/voice/jeppe-neural-v1/v1-043ce36594683967.mp3","text":"Ved venstresving skal føreren også beskytte gående og cyklister på den vej, der svinges ind på. En dobbeltrettet cykelsti kræver orientering i begge retninger."},"v1-056f2f4862c647f6":{"src":"assets/voice/jeppe-neural-v1/v1-056f2f4862c647f6.mp3","text":"Må fortsætte alene efter kl. 20.00, fordi turen begyndte før."},"v1-057168497fd0470c":{"src":"assets/voice/jeppe-neural-v1/v1-057168497fd0470c.mp3","text":"Må du vende her? Du har misset en afkørsel på motorvejen. Næste afkørsel er fem kilometer væk, og nødsporet er tomt."},"v1-05d811b06593ac58":{"src":"assets/voice/jeppe-neural-v1/v1-05d811b06593ac58.mp3","text":"Bolden er trailer for næste scene."},"v1-05eaa554abf3432c":{"src":"assets/voice/jeppe-neural-v1/v1-05eaa554abf3432c.mp3","text":"Hvad betyder C 55 med 60? En C 55-tavle viser 60. Vejen er våd, og sigten er kortere end normalt."},"v1-06869272887d8eb2":{"src":"assets/voice/jeppe-neural-v1/v1-06869272887d8eb2.mp3","text":"Kører direkte ud, fordi første stop ophæver vigepligten."},"v1-06e3f2994a606752":{"src":"assets/voice/jeppe-neural-v1/v1-06e3f2994a606752.mp3","text":"Hvordan giver du plads? Du holder for rødt i højre bane. En ambulance med blå blink og sirene nærmer sig bagfra. Der er fodgængere i krydset."},"v1-073b7910108a2bbc":{"src":"assets/voice/jeppe-neural-v1/v1-073b7910108a2bbc.mp3","text":"Unødig luftmodstand, lavt dæktryk og ujævn kørsel øger forbruget. Sikker kontrol går altid først."},"v1-073b946b94c9eeff":{"src":"assets/voice/jeppe-neural-v1/v1-073b946b94c9eeff.mp3","text":"Har kun vigepligt for trafik fra venstre."},"v1-077a3a6c7db57949":{"src":"assets/voice/jeppe-neural-v1/v1-077a3a6c7db57949.mp3","text":"Finder en almindelig lovlig plads."},"v1-0783a05bb866e521":{"src":"assets/voice/jeppe-neural-v1/v1-0783a05bb866e521.mp3","text":"Antage, at NATKØRSEL-optællingen er dokumenteret identisk med myndighedens."},"v1-07d76bf78f9d3981":{"src":"assets/voice/jeppe-neural-v1/v1-07d76bf78f9d3981.mp3","text":"Hvad er den sikre plan? Du er ny bilist og skal til fest. Du har bilen med og ved endnu ikke, om du vil drikke."},"v1-07fb0f0ad63775ab":{"src":"assets/voice/jeppe-neural-v1/v1-07fb0f0ad63775ab.mp3","text":"Hvem skal sikres? Du skal køre en kort tur med et barn på 120 cm. Den godkendte barnestol, som passer til barnets højde og vægt og til bilen, står i en anden bil."},"v1-089ccc36578bb362":{"src":"assets/voice/jeppe-neural-v1/v1-089ccc36578bb362.mp3","text":"Slutstillingen i planens øvelse er parallel med kanten og højst 20 cm fra højre hjul til kanten. Færdigheden kræver fysisk træning på øvelsesplads."},"v1-08ee4b4a2c8350f2":{"src":"assets/voice/jeppe-neural-v1/v1-08ee4b4a2c8350f2.mp3","text":"Finder et sted helt uden for fortov og cykelsti."},"v1-0937f2ff79e093d4":{"src":"assets/voice/jeppe-neural-v1/v1-0937f2ff79e093d4.mp3","text":"Bakker i nødsporet til sidste frakørsel."},"v1-096a0680ea0fe67a":{"src":"assets/voice/jeppe-neural-v1/v1-096a0680ea0fe67a.mp3","text":"Alkohol svækker netop den dømmekraft, man skulle bruge til at vurdere sig selv. Planlæg nul alkohol før kørsel."},"v1-09e3ade12de3ffee":{"src":"assets/voice/jeppe-neural-v1/v1-09e3ade12de3ffee.mp3","text":"Kører over hellen, hvis det sparer tid."},"v1-0a531531127b0521":{"src":"assets/voice/jeppe-neural-v1/v1-0a531531127b0521.mp3","text":"Tænder fjernlys mod de forankørende."},"v1-0ab02ff0f8f3e1b3":{"src":"assets/voice/jeppe-neural-v1/v1-0ab02ff0f8f3e1b3.mp3","text":"I cykelgade skal motorkørende vise særlig agtpågivenhed og må ikke unødigt hindre eller presse cyklister. Et bump kan kræve yderligere fartnedsættelse."},"v1-0b7b7e237253430e":{"src":"assets/voice/jeppe-neural-v1/v1-0b7b7e237253430e.mp3","text":"Last skal sikres. Vægt og placering påvirker bilens stabilitet og bremsning."},"v1-0ba8d5bcb05e49b3":{"src":"assets/voice/jeppe-neural-v1/v1-0ba8d5bcb05e49b3.mp3","text":"Orienterer mig igen lige før svinget."},"v1-0bce03b886392e22":{"src":"assets/voice/jeppe-neural-v1/v1-0bce03b886392e22.mp3","text":"Springer stoplinjen over og standser kun ved udsynet."},"v1-0c38870164959544":{"src":"assets/voice/jeppe-neural-v1/v1-0c38870164959544.mp3","text":"Venter med indstilling, til jeg er ude af parkeringspladsen."},"v1-0cd5a984f4e9d8c0":{"src":"assets/voice/jeppe-neural-v1/v1-0cd5a984f4e9d8c0.mp3","text":"Sikrer værktøjskassen mod at flytte sig."},"v1-0cef7f9a8b7ed85f":{"src":"assets/voice/jeppe-neural-v1/v1-0cef7f9a8b7ed85f.mp3","text":"Lader den gående passere uden fare eller ulempe."},"v1-0d43dafc253eeb6c":{"src":"assets/voice/jeppe-neural-v1/v1-0d43dafc253eeb6c.mp3","text":"Kører straks ud, fordi blinklyset giver fortrinsret."},"v1-0e57d296ddb53ba9":{"src":"assets/voice/jeppe-neural-v1/v1-0e57d296ddb53ba9.mp3","text":"Bevarer en sikker fart efter forholdene."},"v1-0ea349dcffbaf9e8":{"src":"assets/voice/jeppe-neural-v1/v1-0ea349dcffbaf9e8.mp3","text":"Ved et ureguleret felt skal hastigheden tilpasses, så gående i eller på vej ud i feltet ikke udsættes for fare eller ulempe; stands om nødvendigt."},"v1-0f2453d5db021640":{"src":"assets/voice/jeppe-neural-v1/v1-0f2453d5db021640.mp3","text":"Uden en afmærket bås må du hverken standse eller parkere i et kryds eller nærmere end 10 m fra den tværgående kørebanes nærmeste kant."},"v1-0f44672dba6d6431":{"src":"assets/voice/jeppe-neural-v1/v1-0f44672dba6d6431.mp3","text":"Dæk skal have mindst 1,6 mm i hovedmønstret og være ubeskadigede. Hurtigt blink kan tyde på lygtefejl."},"v1-1079c21195d0007c":{"src":"assets/voice/jeppe-neural-v1/v1-1079c21195d0007c.mp3","text":"Orienterer mig og kører først derefter, når vejen er fri."},"v1-10fe21856e28f81f":{"src":"assets/voice/jeppe-neural-v1/v1-10fe21856e28f81f.mp3","text":"Følger efter turen op med refleksion og feedback."},"v1-1111a4eacc644605":{"src":"assets/voice/jeppe-neural-v1/v1-1111a4eacc644605.mp3","text":"Undgår pludselige styre- og pedalbevægelser."},"v1-1145f9eb7d31294b":{"src":"assets/voice/jeppe-neural-v1/v1-1145f9eb7d31294b.mp3","text":"Hvad gør du først? Du ankommer til et frisk uheld på en mørk landevej. En person sidder i grøften, og en bil står delvist på kørebanen."},"v1-126a071ca535a00f":{"src":"assets/voice/jeppe-neural-v1/v1-126a071ca535a00f.mp3","text":"Kontrollerer begge retninger på cykelstien og holder tilbage for cyklisten."},"v1-12b1389debba4c7d":{"src":"assets/voice/jeppe-neural-v1/v1-12b1389debba4c7d.mp3","text":"Kører ind, fordi bommen er oppe."},"v1-1374a02f34fd0c1d":{"src":"assets/voice/jeppe-neural-v1/v1-1374a02f34fd0c1d.mp3","text":"Hvad hjælper i svinget? På lukket øvelsesplads kører du langsomt gennem et skarpt sving. Du stirrer på keglen ved bilens højre hjørne og driver hen imod den."},"v1-13d4dcc5344ca3d9":{"src":"assets/voice/jeppe-neural-v1/v1-13d4dcc5344ca3d9.mp3","text":"Skifter straks, fordi spejlene er fri."},"v1-1416c3227011053a":{"src":"assets/voice/jeppe-neural-v1/v1-1416c3227011053a.mp3","text":"Er maksimum også målet? Tavlen viser 80. Det regner kraftigt, sigten er kort, og vand samler sig i hjulsporene."},"v1-14798a7b06023928":{"src":"assets/voice/jeppe-neural-v1/v1-14798a7b06023928.mp3","text":"Holder tilbage for den gående og standser om nødvendigt før fodgængerfeltet."},"v1-150979701edfc5e8":{"src":"assets/voice/jeppe-neural-v1/v1-150979701edfc5e8.mp3","text":"Accelererer ind i svinget for at øge vejgrebet."},"v1-156617072d7eaaa8":{"src":"assets/voice/jeppe-neural-v1/v1-156617072d7eaaa8.mp3","text":"Dytter for at få personen til at vente."},"v1-1588dc525bfa10d3":{"src":"assets/voice/jeppe-neural-v1/v1-1588dc525bfa10d3.mp3","text":"Kontrollerer bagud før døren åbnes."},"v1-15dd2c035f912a0f":{"src":"assets/voice/jeppe-neural-v1/v1-15dd2c035f912a0f.mp3","text":"Kører forsigtigt, fordi håndbremsen findes."},"v1-1615fe21a847a045":{"src":"assets/voice/jeppe-neural-v1/v1-1615fe21a847a045.mp3","text":"Sætter farten op over det forsvarlige."},"v1-1702846ab10d1aef":{"src":"assets/voice/jeppe-neural-v1/v1-1702846ab10d1aef.mp3","text":"Hvad sparer energi sikkert? Du kører på en jævn vej med god oversigt. Tagboksen er tom, dækkene mangler luft, og du accelererer og bremser gentagne gange uden grund."},"v1-176525e1f07d0af2":{"src":"assets/voice/jeppe-neural-v1/v1-176525e1f07d0af2.mp3","text":"Holder tilbage for bilen fra højre."},"v1-18247d5ba3ffe51f":{"src":"assets/voice/jeppe-neural-v1/v1-18247d5ba3ffe51f.mp3","text":"Orienterer mig og følger den faktiske trafik frem for en sen instruktion."},"v1-1869331b5c0b690e":{"src":"assets/voice/jeppe-neural-v1/v1-1869331b5c0b690e.mp3","text":"Trekanten kræver respekt, ikke teaterpause."},"v1-18b589f002cba476":{"src":"assets/voice/jeppe-neural-v1/v1-18b589f002cba476.mp3","text":"Pumper pedalen og erklærer bilen rask uden kontrol."},"v1-17e8cbe25fbb66ff":{"src":"assets/voice/jeppe-neural-v1/v1-17e8cbe25fbb66ff.mp3","text":"Hastighedsgrænsen er et maksimum. Vej, vejr og sigt kan kræve væsentligt lavere fart."},"v1-1a73e1df29cfbd2c":{"src":"assets/voice/jeppe-neural-v1/v1-1a73e1df29cfbd2c.mp3","text":"Letbanen kommer ikke til køreskolen, men undervisningen gør."},"v1-18f07fb56d13492c":{"src":"assets/voice/jeppe-neural-v1/v1-18f07fb56d13492c.mp3","text":"“Tom vej” er ikke et gør-det-selv køreteknisk anlæg."},"v1-199617205378db11":{"src":"assets/voice/jeppe-neural-v1/v1-199617205378db11.mp3","text":"Venter på frit udsyn og tilstrækkelig plads."},"v1-19638b29f1c424da":{"src":"assets/voice/jeppe-neural-v1/v1-19638b29f1c424da.mp3","text":"Hvad er sikkert? Du vil bakke ud fra en indkørsel over et fortov. Et barn leger ved hækken, og bakkameraet viser kun området lige bag bilen."},"v1-1b2769fbbe678ec0":{"src":"assets/voice/jeppe-neural-v1/v1-1b2769fbbe678ec0.mp3","text":"Kører langsommere, hvis vej og sigt kræver det."},"v1-1c060ce3ddc047ea":{"src":"assets/voice/jeppe-neural-v1/v1-1c060ce3ddc047ea.mp3","text":"Bakkameraet er en hjælper, ikke en synsk professor."},"v1-1c4de72b53d55880":{"src":"assets/voice/jeppe-neural-v1/v1-1c4de72b53d55880.mp3","text":"Holder på sporet og regner med, at køen flytter sig."},"v1-1cbd98fa0f44d757":{"src":"assets/voice/jeppe-neural-v1/v1-1cbd98fa0f44d757.mp3","text":"Venter på signal for min kørselsretning og kontrollerer toget igen."},"v1-1e16cd633c49f20f":{"src":"assets/voice/jeppe-neural-v1/v1-1e16cd633c49f20f.mp3","text":"Politiets anvisning går foran lyssignal og almindelige regler."},"v1-1f7fe0d7a2acb11c":{"src":"assets/voice/jeppe-neural-v1/v1-1f7fe0d7a2acb11c.mp3","text":"Træthed kan ikke repareres sikkert med små tricks. Undlad at køre, når du ikke kan gøre det forsvarligt."},"v1-1e98c71145c9a47e":{"src":"assets/voice/jeppe-neural-v1/v1-1e98c71145c9a47e.mp3","text":"En brat tilbageføring over en høj kant ved for høj fart kan udløse tab af kontrol. På anlægget trænes rolig styring langs kanten, forsigtig fartreduktion og først derefter kontrolleret tilbageføring."},"v1-1d991ac79778a1c4":{"src":"assets/voice/jeppe-neural-v1/v1-1d991ac79778a1c4.mp3","text":"Hvilke vurderinger er rigtige? På morgenkontrollen ser du et dæk med tydelig skade i siden og måler 1,3 mm i hovedmønstret. Højre blinklys blinker meget hurtigere end normalt."},"v1-1f9fc82cf16684e6":{"src":"assets/voice/jeppe-neural-v1/v1-1f9fc82cf16684e6.mp3","text":"Må holde her i under tre minutter."},"v1-1fe47bb5d79000d2":{"src":"assets/voice/jeppe-neural-v1/v1-1fe47bb5d79000d2.mp3","text":"Skifter, fordi jeg har blinket tre gange."},"v1-2093c892bffeea31":{"src":"assets/voice/jeppe-neural-v1/v1-2093c892bffeea31.mp3","text":"Prøvetiden er valgfri, hvis den kaldes officiel simulation."},"v1-20acbb3e1a259940":{"src":"assets/voice/jeppe-neural-v1/v1-20acbb3e1a259940.mp3","text":"Er du køreklar? Efter en nat uden søvn gaber du konstant og mister kortvarigt fokus. Du skal køre en ven til lufthavnen."},"v1-220b585d6b9fc1d7":{"src":"assets/voice/jeppe-neural-v1/v1-220b585d6b9fc1d7.mp3","text":"Holder ekstra afstand til de parkerede biler."},"v1-21fa77b2251cc1bd":{"src":"assets/voice/jeppe-neural-v1/v1-21fa77b2251cc1bd.mp3","text":"Første kørekort har ingen aldersrabatkode."},"v1-20e3ab49cf6672f2":{"src":"assets/voice/jeppe-neural-v1/v1-20e3ab49cf6672f2.mp3","text":"Fodgængerfeltet er ikke et modspil i sten-saks-papir."},"v1-20d78fa1a7a14f81":{"src":"assets/voice/jeppe-neural-v1/v1-20d78fa1a7a14f81.mp3","text":"C 55 fastsætter en maksimal hastighed. Den konkrete sikre fart kan være lavere på grund af vejr, udsyn og trafik."},"v1-226d5f0fab7145e6":{"src":"assets/voice/jeppe-neural-v1/v1-226d5f0fab7145e6.mp3","text":"Venter før overkørslen."},"v1-235ac8b37e1fd34d":{"src":"assets/voice/jeppe-neural-v1/v1-235ac8b37e1fd34d.mp3","text":"Kører uden at tvinge nogen til at ændre fart eller placering."},"v1-23057f7cec319f30":{"src":"assets/voice/jeppe-neural-v1/v1-23057f7cec319f30.mp3","text":"Har fortrinsret, fordi der ikke er hajtænder."},"v1-22d721f7ed3c4245":{"src":"assets/voice/jeppe-neural-v1/v1-22d721f7ed3c4245.mp3","text":"Midlertidig gul regulering ved vejarbejde skal respekteres frem for modstridende hvid afmærkning. Farten skal tilpasses de arbejdende og den ændrede vejføring."},"v1-24e8e6fc51b949b4":{"src":"assets/voice/jeppe-neural-v1/v1-24e8e6fc51b949b4.mp3","text":"Tilpasser fart og placering før hellen."},"v1-23db67e89332d058":{"src":"assets/voice/jeppe-neural-v1/v1-23db67e89332d058.mp3","text":"Tænder nærlys, så bilen også er tydelig bagfra."},"v1-24543c9181703cf0":{"src":"assets/voice/jeppe-neural-v1/v1-24543c9181703cf0.mp3","text":"Begrænset udsyn gør det umuligt at sikre fri overhalingsstrækning. Vent."},"v1-2408a17387fc1055":{"src":"assets/voice/jeppe-neural-v1/v1-2408a17387fc1055.mp3","text":"Hvornår kan du køre? Du kommer fra en tankstation over et fortov og vil ud på vejen. Der er biler fra venstre og en cyklist fra højre på cykelstien."},"v1-25b6d4e4ee18447a":{"src":"assets/voice/jeppe-neural-v1/v1-25b6d4e4ee18447a.mp3","text":"Korrigerer dæktrykket efter bilens anvisning."},"v1-2531fb96731a33bd":{"src":"assets/voice/jeppe-neural-v1/v1-2531fb96731a33bd.mp3","text":"Under tre minutter er tilladt selv på et sted med standsningsforbud."},"v1-25c946cb092963f2":{"src":"assets/voice/jeppe-neural-v1/v1-25c946cb092963f2.mp3","text":"C 62 betyder også, at enhver standsning er forbudt."},"v1-25bdfa94755fc914":{"src":"assets/voice/jeppe-neural-v1/v1-25bdfa94755fc914.mp3","text":"Advarer andre og søger sikkerhed væk fra trafikken."},"v1-2680f95941d5b813":{"src":"assets/voice/jeppe-neural-v1/v1-2680f95941d5b813.mp3","text":"Regner ikke med fortovsundtagelsen uden for tættere bebygget område."},"v1-25e0290871c9d83f":{"src":"assets/voice/jeppe-neural-v1/v1-25e0290871c9d83f.mp3","text":"Afventer, hvis jeg ikke sikkert kan bedømme afstand og hastighed."},"v1-25dad275cc985d7e":{"src":"assets/voice/jeppe-neural-v1/v1-25dad275cc985d7e.mp3","text":"Rundkørslen er rund; dit ansvar er stadig helt."},"v1-26d414c3b8d22ae5":{"src":"assets/voice/jeppe-neural-v1/v1-26d414c3b8d22ae5.mp3","text":"Førerassistenter kan fejle. Føreren skal følge aktuelle anvisninger og har fortsat ansvaret."},"v1-27baeb14c7a92d67":{"src":"assets/voice/jeppe-neural-v1/v1-27baeb14c7a92d67.mp3","text":"Forventer, at et barn kan følge efter bolden."},"v1-274c0806f4e0252d":{"src":"assets/voice/jeppe-neural-v1/v1-274c0806f4e0252d.mp3","text":"Baglygterne kan ikke arbejde hjemmefra."},"v1-26d5604d64f3f7d4":{"src":"assets/voice/jeppe-neural-v1/v1-26d5604d64f3f7d4.mp3","text":"Bruger resultatet som frivillig træning."},"v1-2817b3a660a30045":{"src":"assets/voice/jeppe-neural-v1/v1-2817b3a660a30045.mp3","text":"Gælder højre vigepligt i T-krydset? Du kører ligeud på en lille vej. Fra din højre side munder en lige så lille vej ud. Der er ingen tavler, hajtænder, fortovsoverkørsel eller anden særlig regulering."},"v1-295683353836a729":{"src":"assets/voice/jeppe-neural-v1/v1-295683353836a729.mp3","text":"Ruten må gerne have et mål, der ikke er “hurtigst til bageren”."},"v1-293634cded485481":{"src":"assets/voice/jeppe-neural-v1/v1-293634cded485481.mp3","text":"Regner kravet fra det aktuelle klokkeslæt, ikke turens start."},"v1-29a8baf620934a22":{"src":"assets/voice/jeppe-neural-v1/v1-29a8baf620934a22.mp3","text":"Hvad forventer du? Du kører forbi en skole ved fyraften. Parkerede biler skjuler fortovet, og en forælder står med en åben bildør."},"v1-2887a8d8c0f2d090":{"src":"assets/voice/jeppe-neural-v1/v1-2887a8d8c0f2d090.mp3","text":"Ved tvungen standsning skal bilen væk fra kørebanen, andre advares, og personer beskyttes. Bakning er forbudt."},"v1-2a15b096ea2e9fc3":{"src":"assets/voice/jeppe-neural-v1/v1-2a15b096ea2e9fc3.mp3","text":"Bakker hurtigt, så fortovet er spærret kortere tid."},"v1-2ba9fe578eb12647":{"src":"assets/voice/jeppe-neural-v1/v1-2ba9fe578eb12647.mp3","text":"Lader en udhvilet person køre eller vælger anden transport."},"v1-2b5b85ba1eab86f9":{"src":"assets/voice/jeppe-neural-v1/v1-2b5b85ba1eab86f9.mp3","text":"Bred asfalt er stadig ikke et diplomatpas."},"v1-2a6a6e837e04a472":{"src":"assets/voice/jeppe-neural-v1/v1-2a6a6e837e04a472.mp3","text":"Pres bagfra ændrer ikke vejgreb eller udsyn. Kør forudsigeligt og giv eventuelt plads på en sikker måde."},"v1-2bd9ef44fa681e76":{"src":"assets/voice/jeppe-neural-v1/v1-2bd9ef44fa681e76.mp3","text":"Kører så langsomt, at jeg kan bedømme hjul og bilens hjørner."},"v1-2c3fe32a707a0b2c":{"src":"assets/voice/jeppe-neural-v1/v1-2c3fe32a707a0b2c.mp3","text":"Af- og påstigning regnes ikke som parkering, også når den konkrete handling varer over tre minutter. C 62 forbyder parkering, mens C 61 forbyder standsning."},"v1-2c3f5faeaa4123e5":{"src":"assets/voice/jeppe-neural-v1/v1-2c3f5faeaa4123e5.mp3","text":"Hvad gør du efter parkeringen? Du holder lovligt langs en cykelsti. En cyklist nærmer sig bagfra, og din passager vil åbne døren mod cykelstien."},"v1-2c024ac6f1823a90":{"src":"assets/voice/jeppe-neural-v1/v1-2c024ac6f1823a90.mp3","text":"Hvordan reagerer du? Før turen synker bremsepedalen langsomt mod gulvet, mens du holder et fast, konstant tryk. Bilen står stadig parkeret."},"v1-2c5b6f439df0039d":{"src":"assets/voice/jeppe-neural-v1/v1-2c5b6f439df0039d.mp3","text":"Regner med, at elcyklen har lav fart som en gående."},"v1-2c91052a42f9528c":{"src":"assets/voice/jeppe-neural-v1/v1-2c91052a42f9528c.mp3","text":"Slukker motoren, når det kan ske sikkert."},"v1-2d6e78641761cf1c":{"src":"assets/voice/jeppe-neural-v1/v1-2d6e78641761cf1c.mp3","text":"Hvad kræver tavlen? Du møder STOP og en tydelig stoplinje. Der er frit udsyn, og ingen anden trafik kan ses."},"v1-2cf63e9c83b126f7":{"src":"assets/voice/jeppe-neural-v1/v1-2cf63e9c83b126f7.mp3","text":"Hvad er korrekt om lasten? Bagagerummet er fyldt. En tung værktøjskasse står løst øverst, og bilen føles tungere end normalt."},"v1-2ef8c19bd4f76897":{"src":"assets/voice/jeppe-neural-v1/v1-2ef8c19bd4f76897.mp3","text":"Lader barnet holde fast i en voksen."},"v1-2dc34f37d05c56cb":{"src":"assets/voice/jeppe-neural-v1/v1-2dc34f37d05c56cb.mp3","text":"Kører først, når der er plads til hele bilen på den anden side."},"v1-2eb483b521a524d0":{"src":"assets/voice/jeppe-neural-v1/v1-2eb483b521a524d0.mp3","text":"Hvilke prøveoplysninger er rigtige? Du forbereder en fuld digital øveprøve til kategori B efter Færdselsstyrelsens aktuelle offentlige format."},"v1-2f44293df35e7d20":{"src":"assets/voice/jeppe-neural-v1/v1-2f44293df35e7d20.mp3","text":"Fem-meterreglen før fodgængerfeltet er et standsningsforbud. Kort varighed, afstigning og havariblink ophæver ikke et standsningsforbud."},"v1-2fb736b102b1f498":{"src":"assets/voice/jeppe-neural-v1/v1-2fb736b102b1f498.mp3","text":"Kører mere jævnt og forudseende."},"v1-2fa6daef17cd5244":{"src":"assets/voice/jeppe-neural-v1/v1-2fa6daef17cd5244.mp3","text":"Dækket opfylder ikke kravet til mønsterdybde."},"v1-30f8e93e7b55764b":{"src":"assets/voice/jeppe-neural-v1/v1-30f8e93e7b55764b.mp3","text":"Aftaler hjemtransport uden bil på forhånd."},"v1-2f466cfd2afde435":{"src":"assets/voice/jeppe-neural-v1/v1-2f466cfd2afde435.mp3","text":"Ruteplanlægning og førerstøtte kan indgå i sammensat kørsel, men er hjælpemidler. Eleven skal fortsat køre selvstændigt og ansvarligt efter de faktiske forhold."},"v1-3298cf2774455a45":{"src":"assets/voice/jeppe-neural-v1/v1-3298cf2774455a45.mp3","text":"Kører først, fordi hindringen er midlertidig."},"v1-3136ab86d99999cf":{"src":"assets/voice/jeppe-neural-v1/v1-3136ab86d99999cf.mp3","text":"Fortsætter til næste lovlige afkørsel."},"v1-32f24009e2647f0b":{"src":"assets/voice/jeppe-neural-v1/v1-32f24009e2647f0b.mp3","text":"60 km/t er den højest tilladte hastighed fra tavlen."},"v1-3104a3a35c16ceb3":{"src":"assets/voice/jeppe-neural-v1/v1-3104a3a35c16ceb3.mp3","text":"Bagklappen er ikke en juridisk spændestrop."},"v1-34f8b941cb6ad09b":{"src":"assets/voice/jeppe-neural-v1/v1-34f8b941cb6ad09b.mp3","text":"Blå blink kræver hjerne, ikke stuntkørsel."},"v1-342086e25dabda97":{"src":"assets/voice/jeppe-neural-v1/v1-342086e25dabda97.mp3","text":"En hensætning under tre minutter regnes ikke som parkering. Den er stadig en standsning og skal derfor overholde alle standsningsforbud og hensynsregler."},"v1-3322bcd56b78f37c":{"src":"assets/voice/jeppe-neural-v1/v1-3322bcd56b78f37c.mp3","text":"Skal holde præcis 60 km/t."},"v1-338c31cfcfa3830d":{"src":"assets/voice/jeppe-neural-v1/v1-338c31cfcfa3830d.mp3","text":"Hvad kræver tidsbegrænsningen? Det er onsdag kl. 10.00. En E 33-tavle med undertavle siger “2 timer, P-skive, hverdage 8-18”. Der er en fri almindelig bås, og ingen anden regel forbyder parkering."},"v1-352745dc2316c2eb":{"src":"assets/voice/jeppe-neural-v1/v1-352745dc2316c2eb.mp3","text":"Man må ikke begynde en overhaling, når en bagvedkørende allerede overhaler. Undgå konkurrence og konflikt."},"v1-3532e73d2533c1dc":{"src":"assets/voice/jeppe-neural-v1/v1-3532e73d2533c1dc.mp3","text":"Skifter bane straks, fordi GPS-instruktionen indgår i lektionen."},"v1-351c70ec312b40bf":{"src":"assets/voice/jeppe-neural-v1/v1-351c70ec312b40bf.mp3","text":"Må påstigningen tage over tre minutter? Ved en C 62-tavle er parkering forbudt, men standsning er tilladt. En gangbesværet passager bruger fire minutter på en sammenhængende påstigning, og bilen er ikke til fare eller ulempe."},"v1-34aa8e4dc6e01008":{"src":"assets/voice/jeppe-neural-v1/v1-34aa8e4dc6e01008.mp3","text":"I de første tre år efter dit første kategori B-kørekort straffes kørsel over 0,20 ‰ i blod eller over 0,10 mg/l udåndingsluft som spirituskørsel, uanset alder. Færdselsstyrelsens praktiske råd er ingen alkohol før kørsel."},"v1-3661d4ad1311f620":{"src":"assets/voice/jeppe-neural-v1/v1-3661d4ad1311f620.mp3","text":"Auto-lys er ikke en regn-orakel."},"v1-36a62a66a23e778f":{"src":"assets/voice/jeppe-neural-v1/v1-36a62a66a23e778f.mp3","text":"Korrigerer placeringen roligt, når området er frit."},"v1-36e7dc5f6cc82f63":{"src":"assets/voice/jeppe-neural-v1/v1-36e7dc5f6cc82f63.mp3","text":"Fortsætter, fordi personen endnu ikke står midt i feltet."},"v1-358ea1ae6769d450":{"src":"assets/voice/jeppe-neural-v1/v1-358ea1ae6769d450.mp3","text":"Hvordan bremser du bedst her? På våd vej opdager du tidligt en kø langt fremme. Bilen har moderne bremseassistenter, og der er god afstand."},"v1-37acc638b810dc64":{"src":"assets/voice/jeppe-neural-v1/v1-37acc638b810dc64.mp3","text":"Den bør bestå af 25 situationer."},"v1-36f35ebdb6283cc1":{"src":"assets/voice/jeppe-neural-v1/v1-36f35ebdb6283cc1.mp3","text":"25-25-5. Den eneste trio uden comeback-turné."},"v1-378df48101867449":{"src":"assets/voice/jeppe-neural-v1/v1-378df48101867449.mp3","text":"Hvordan kører du i området? Du passerer E 51 og kører ind i et opholds- og legeområde. Et barn leger på kørearealet, og der er ingen særligt afmærkede parkeringspladser."},"v1-383fcc109b1b678a":{"src":"assets/voice/jeppe-neural-v1/v1-383fcc109b1b678a.mp3","text":"Egen hjemmebrug tæller ikke automatisk som formel undervisning. En godkendt kørelærer kan planlægge, følge op på og registrere højst syv selvstudielektioner i egnede dele af afsnit 1, 3, 6, 9 og 10; afsnit 10 i modul 1 er undtaget. Appens badge er ikke dokumentation."},"v1-3a89c20b4e4794a0":{"src":"assets/voice/jeppe-neural-v1/v1-3a89c20b4e4794a0.mp3","text":"Kører på grønt, fordi signalet er elektronisk."},"v1-39f7a4bed9042bb6":{"src":"assets/voice/jeppe-neural-v1/v1-39f7a4bed9042bb6.mp3","text":"T-formen er geometri, ikke fortrinsret."},"v1-393f2e143fea599c":{"src":"assets/voice/jeppe-neural-v1/v1-393f2e143fea599c.mp3","text":"GPS’en kan genberegne. Det kan skærmen ikke gøre med et sidespejl."},"v1-39a5eb2ba87221f1":{"src":"assets/voice/jeppe-neural-v1/v1-39a5eb2ba87221f1.mp3","text":"B 13 kræver fuld standsning ved stoplinjen og derefter ubetinget vigepligt."},"v1-3b944c3dcb721f2c":{"src":"assets/voice/jeppe-neural-v1/v1-3b944c3dcb721f2c.mp3","text":"Sænker farten og venter før varebilen."},"v1-3c015467ae320076":{"src":"assets/voice/jeppe-neural-v1/v1-3c015467ae320076.mp3","text":"Det hurtige blink kan varsle en defekt blinklygte."},"v1-3afdc282e437bb88":{"src":"assets/voice/jeppe-neural-v1/v1-3afdc282e437bb88.mp3","text":"Regner ikke hjemmebrugen som automatisk gennemført undervisning."},"v1-3b9f1bb3a8210b87":{"src":"assets/voice/jeppe-neural-v1/v1-3b9f1bb3a8210b87.mp3","text":"Fører bilen så langt væk fra kørebanen som muligt."},"v1-3c07551fb617792d":{"src":"assets/voice/jeppe-neural-v1/v1-3c07551fb617792d.mp3","text":"Kører videre, hvis andre allerede filmer."},"v1-3cb96c5975262c30":{"src":"assets/voice/jeppe-neural-v1/v1-3cb96c5975262c30.mp3","text":"Svinget er først færdigt, når hele rollelisten er set."},"v1-3c5ec865ba964119":{"src":"assets/voice/jeppe-neural-v1/v1-3c5ec865ba964119.mp3","text":"E 33 med handicapsymbol reserverer arealet til køretøjer med den krævede tilladelse. Kort varighed og havariblink giver ingen adgang."},"v1-3d2742ebe8ec817b":{"src":"assets/voice/jeppe-neural-v1/v1-3d2742ebe8ec817b.mp3","text":"Hvad kræver cykelgaden? Du kører bil i en skiltet cykelgade. To cyklister kører foran side om side, og et fartdæmpende bump ligger længere fremme. Ingen kan sikkert passere lige nu."},"v1-3f825e9c8ef18e9e":{"src":"assets/voice/jeppe-neural-v1/v1-3f825e9c8ef18e9e.mp3","text":"Styrer og bremser jævnt."},"v1-3fb38d9106083684":{"src":"assets/voice/jeppe-neural-v1/v1-3fb38d9106083684.mp3","text":"Kører langsomt uden udstyr, fordi turen er kort."},"v1-3edca8236d7ed68a":{"src":"assets/voice/jeppe-neural-v1/v1-3edca8236d7ed68a.mp3","text":"Skoleklokken ringer også for din risikovurdering."},"v1-3da1f3a302c8c31e":{"src":"assets/voice/jeppe-neural-v1/v1-3da1f3a302c8c31e.mp3","text":"Spejle dækker ikke alle områder. Orientering, tegn og kontrol af blind vinkel skal ske før vognbaneskift."},"v1-40d4603b8a7ff0bc":{"src":"assets/voice/jeppe-neural-v1/v1-40d4603b8a7ff0bc.mp3","text":"Sænker farten før broen og svinget."},"v1-40856e8066103573":{"src":"assets/voice/jeppe-neural-v1/v1-40856e8066103573.mp3","text":"Klokken 20.00 lukker solo-vinduet uden rulletekster."},"v1-3fb8442038aabe44":{"src":"assets/voice/jeppe-neural-v1/v1-3fb8442038aabe44.mp3","text":"Gennemgår de praktiske færdigheder ved letbane i teorilokalet."},"v1-410bc388bccfd94e":{"src":"assets/voice/jeppe-neural-v1/v1-410bc388bccfd94e.mp3","text":"Vender gennem en åbning i midterrabatten."},"v1-41419651e32fb600":{"src":"assets/voice/jeppe-neural-v1/v1-41419651e32fb600.mp3","text":"Jeg må gennemføre påstigningen hensynsfuldt."},"v1-417980f16948ff67":{"src":"assets/voice/jeppe-neural-v1/v1-417980f16948ff67.mp3","text":"Åbner hurtigt, fordi bilen holder stille."},"v1-41f0c739a0911682":{"src":"assets/voice/jeppe-neural-v1/v1-41f0c739a0911682.mp3","text":"Må bruge båsen med havariblink."},"v1-44013d618cfb78aa":{"src":"assets/voice/jeppe-neural-v1/v1-44013d618cfb78aa.mp3","text":"Havariblink er ikke et “jeg må godt”-filter."},"v1-4455da1fcfd45e09":{"src":"assets/voice/jeppe-neural-v1/v1-4455da1fcfd45e09.mp3","text":"D 15 angiver, at tavlen skal passeres på den side, pilen peger."},"v1-443acb9be5970858":{"src":"assets/voice/jeppe-neural-v1/v1-443acb9be5970858.mp3","text":"Accelererer gennem feltet, fordi jeg allerede er i rundkørslen."},"v1-44108302eeaac2be":{"src":"assets/voice/jeppe-neural-v1/v1-44108302eeaac2be.mp3","text":"Hvad er korrekt om assistenten? På en klar vej viser bilens skiltegenkendelse 80, men du har netop passeret et tydeligt midlertidigt skilt med 50 ved vejarbejde."},"v1-450ed2b99a429529":{"src":"assets/voice/jeppe-neural-v1/v1-450ed2b99a429529.mp3","text":"Hvad skal ske før og efter turen? Du skal have en afsluttende praktisk lektion i afsnit 7.22. Kørelæreren og du har valgt rute, men har endnu ikke aftalt et konkret læringsmål eller planlagt opfølgning."},"v1-454c973e5987d469":{"src":"assets/voice/jeppe-neural-v1/v1-454c973e5987d469.mp3","text":"Må begynde at køre alene kl. 05.00."},"v1-45e897f2c0de3816":{"src":"assets/voice/jeppe-neural-v1/v1-45e897f2c0de3816.mp3","text":"Sænker farten og holder god afstand til arbejderne."},"v1-458d182c428994cc":{"src":"assets/voice/jeppe-neural-v1/v1-458d182c428994cc.mp3","text":"Toget accepterer ikke “køen flyttede sig ikke” som returpolitik."},"v1-459b296eaba9a096":{"src":"assets/voice/jeppe-neural-v1/v1-459b296eaba9a096.mp3","text":"Har du ret til at køre? Du har grønt lys, men krydset er blokeret af kø. Hvis du kører frem, vil bilen stå midt i krydset, når tværtrafikken får grønt."},"v1-45fe63c7c8095632":{"src":"assets/voice/jeppe-neural-v1/v1-45fe63c7c8095632.mp3","text":"Letbanen kan ikke swipe til en anden vognbane."},"v1-4671b892fb4a1b3b":{"src":"assets/voice/jeppe-neural-v1/v1-4671b892fb4a1b3b.mp3","text":"Skifter straks dæk helt op ad den kørende bane."},"v1-475d97ff6ce8bc25":{"src":"assets/voice/jeppe-neural-v1/v1-475d97ff6ce8bc25.mp3","text":"Grønt lys uden særlig venstrepil ophæver ikke pligten til at holde tilbage for modkørende. Den enkelte fører skal selv sikre frit udsyn og et tilstrækkeligt stort ophold."},"v1-487f70dd62d599a6":{"src":"assets/voice/jeppe-neural-v1/v1-487f70dd62d599a6.mp3","text":"Må bilen stå på fortov og cykelsti? I tættere bebygget område vil du stille en almindelig personbil med højre hjul på fortovet og delvist på cykelstien. Der er ingen bås eller tavle, som tillader det."},"v1-48a3bc1586a5ceed":{"src":"assets/voice/jeppe-neural-v1/v1-48a3bc1586a5ceed.mp3","text":"Bevarer plads til bilen foran."},"v1-48c01797fba15b59":{"src":"assets/voice/jeppe-neural-v1/v1-48c01797fba15b59.mp3","text":"Lader bilen stå eller får en egnet ledsager med."},"v1-4af6419d33c84f2e":{"src":"assets/voice/jeppe-neural-v1/v1-4af6419d33c84f2e.mp3","text":"Fjerner den tomme tagboks, når den ikke skal bruges."},"v1-4991175214860bfc":{"src":"assets/voice/jeppe-neural-v1/v1-4991175214860bfc.mp3","text":"Fortsætter uændret, til jeg ser et menneske."},"v1-4c86de2118353d69":{"src":"assets/voice/jeppe-neural-v1/v1-4c86de2118353d69.mp3","text":"Kører kun med positionslys."},"v1-4b01f09bf45b1211":{"src":"assets/voice/jeppe-neural-v1/v1-4b01f09bf45b1211.mp3","text":"Promille og improvisation er et elendigt makkerpar."},"v1-4b5b2b7149c6b920":{"src":"assets/voice/jeppe-neural-v1/v1-4b5b2b7149c6b920.mp3","text":"Må du standse før feltet? Du vil standse 3 m før et fodgængerfelt for at sætte en voksen passager af. Der er ingen afmærket bås eller anden særlig tilladelse."},"v1-4c17878acad4e38b":{"src":"assets/voice/jeppe-neural-v1/v1-4c17878acad4e38b.mp3","text":"Må du bruge handicapbåsen kort? En bås er afmærket med E 33 og handicapsymbol. Du har ikke et gyldigt parkeringskort og vil holde i to minutter for at hente kaffe."},"v1-4ec13b6c8a9fbb30":{"src":"assets/voice/jeppe-neural-v1/v1-4ec13b6c8a9fbb30.mp3","text":"Orienterer mig igen lige før igangsætning."},"v1-4f707038986cfcf3":{"src":"assets/voice/jeppe-neural-v1/v1-4f707038986cfcf3.mp3","text":"Følger den gule midlertidige afmærkning."},"v1-4e4b759f2480668e":{"src":"assets/voice/jeppe-neural-v1/v1-4e4b759f2480668e.mp3","text":"Hvilken side vælger du? Ved en helle viser D 15 Påbudt passage en hvid pil skråt ned mod venstre. Kørebanen til venstre for tavlen er åben."},"v1-4d88cd261ce707f5":{"src":"assets/voice/jeppe-neural-v1/v1-4d88cd261ce707f5.mp3","text":"Hvem holder du tilbage for ved hajtænderne? Du vil lige over et kryds med hajtænder. En cyklist kommer fra højre på den vej, du skal krydse, og vil fortsætte ligeud."},"v1-4ffacb30901f5efb":{"src":"assets/voice/jeppe-neural-v1/v1-4ffacb30901f5efb.mp3","text":"Tavlen er et loft, ikke en KPI."},"v1-50017d37df28d89b":{"src":"assets/voice/jeppe-neural-v1/v1-50017d37df28d89b.mp3","text":"River straks rattet kraftigt til venstre."},"v1-4aa1885da0c20918":{"src":"assets/voice/jeppe-neural-v1/v1-4aa1885da0c20918.mp3","text":"Hvilke linjer følger du? Ved et vejarbejde leder midlertidige gule linjer trafikken mod venstre, mens de gamle hvide linjer fortsætter ligeud mod et afspærret område med vejarbejdere."},"v1-504c1dbc6afd53e3":{"src":"assets/voice/jeppe-neural-v1/v1-504c1dbc6afd53e3.mp3","text":"Må den 17-årige køre? En 17-årig med gyldigt dansk B-kørekort vil køre alene i Danmark kl. 19.45 og forventer at være hjemme kl. 20.10. Der er ingen ledsager med."},"v1-521e60a692055a19":{"src":"assets/voice/jeppe-neural-v1/v1-521e60a692055a19.mp3","text":"Ser kun efter biler, fordi de modkørende allerede er passeret."},"v1-54a4e6198e3d67af":{"src":"assets/voice/jeppe-neural-v1/v1-54a4e6198e3d67af.mp3","text":"Ved vognbaneskift har den skiftende fører pligt til at sikre, at manøvren kan ske sikkert."},"v1-542ac32afedebea6":{"src":"assets/voice/jeppe-neural-v1/v1-542ac32afedebea6.mp3","text":"Første spejlkig har ingen udløbsgaranti."},"v1-54abbe011c6ca8be":{"src":"assets/voice/jeppe-neural-v1/v1-54abbe011c6ca8be.mp3","text":"Holder tilbage for både cyklist og bil."},"v1-555e2e793fa38309":{"src":"assets/voice/jeppe-neural-v1/v1-555e2e793fa38309.mp3","text":"Sænker farten før bladene og svinget."},"v1-56e8411195003781":{"src":"assets/voice/jeppe-neural-v1/v1-56e8411195003781.mp3","text":"Børn under 135 cm skal som hovedregel bruge godkendt udstyr tilpasset højde og vægt. Føreren er ansvarlig for, at passagerer under 15 år er korrekt sikret."},"v1-56e3374c0981631c":{"src":"assets/voice/jeppe-neural-v1/v1-56e3374c0981631c.mp3","text":"Korrekt indstilling giver kontrol og udsyn. Løse genstande kan blive farlige ved hård opbremsning."},"v1-5777d034a11c2072":{"src":"assets/voice/jeppe-neural-v1/v1-5777d034a11c2072.mp3","text":"Må du krydse sporet nu? Du nærmer dig et kryds over letbanespor. Signalet for din kørselsretning viser rødt, og et letbanetog nærmer sig på sporet. Der er plads på den anden side, men ingen grøn pil eller anden tilladelse."},"v1-578d93573e5dc725":{"src":"assets/voice/jeppe-neural-v1/v1-578d93573e5dc725.mp3","text":"Holder tilbage for den gående."},"v1-57abee4d290e9173":{"src":"assets/voice/jeppe-neural-v1/v1-57abee4d290e9173.mp3","text":"Standser bilen helt ved stoplinjen."},"v1-59caddd12d6c56e1":{"src":"assets/voice/jeppe-neural-v1/v1-59caddd12d6c56e1.mp3","text":"Laver store ratudslag under hård bremsning uden behov."},"v1-5a529a1b5cea2d3a":{"src":"assets/voice/jeppe-neural-v1/v1-5a529a1b5cea2d3a.mp3","text":"Hvad gør du ved det uregulerede felt? Du nærmer dig et ureguleret fodgængerfelt. En gående står ved kanten og er tydeligt på vej ud i feltet."},"v1-5c328c66dcf1febf":{"src":"assets/voice/jeppe-neural-v1/v1-5c328c66dcf1febf.mp3","text":"Uden anden regulering gælder højre vigepligt. Man skal stadig være klar på, at andre kan tage fejl."},"v1-5b231737267f2d11":{"src":"assets/voice/jeppe-neural-v1/v1-5b231737267f2d11.mp3","text":"Bevarer en sikker plads bag den langsomme bil."},"v1-5a5e6ff788134298":{"src":"assets/voice/jeppe-neural-v1/v1-5a5e6ff788134298.mp3","text":"“Det er kun rundt om hjørnet” spænder ingen sele."},"v1-5c9fd41d7da6c57a":{"src":"assets/voice/jeppe-neural-v1/v1-5c9fd41d7da6c57a.mp3","text":"Hvad bør du gøre? Under kørsel tænder en rød advarselslampe for olietryk, og motoren begynder at lyde usædvanligt. Du kan straks holde sikkert ind."},"v1-5cb5e51fe9fdc812":{"src":"assets/voice/jeppe-neural-v1/v1-5cb5e51fe9fdc812.mp3","text":"Springer standsningen over, fordi vejen ser tom ud."},"v1-6085b3789d1c7fa8":{"src":"assets/voice/jeppe-neural-v1/v1-6085b3789d1c7fa8.mp3","text":"Bevarer mulighed for at reagere."},"v1-5ddd2297a2e21aa7":{"src":"assets/voice/jeppe-neural-v1/v1-5ddd2297a2e21aa7.mp3","text":"Hvordan skifter du bane? På en firesporet byvej viser spejlene fri bane. En motorcykel kan have placeret sig i din venstre blinde vinkel."},"v1-6145d1685c7e9ba9":{"src":"assets/voice/jeppe-neural-v1/v1-6145d1685c7e9ba9.mp3","text":"Kører med meget lav fart og normalt under 15 km/t."},"v1-61d649322f1f3385":{"src":"assets/voice/jeppe-neural-v1/v1-61d649322f1f3385.mp3","text":"Blinklyset har sendt en kalenderinvitation, ikke en tvangsordre."},"v1-61796843124533f0":{"src":"assets/voice/jeppe-neural-v1/v1-61796843124533f0.mp3","text":"Pilen er ikke en kreativ skriveøvelse."},"v1-62c70211a45b9d6c":{"src":"assets/voice/jeppe-neural-v1/v1-62c70211a45b9d6c.mp3","text":"Første stop var loven; næste kan være sund fornuft."},"v1-625e58bd7950f446":{"src":"assets/voice/jeppe-neural-v1/v1-625e58bd7950f446.mp3","text":"Tilkald hjælp og hjælper tilskadekomne efter evne."},"v1-6422f5bed02288d3":{"src":"assets/voice/jeppe-neural-v1/v1-6422f5bed02288d3.mp3","text":"Antager, at bilen helt sikkert drejer nu."},"v1-632b1b7606c6dcc7":{"src":"assets/voice/jeppe-neural-v1/v1-632b1b7606c6dcc7.mp3","text":"Blind vinkel er et område, ikke en personlighedstype."},"v1-641fa999c238704e":{"src":"assets/voice/jeppe-neural-v1/v1-641fa999c238704e.mp3","text":"Svinger, fordi cyklisten var bagved ved første blik."},"v1-63db53c64147af15":{"src":"assets/voice/jeppe-neural-v1/v1-63db53c64147af15.mp3","text":"B 11 og hajtænder betyder ubetinget vigepligt. Fuldt stop kræves ikke i sig selv; det kræves ved B 13 eller når situationen gør standsning nødvendig."},"v1-642347b4e79f0a94":{"src":"assets/voice/jeppe-neural-v1/v1-642347b4e79f0a94.mp3","text":"Holder retningen roligt langs kanten."},"v1-65b4de82539c8389":{"src":"assets/voice/jeppe-neural-v1/v1-65b4de82539c8389.mp3","text":"Forventer, at barnet straks forlader vejarealet."},"v1-647aae592a9396ad":{"src":"assets/voice/jeppe-neural-v1/v1-647aae592a9396ad.mp3","text":"Bliver bag traktoren."},"v1-656ec966ed7ddf8d":{"src":"assets/voice/jeppe-neural-v1/v1-656ec966ed7ddf8d.mp3","text":"Hvordan gennemfører du svinget? Du vil dreje til højre over en cykelsti. En cyklist fortsætter ligeud ved siden af dig, og der er fri vej foran."},"v1-678ad1568389956d":{"src":"assets/voice/jeppe-neural-v1/v1-678ad1568389956d.mp3","text":"Vurderer min køreevne efter festen."},"v1-66aa8a16b7af44ca":{"src":"assets/voice/jeppe-neural-v1/v1-66aa8a16b7af44ca.mp3","text":"Besvare alle fire ja/nej-valg, fordi et manglende valg tæller som app-fejl."},"v1-6783452eac33e8fe":{"src":"assets/voice/jeppe-neural-v1/v1-6783452eac33e8fe.mp3","text":"Krydset måles fra kanten, ikke fra dets følelsesmæssige centrum."},"v1-65ed15a2582f51e7":{"src":"assets/voice/jeppe-neural-v1/v1-65ed15a2582f51e7.mp3","text":"Hvem skal du holde tilbage for? Efter at de modkørende er passeret, vil du afslutte venstresvinget. På den vej, du drejer ind på, krydser en gående kørebanen, og en cyklist nærmer sig fra højre på en tydeligt afmærket dobbeltrettet cykelsti."},"v1-6b79ce74135085e8":{"src":"assets/voice/jeppe-neural-v1/v1-6b79ce74135085e8.mp3","text":"Kører langsommere end 80 efter forholdene."},"v1-6834eaa927e288a1":{"src":"assets/voice/jeppe-neural-v1/v1-6834eaa927e288a1.mp3","text":"Beskeden overlever. Det bør alle andre også."},"v1-67df1d3ee9e33400":{"src":"assets/voice/jeppe-neural-v1/v1-67df1d3ee9e33400.mp3","text":"Antager, at ligeudkørsel altid giver fortrinsret."},"v1-686b54658f2bb142":{"src":"assets/voice/jeppe-neural-v1/v1-686b54658f2bb142.mp3","text":"Bagkofangeren er ikke din personlige træner."},"v1-6e5ad329ba84aaba":{"src":"assets/voice/jeppe-neural-v1/v1-6e5ad329ba84aaba.mp3","text":"Udelader hele emnet, fordi praktisk kørsel ikke kan nås."},"v1-6d74e1499c7a89d1":{"src":"assets/voice/jeppe-neural-v1/v1-6d74e1499c7a89d1.mp3","text":"Drikker lidt og kører ekstra langsomt."},"v1-6d098ab7e0492b8e":{"src":"assets/voice/jeppe-neural-v1/v1-6d098ab7e0492b8e.mp3","text":"Betragter et korrekt appsvar som gennemført praktisk øvelse."},"v1-6d9ebbd6663c5fe8":{"src":"assets/voice/jeppe-neural-v1/v1-6d9ebbd6663c5fe8.mp3","text":"Har fortrinsret, fordi tankstationen har en bred udkørsel."},"v1-6e645dd703614de0":{"src":"assets/voice/jeppe-neural-v1/v1-6e645dd703614de0.mp3","text":"Skal vente til kl. 05.01."},"v1-6ef013e83e514a9c":{"src":"assets/voice/jeppe-neural-v1/v1-6ef013e83e514a9c.mp3","text":"Skal fortsat følge alle almindelige førerpligter."},"v1-6ef56fc2058548b8":{"src":"assets/voice/jeppe-neural-v1/v1-6ef56fc2058548b8.mp3","text":"Må standse, fordi afsætningen tager under tre minutter."},"v1-6eeb198c51239eb1":{"src":"assets/voice/jeppe-neural-v1/v1-6eeb198c51239eb1.mp3","text":"Hvordan reagerer du på presset? En bilist ligger tæt bag dig på en smal, våd landevej. Du kører efter forholdene og under den skiltede maksimumshastighed."},"v1-6fccad032e6c793f":{"src":"assets/voice/jeppe-neural-v1/v1-6fccad032e6c793f.mp3","text":"Har kun vigepligt for trafikken fra venstre."},"v1-718755d05bc5978c":{"src":"assets/voice/jeppe-neural-v1/v1-718755d05bc5978c.mp3","text":"60 er et loft, ikke et abonnement."},"v1-6fc7b41723a202d4":{"src":"assets/voice/jeppe-neural-v1/v1-6fc7b41723a202d4.mp3","text":"Lange køretøjer kan trække ud før et snævert sving og har blinde zoner. Giv plads og undgå indersiden."},"v1-6f7ae5e594b52490":{"src":"assets/voice/jeppe-neural-v1/v1-6f7ae5e594b52490.mp3","text":"Hvordan kører du på den glatte vej? Det fryser. Vejen ser mest tør ud, men en skyggefuld bro kan være glat, og du nærmer dig et sving."},"v1-71e662eaefc93d15":{"src":"assets/voice/jeppe-neural-v1/v1-71e662eaefc93d15.mp3","text":"Accepterer 30 cm, fordi bilen allerede står parallelt."},"v1-743945247c5b3896":{"src":"assets/voice/jeppe-neural-v1/v1-743945247c5b3896.mp3","text":"Sænker farten og søger efter børn mellem bilerne."},"v1-72e13e35984c97e6":{"src":"assets/voice/jeppe-neural-v1/v1-72e13e35984c97e6.mp3","text":"Blikretning påvirker styringen. Lav fart og et blik mod den ønskede kurs giver bedre kontrol."},"v1-731f421ddf2e52f3":{"src":"assets/voice/jeppe-neural-v1/v1-731f421ddf2e52f3.mp3","text":"Stoppligten opfyldes ved stoplinjen. Hvis der ikke er udsyn, må du derefter liste frem og om nødvendigt standse igen, mens den ubetingede vigepligt fortsat gælder."},"v1-7456656865fbfd19":{"src":"assets/voice/jeppe-neural-v1/v1-7456656865fbfd19.mp3","text":"Cykelgaden har ikke bestilt en bilbaseret trommesolo."},"v1-757225a803708514":{"src":"assets/voice/jeppe-neural-v1/v1-757225a803708514.mp3","text":"Sænker farten og øger afstanden."},"v1-75c4155c5a2242ce":{"src":"assets/voice/jeppe-neural-v1/v1-75c4155c5a2242ce.mp3","text":"Giver tydeligt tegn i god tid."},"v1-748ec4dd62f938e7":{"src":"assets/voice/jeppe-neural-v1/v1-748ec4dd62f938e7.mp3","text":"Hvad forebygger udskridning? Der ligger løse blade i et skarpt sving. Du kan se dem i god tid og har fri bane bag dig."},"v1-7680cdec522d1d3f":{"src":"assets/voice/jeppe-neural-v1/v1-7680cdec522d1d3f.mp3","text":"STOP er usædvanligt tydelig kommunikation."},"v1-7702634c703ec982":{"src":"assets/voice/jeppe-neural-v1/v1-7702634c703ec982.mp3","text":"Antager, at ét lys altid betyder lav fart."},"v1-75ffd963972d7661":{"src":"assets/voice/jeppe-neural-v1/v1-75ffd963972d7661.mp3","text":"Efter præcis tre minutter bliver aktiv påstigning automatisk parkering."},"v1-7714177be24c8152":{"src":"assets/voice/jeppe-neural-v1/v1-7714177be24c8152.mp3","text":"NATKØRSEL-bedømmelse: Et scenarie tæller som én app-fejl, hvis ét eller flere af de fire valg er forkerte eller mangler. Færdselsstyrelsen oplyser højst fem fejl for bestået, men den offentlige side beskriver ikke den præcise optælling af flere fejlvalg i samme scenarie."},"v1-774bc70bd14619bb":{"src":"assets/voice/jeppe-neural-v1/v1-774bc70bd14619bb.mp3","text":"Her er bilen gæst. Barnet har tydeligvis booket hele gulvet."},"v1-7768eceb0d3f1eda":{"src":"assets/voice/jeppe-neural-v1/v1-7768eceb0d3f1eda.mp3","text":"Bogmærket er en huskeseddel, ikke en tryllestav."},"v1-78ddccf919f13d00":{"src":"assets/voice/jeppe-neural-v1/v1-78ddccf919f13d00.mp3","text":"Ruller langsomt over linjen uden stop."},"v1-7895a966250c1a8a":{"src":"assets/voice/jeppe-neural-v1/v1-7895a966250c1a8a.mp3","text":"Håndholdt brug er forbudt, og også fastgjorte skærme kan distrahere. Betjening må ikke fjerne opmærksomheden fra trafikken."},"v1-79ae8d48d6eee6c9":{"src":"assets/voice/jeppe-neural-v1/v1-79ae8d48d6eee6c9.mp3","text":"Klokken 05.00 trykker reglen på start."},"v1-79fe375e9a6c4d9e":{"src":"assets/voice/jeppe-neural-v1/v1-79fe375e9a6c4d9e.mp3","text":"Kører op på lastbilens højre side."},"v1-790f4ab78e59b654":{"src":"assets/voice/jeppe-neural-v1/v1-790f4ab78e59b654.mp3","text":"Ser kun på højre forskærm og ignorerer resten af området."},"v1-798a4fd4ad0d682a":{"src":"assets/voice/jeppe-neural-v1/v1-798a4fd4ad0d682a.mp3","text":"E 33 tillader parkering, men undertavlens vilkår og tidsrum begrænser tilladelsen. Påbudt parkeringsskive skal anvendes."},"v1-7a3874e3c5e4c663":{"src":"assets/voice/jeppe-neural-v1/v1-7a3874e3c5e4c663.mp3","text":"Følger det aktuelle, synlige skilt."},"v1-7a0f92f1cdeb83df":{"src":"assets/voice/jeppe-neural-v1/v1-7a0f92f1cdeb83df.mp3","text":"Holder afstand og giver lastbilen plads."},"v1-7a2d26fb6007db29":{"src":"assets/voice/jeppe-neural-v1/v1-7a2d26fb6007db29.mp3","text":"Hajtænder giver ubetinget vigepligt for al kørende færdsel på den vej, du kører ind på eller over, også cyklister."},"v1-7a4efc8a740a7035":{"src":"assets/voice/jeppe-neural-v1/v1-7a4efc8a740a7035.mp3","text":"Fortsætter sikkert og lader om nødvendigt GPS-ruten blive beregnet om."},"v1-7a7b06aa23d4dc96":{"src":"assets/voice/jeppe-neural-v1/v1-7a7b06aa23d4dc96.mp3","text":"Lastbilen danser ikke; den har bare en meget lang krop."},"v1-7af5ef4b3188dae4":{"src":"assets/voice/jeppe-neural-v1/v1-7af5ef4b3188dae4.mp3","text":"Forventer, at cyklisten kører udenom døren."},"v1-7ac99a9a0a877807":{"src":"assets/voice/jeppe-neural-v1/v1-7ac99a9a0a877807.mp3","text":"Vejens selvtillid måles ikke i centimeter."},"v1-7a616ed387f8abaa":{"src":"assets/voice/jeppe-neural-v1/v1-7a616ed387f8abaa.mp3","text":"Tegnet viser en hensigt, men kan være glemt eller ændret. Bedøm hele situationen."},"v1-7c43275e0e5b47fc":{"src":"assets/voice/jeppe-neural-v1/v1-7c43275e0e5b47fc.mp3","text":"Har kun vigepligt for biler."},"v1-7e19eacc72404d65":{"src":"assets/voice/jeppe-neural-v1/v1-7e19eacc72404d65.mp3","text":"Tidsgrænsen gælder først efter kl. 18."},"v1-7d3395b5f2235403":{"src":"assets/voice/jeppe-neural-v1/v1-7d3395b5f2235403.mp3","text":"Kører mellem gul og hvid linje efter eget valg."},"v1-7e14f78ba2c537cd":{"src":"assets/voice/jeppe-neural-v1/v1-7e14f78ba2c537cd.mp3","text":"Hvordan skaber du plads? På en smal vej står en varebil parkeret i din side. En modkørende er allerede tæt på indsnævringen."},"v1-7e75a51a9895d623":{"src":"assets/voice/jeppe-neural-v1/v1-7e75a51a9895d623.mp3","text":"Blinklyset er et signal, ikke en notar."},"v1-7e9cb8d4fbf807e3":{"src":"assets/voice/jeppe-neural-v1/v1-7e9cb8d4fbf807e3.mp3","text":"Fortsætter til næste by, fordi røde lamper er vejledende."},"v1-7f211a66a53fee3c":{"src":"assets/voice/jeppe-neural-v1/v1-7f211a66a53fee3c.mp3","text":"Kører hurtigere for at være kortere tid i regnen."},"v1-7ee058f4958556f4":{"src":"assets/voice/jeppe-neural-v1/v1-7ee058f4958556f4.mp3","text":"Den højresvingende skal holde tilbage for den ligeudkørende cyklist langs vejen."},"v1-7f3d8d2fc903521b":{"src":"assets/voice/jeppe-neural-v1/v1-7f3d8d2fc903521b.mp3","text":"Det regnes som standsning, ikke parkering."},"v1-7fcb9fab05875a87":{"src":"assets/voice/jeppe-neural-v1/v1-7fcb9fab05875a87.mp3","text":"Må standse med havariblinket tændt."},"v1-7f5e4ea72a5859e3":{"src":"assets/voice/jeppe-neural-v1/v1-7f5e4ea72a5859e3.mp3","text":"Forlader pladsen senest efter den angivne parkeringstid."},"v1-7fb70444740fbe17":{"src":"assets/voice/jeppe-neural-v1/v1-7fb70444740fbe17.mp3","text":"Solo-kørsel er tilladt i Danmark kl. 05.00-20.00. Fra kl. 20.00 kræves ledsager, uanset starttidspunkt."},"v1-816983b03da64559":{"src":"assets/voice/jeppe-neural-v1/v1-816983b03da64559.mp3","text":"Dækket har afleveret sin opsigelse skriftligt."},"v1-8143c8426c060590":{"src":"assets/voice/jeppe-neural-v1/v1-8143c8426c060590.mp3","text":"Havariblink er lys, ikke diplomatisk immunitet."},"v1-829f912f46e326d7":{"src":"assets/voice/jeppe-neural-v1/v1-829f912f46e326d7.mp3","text":"Lader kassen stå løs, fordi bagklappen er lukket."},"v1-815aab4ddf91e80f":{"src":"assets/voice/jeppe-neural-v1/v1-815aab4ddf91e80f.mp3","text":"Anerkender, at træthed kan gøre kørslen uforsvarlig."},"v1-831450a5cecd46ad":{"src":"assets/voice/jeppe-neural-v1/v1-831450a5cecd46ad.mp3","text":"Passerer tavlen på venstre side."},"v1-8315f34e38d549dc":{"src":"assets/voice/jeppe-neural-v1/v1-8315f34e38d549dc.mp3","text":"Bliver stående uden at undersøge sikre muligheder for at give plads."},"v1-83123331aeb20b98":{"src":"assets/voice/jeppe-neural-v1/v1-83123331aeb20b98.mp3","text":"Parallel er godt; parallel i nabopostnummeret er stadig for langt væk."},"v1-8310a31aedc5d7b3":{"src":"assets/voice/jeppe-neural-v1/v1-8310a31aedc5d7b3.mp3","text":"Dårlig sigt kræver korrekt lys, lavere fart og større afstand. Særligt kørelys er ikke nok i lygtetændingstiden."},"v1-8405cc32332a8cc7":{"src":"assets/voice/jeppe-neural-v1/v1-8405cc32332a8cc7.mp3","text":"Giver tegn i god tid, men venter stadig på cyklisten."},"v1-8402e67d57a29fa2":{"src":"assets/voice/jeppe-neural-v1/v1-8402e67d57a29fa2.mp3","text":"Både standsning og parkering er forbudt på stedet."},"v1-85e21ada84e47007":{"src":"assets/voice/jeppe-neural-v1/v1-85e21ada84e47007.mp3","text":"Sætter farten op for at konkurrere om pladsen."},"v1-846e061a4b07c72f":{"src":"assets/voice/jeppe-neural-v1/v1-846e061a4b07c72f.mp3","text":"Ved uheld skal man standse, hjælpe og forebygge nye uheld. Egen sikkerhed og synlig sikring er en del af hjælpen."},"v1-86239525317c6bdf":{"src":"assets/voice/jeppe-neural-v1/v1-86239525317c6bdf.mp3","text":"Kaffetørst står ikke på parkeringskortet."},"v1-864fd53b0b6e3266":{"src":"assets/voice/jeppe-neural-v1/v1-864fd53b0b6e3266.mp3","text":"Vælger høj fart, så øvelsen ligner planens risikosituation."},"v1-8768cc3c4780da0c":{"src":"assets/voice/jeppe-neural-v1/v1-8768cc3c4780da0c.mp3","text":"Bliver holdende, til barnet har set bilen, givet plads og ikke kan komme farligt nær den."},"v1-85fae6ed2b9e8d27":{"src":"assets/voice/jeppe-neural-v1/v1-85fae6ed2b9e8d27.mp3","text":"Læser hurtigt, fordi telefonen sidder i en holder."},"v1-87a726896fa45805":{"src":"assets/voice/jeppe-neural-v1/v1-87a726896fa45805.mp3","text":"Afventer nyt tegn fra betjenten."},"v1-879c0683c82a5014":{"src":"assets/voice/jeppe-neural-v1/v1-879c0683c82a5014.mp3","text":"Må fortsætte alene, fordi turen begyndte før kl. 20.00."},"v1-88a65c8acf45a913":{"src":"assets/voice/jeppe-neural-v1/v1-88a65c8acf45a913.mp3","text":"Sænker straks farten og er klar til at standse."},"v1-88c7a07c016ecc0f":{"src":"assets/voice/jeppe-neural-v1/v1-88c7a07c016ecc0f.mp3","text":"Hvad forudser du? En lang lastbil foran dig blinker til højre ved et snævert hjørne og ligger lidt mod venstre for at få plads."},"v1-89c2f9f0a44e1510":{"src":"assets/voice/jeppe-neural-v1/v1-89c2f9f0a44e1510.mp3","text":"Holder selv øje med vejen."},"v1-88eba1c492468244":{"src":"assets/voice/jeppe-neural-v1/v1-88eba1c492468244.mp3","text":"Keglen vandt stirrekonkurrencen."},"v1-8969c2ac30096eb4":{"src":"assets/voice/jeppe-neural-v1/v1-8969c2ac30096eb4.mp3","text":"Hvem følger du? Lyset viser grønt, men en uniformeret politibetjent står i krydset og giver dig tydeligt tegn til at standse."},"v1-89cd46b2488b19e2":{"src":"assets/voice/jeppe-neural-v1/v1-89cd46b2488b19e2.mp3","text":"I et opholds- og legeområde sker motorkørsel på de gåendes betingelser og normalt med hastighed under 15 km/t. Føreren fortsætter først, når barnet har set bilen og givet plads, og ingen kan komme farligt nær den. Parkering må kun ske på særligt afmærkede pladser."},"v1-8b1406cb87cbb062":{"src":"assets/voice/jeppe-neural-v1/v1-8b1406cb87cbb062.mp3","text":"Måler kun turens kvalitet på, hvor hurtigt ruten blev kørt."},"v1-8b0ca3a23df101f7":{"src":"assets/voice/jeppe-neural-v1/v1-8b0ca3a23df101f7.mp3","text":"Stopuret kan skelne ordene, men det kan ikke flytte bilen."},"v1-89d174534316bd88":{"src":"assets/voice/jeppe-neural-v1/v1-89d174534316bd88.mp3","text":"Forventer, at bilen i venstre bane altid skal lukke mig ind."},"v1-8ac5e8ad879abd55":{"src":"assets/voice/jeppe-neural-v1/v1-8ac5e8ad879abd55.mp3","text":"Beholder forreste kørelys alene, fordi det er dag."},"v1-8bc69d8ab3a48dd1":{"src":"assets/voice/jeppe-neural-v1/v1-8bc69d8ab3a48dd1.mp3","text":"Venter på motorcyklen."},"v1-8b680b0f8e2c2dc9":{"src":"assets/voice/jeppe-neural-v1/v1-8b680b0f8e2c2dc9.mp3","text":"Kører tæt forbi, fordi blinklyset binder føreren juridisk."},"v1-8b398c8966c32b0f":{"src":"assets/voice/jeppe-neural-v1/v1-8b398c8966c32b0f.mp3","text":"Standser sikkert og sikrer stedet."},"v1-8c8454356fad71e3":{"src":"assets/voice/jeppe-neural-v1/v1-8c8454356fad71e3.mp3","text":"Tilpasser kørsel og afstand til den ændrede vægt."},"v1-8d12518898e0352b":{"src":"assets/voice/jeppe-neural-v1/v1-8d12518898e0352b.mp3","text":"Blokerer krydset og tænder havariblink."},"v1-8d135fb9090cffc3":{"src":"assets/voice/jeppe-neural-v1/v1-8d135fb9090cffc3.mp3","text":"Dytter og antager derefter fri bane."},"v1-8ccc7b345af1f576":{"src":"assets/voice/jeppe-neural-v1/v1-8ccc7b345af1f576.mp3","text":"Lader den bagvedkørende gennemføre først."},"v1-8cfb92129ea59768":{"src":"assets/voice/jeppe-neural-v1/v1-8cfb92129ea59768.mp3","text":"Hvad kræver B 11? Du møder B 11 Ubetinget vigepligt og hajtænder ved et overskueligt kryds. Der er ingen trafik på den vej, du vil køre ind på."},"v1-8f0d6cdd6d1585c4":{"src":"assets/voice/jeppe-neural-v1/v1-8f0d6cdd6d1585c4.mp3","text":"Svinger først, når cykelstien er fri."},"v1-8f3ab1393cfc34ce":{"src":"assets/voice/jeppe-neural-v1/v1-8f3ab1393cfc34ce.mp3","text":"Ruller langsomt videre, fordi udsynet er godt."},"v1-8d23e639b571c2b0":{"src":"assets/voice/jeppe-neural-v1/v1-8d23e639b571c2b0.mp3","text":"E 33 uden videre giver ubegrænset parkering."},"v1-8d76b303d320b172":{"src":"assets/voice/jeppe-neural-v1/v1-8d76b303d320b172.mp3","text":"Hvorfor sænke farten? Du nærmer dig et uoverskueligt vejsving hurtigere end normalt, men er endnu på den lige strækning med godt vejgreb."},"v1-91839075f5e75633":{"src":"assets/voice/jeppe-neural-v1/v1-91839075f5e75633.mp3","text":"Åbner vinduet og regner problemet for løst."},"v1-8fecb3d9fdf016e9":{"src":"assets/voice/jeppe-neural-v1/v1-8fecb3d9fdf016e9.mp3","text":"Det er altid parkering, når motoren er slukket."},"v1-9028ac1e6e1352f6":{"src":"assets/voice/jeppe-neural-v1/v1-9028ac1e6e1352f6.mp3","text":"Bruger appteksten som tilladelse til selvtræning."},"v1-90b52d6ec76a8be3":{"src":"assets/voice/jeppe-neural-v1/v1-90b52d6ec76a8be3.mp3","text":"Er slutstillingen godkendt? Efter forlæns parkering på lukket øvelsesplads står bilen parallelt med højre vejkant. Højre hjul er 30 cm fra kanten. Kørelæreren beder dig vurdere resultatet."},"v1-930e025ef9f93813":{"src":"assets/voice/jeppe-neural-v1/v1-930e025ef9f93813.mp3","text":"Lader bilen stå, hvis jeg drikker."},"v1-93cf7802f2d9111c":{"src":"assets/voice/jeppe-neural-v1/v1-93cf7802f2d9111c.mp3","text":"Kontrollerer den blinde vinkel før skiftet."},"v1-93f78d49e15d1143":{"src":"assets/voice/jeppe-neural-v1/v1-93f78d49e15d1143.mp3","text":"Fysik tilbyder ingen premium-undtagelse."},"v1-928c3c27cc78d620":{"src":"assets/voice/jeppe-neural-v1/v1-928c3c27cc78d620.mp3","text":"Kan du overhale? Du ligger bag en traktor på en tosporet landevej. Kort fremme begynder en bakketop, og du kan ikke se vejforløbet bag den."},"v1-9570b8314a5de16e":{"src":"assets/voice/jeppe-neural-v1/v1-9570b8314a5de16e.mp3","text":"Fikserer blikket endnu hårdere på keglen."},"v1-946cc719d8104f11":{"src":"assets/voice/jeppe-neural-v1/v1-946cc719d8104f11.mp3","text":"Hver situation skal have fire udsagn, hvor mindst ét er korrekt."},"v1-95351e0262ff4eb6":{"src":"assets/voice/jeppe-neural-v1/v1-95351e0262ff4eb6.mp3","text":"STOP kræver fuld standsning, også når vejen ser fri ud. Derefter gælder vigepligten fortsat."},"v1-945527fcda0afd84":{"src":"assets/voice/jeppe-neural-v1/v1-945527fcda0afd84.mp3","text":"Er det parkering? På en lovlig vejkant uden tavler eller andre forbud bliver du siddende i bilen og venter i to minutter på en passager. Du skaber ikke fare eller ulempe."},"v1-958ead40c9c3affb":{"src":"assets/voice/jeppe-neural-v1/v1-958ead40c9c3affb.mp3","text":"Bliver bag cyklisterne uden at presse dem."},"v1-980ad8575f938071":{"src":"assets/voice/jeppe-neural-v1/v1-980ad8575f938071.mp3","text":"Starter overhalingen og vurderer senere."},"v1-976336fe5d3195b2":{"src":"assets/voice/jeppe-neural-v1/v1-976336fe5d3195b2.mp3","text":"Følger tæt efter bilen foran uden selv at kontrollere modkørende."},"v1-97c934790ebb13a0":{"src":"assets/voice/jeppe-neural-v1/v1-97c934790ebb13a0.mp3","text":"Hvad vælger du? En bold triller ud mellem parkerede biler foran dig. Du kan ikke se, hvem der har sparket den."},"v1-9830b69721308a04":{"src":"assets/voice/jeppe-neural-v1/v1-9830b69721308a04.mp3","text":"Holder tilbage for cyklisten."},"v1-98b7848f45e58cbd":{"src":"assets/voice/jeppe-neural-v1/v1-98b7848f45e58cbd.mp3","text":"En bestået teoriprøve alene giver ret til at køre."},"v1-9865de7ac0759440":{"src":"assets/voice/jeppe-neural-v1/v1-9865de7ac0759440.mp3","text":"Følger et særskilt signal, der kun gælder letbanen."},"v1-986823d2296a7ad9":{"src":"assets/voice/jeppe-neural-v1/v1-986823d2296a7ad9.mp3","text":"Bakning og vending er forbudt på motorvej og dens til- og frakørsler. Kør videre til næste afkørsel."},"v1-99c300533925392f":{"src":"assets/voice/jeppe-neural-v1/v1-99c300533925392f.mp3","text":"Kommentarfeltet kan ikke lægge en forbinding."},"v1-990aa68496c0eb01":{"src":"assets/voice/jeppe-neural-v1/v1-990aa68496c0eb01.mp3","text":"Bruger kun positionslys under kørslen."},"v1-99107d2a5e482851":{"src":"assets/voice/jeppe-neural-v1/v1-99107d2a5e482851.mp3","text":"Bremser hårdt midt i svinget for at teste grebet."},"v1-99260bdd98cb317d":{"src":"assets/voice/jeppe-neural-v1/v1-99260bdd98cb317d.mp3","text":"Betragter navigation som erstatning for egen orientering."},"v1-9a149d26f0132d19":{"src":"assets/voice/jeppe-neural-v1/v1-9a149d26f0132d19.mp3","text":"Keglerne tager ikke skade af langsom beslutningskraft."},"v1-9a9009227eb49726":{"src":"assets/voice/jeppe-neural-v1/v1-9a9009227eb49726.mp3","text":"Stoler alene på kameraet."},"v1-99eb96f265397108":{"src":"assets/voice/jeppe-neural-v1/v1-99eb96f265397108.mp3","text":"Klokken 20.00 laver reglen et hårdt sceneskift."},"v1-9b8689328c2ce468":{"src":"assets/voice/jeppe-neural-v1/v1-9b8689328c2ce468.mp3","text":"Har automatisk fortrinsret, fordi min vej fortsætter visuelt."},"v1-9ba7e5921c4ecc1e":{"src":"assets/voice/jeppe-neural-v1/v1-9ba7e5921c4ecc1e.mp3","text":"Udsagn 3."},"v1-9bab07921c513bbb":{"src":"assets/voice/jeppe-neural-v1/v1-9bab07921c513bbb.mp3","text":"Udsagn 2."},"v1-9ba487921c4bf68d":{"src":"assets/voice/jeppe-neural-v1/v1-9ba487921c4bf68d.mp3","text":"Udsagn 4."},"v1-9bae65921c54114c":{"src":"assets/voice/jeppe-neural-v1/v1-9bae65921c54114c.mp3","text":"Udsagn 1."},"v1-9bed4b254bad1b65":{"src":"assets/voice/jeppe-neural-v1/v1-9bed4b254bad1b65.mp3","text":"Må bruge fortovet, hvis der stadig er lidt plads til gående."},"v1-9c27aef68d39ae96":{"src":"assets/voice/jeppe-neural-v1/v1-9c27aef68d39ae96.mp3","text":"Standser for politiets anvisning."},"v1-9bc01c2d9db2720e":{"src":"assets/voice/jeppe-neural-v1/v1-9bc01c2d9db2720e.mp3","text":"Holder samme fart, fordi asfalten ser sort ud."},"v1-9bedbf53d628c5fd":{"src":"assets/voice/jeppe-neural-v1/v1-9bedbf53d628c5fd.mp3","text":"Parkerer langs husmuren, fordi der ikke er en forbudstavle."},"v1-9d970691fa6d773b":{"src":"assets/voice/jeppe-neural-v1/v1-9d970691fa6d773b.mp3","text":"Gul er midlertidig, ikke valgfri."},"v1-9dfa7c813af99a32":{"src":"assets/voice/jeppe-neural-v1/v1-9dfa7c813af99a32.mp3","text":"Kontrollerer samtidig, om føreren faktisk ser mig."},"v1-9dbf47db390ea644":{"src":"assets/voice/jeppe-neural-v1/v1-9dbf47db390ea644.mp3","text":"Har automatisk fortrinsret, fordi jeg kører ligeud."},"v1-9ee32747c56822f7":{"src":"assets/voice/jeppe-neural-v1/v1-9ee32747c56822f7.mp3","text":"Fri passage skal skabes roligt og sikkert. Udrykning ophæver ikke behovet for at beskytte andre."},"v1-a08d7bd795c24879":{"src":"assets/voice/jeppe-neural-v1/v1-a08d7bd795c24879.mp3","text":"Et badge kan være flot uden at være et myndighedsdokument."},"v1-a231df3ae1edfe19":{"src":"assets/voice/jeppe-neural-v1/v1-a231df3ae1edfe19.mp3","text":"Skruer musikken op, så mislyden ikke distraherer."},"v1-9ef7642d85a9fe9e":{"src":"assets/voice/jeppe-neural-v1/v1-9ef7642d85a9fe9e.mp3","text":"Hvad kræver B 13? Du møder B 13 Stop og en stoplinje. Krydset ser tomt ud, og der er godt udsyn fra linjen."},"v1-9f765902715d05e7":{"src":"assets/voice/jeppe-neural-v1/v1-9f765902715d05e7.mp3","text":"Slukker motoren, mens bilen ruller, for maksimal besparelse."},"v1-a30320a43963cd1a":{"src":"assets/voice/jeppe-neural-v1/v1-a30320a43963cd1a.mp3","text":"Trækker ud foran bilen, fordi jeg blinkede først."},"v1-a388593b0bdb995c":{"src":"assets/voice/jeppe-neural-v1/v1-a388593b0bdb995c.mp3","text":"Den lave grænse gælder også denne nye bilist."},"v1-a395264a5c60c9a9":{"src":"assets/voice/jeppe-neural-v1/v1-a395264a5c60c9a9.mp3","text":"Overhaler, fordi traktoren er langsom."},"v1-a301db2dc709e0b0":{"src":"assets/voice/jeppe-neural-v1/v1-a301db2dc709e0b0.mp3","text":"Alder over 18 fritager i de første tre år."},"v1-a4023a33d0f5d174":{"src":"assets/voice/jeppe-neural-v1/v1-a4023a33d0f5d174.mp3","text":"Aftaler et konkret mål for lektionen sammen."},"v1-a44879572305746f":{"src":"assets/voice/jeppe-neural-v1/v1-a44879572305746f.mp3","text":"Kører derefter først, når vigepligten kan overholdes."},"v1-a5653c5bec7e091d":{"src":"assets/voice/jeppe-neural-v1/v1-a5653c5bec7e091d.mp3","text":"Indkørslen har adresse, ikke fortrinsret."},"v1-a4d15368f6d29083":{"src":"assets/voice/jeppe-neural-v1/v1-a4d15368f6d29083.mp3","text":"Forventer mulig igangsætning, men søger bekræftelse."},"v1-a5c3d6e6ed3064a8":{"src":"assets/voice/jeppe-neural-v1/v1-a5c3d6e6ed3064a8.mp3","text":"Svinger foran, fordi bilen allerede blinker."},"v1-a5a593bbedd6a6f2":{"src":"assets/voice/jeppe-neural-v1/v1-a5a593bbedd6a6f2.mp3","text":"Nødsporet er en nødløsning, ikke et værksted med motorvejsudsigt."},"v1-a8551bf04fe7cc51":{"src":"assets/voice/jeppe-neural-v1/v1-a8551bf04fe7cc51.mp3","text":"Skal have en egnet ledsager fra kl. 20.00."},"v1-a637eaf9667fe7fc":{"src":"assets/voice/jeppe-neural-v1/v1-a637eaf9667fe7fc.mp3","text":"Hvordan begynder du parkeringen? På lukket øvelsesplads skal du forlæns ind i et afmærket område langs højre kant. Der er god plads til den første øvelse, og kørelæreren sidder ved siden af."},"v1-a8563f9cb1285b9f":{"src":"assets/voice/jeppe-neural-v1/v1-a8563f9cb1285b9f.mp3","text":"Kører først, når ingen tvinges til at ændre fart eller placering."},"v1-a9c54fbed2792ad6":{"src":"assets/voice/jeppe-neural-v1/v1-a9c54fbed2792ad6.mp3","text":"Lader den modkørende passere."},"v1-ab4dfad882f1bbae":{"src":"assets/voice/jeppe-neural-v1/v1-ab4dfad882f1bbae.mp3","text":"Sænker farten og sikrer mig, at vejen er fri."},"v1-a8f4f7447e3bfa2f":{"src":"assets/voice/jeppe-neural-v1/v1-a8f4f7447e3bfa2f.mp3","text":"Må allerede køre alene kl. 04.59."},"v1-ac5a5ad16dfc108e":{"src":"assets/voice/jeppe-neural-v1/v1-ac5a5ad16dfc108e.mp3","text":"Påstigningen regnes ikke som parkering."},"v1-af582a21e3971ed8":{"src":"assets/voice/jeppe-neural-v1/v1-af582a21e3971ed8.mp3","text":"Bremser forsigtigt og reducerer farten."},"v1-ac869b3eece5dd0d":{"src":"assets/voice/jeppe-neural-v1/v1-ac869b3eece5dd0d.mp3","text":"Må holde delvist på cykelstien, når bilen vejer under 3.500 kg."},"v1-aeb32282133b3a0e":{"src":"assets/voice/jeppe-neural-v1/v1-aeb32282133b3a0e.mp3","text":"Hvad gør du før højresving? Du kører langs en cykelsti og vil dreje til højre. En hurtig elcyklist er bag dig og kan nå op på siden før svinget."},"v1-afd3ee6bbf06bef6":{"src":"assets/voice/jeppe-neural-v1/v1-afd3ee6bbf06bef6.mp3","text":"Regner med, at motorcyklen dytter."},"v1-b0e84dccf8cc5dfd":{"src":"assets/voice/jeppe-neural-v1/v1-b0e84dccf8cc5dfd.mp3","text":"Bruger pladsen til rolige korrektioner."},"v1-b13724e8044aa9c9":{"src":"assets/voice/jeppe-neural-v1/v1-b13724e8044aa9c9.mp3","text":"Venter og lader nødbremsesystemet klare det."},"v1-afe0b8bae2baa4cd":{"src":"assets/voice/jeppe-neural-v1/v1-afe0b8bae2baa4cd.mp3","text":"Pedalvandringen afhænger af bilfabrikatet, men pedalen må normalt ikke synke ved konstant tryk og må ikke kunne trædes i bund ved hårdt tryk. En tydelig afvigelse skal undersøges."},"v1-b157679f408dc3db":{"src":"assets/voice/jeppe-neural-v1/v1-b157679f408dc3db.mp3","text":"Sigter mod højst 20 cm mellem højre hjul og kanten."},"v1-b21d4f8ff1793e2d":{"src":"assets/voice/jeppe-neural-v1/v1-b21d4f8ff1793e2d.mp3","text":"Cykelstien er infrastruktur, ikke bilens fodskammel."},"v1-b1f3d8c3212d9537":{"src":"assets/voice/jeppe-neural-v1/v1-b1f3d8c3212d9537.mp3","text":"Indstiller parkeringsskiven korrekt."},"v1-b1675faf2205e1fb":{"src":"assets/voice/jeppe-neural-v1/v1-b1675faf2205e1fb.mp3","text":"Hvordan genvinder du kontrollen? På et godkendt køreteknisk anlæg under instruktion kommer bilens højre hjul ud over en høj vejkant. Bilen har stadig for høj fart til sikkert at styre hjulene direkte op over kanten."},"v1-b3b90acc2140f2cf":{"src":"assets/voice/jeppe-neural-v1/v1-b3b90acc2140f2cf.mp3","text":"Venter med at fuldføre svinget, til udsynet er tilstrækkeligt."},"v1-b3313dba56847b12":{"src":"assets/voice/jeppe-neural-v1/v1-b3313dba56847b12.mp3","text":"Kører tæt forbi, fordi der ikke står nogen på kørebanen endnu."},"v1-b35d54da888933af":{"src":"assets/voice/jeppe-neural-v1/v1-b35d54da888933af.mp3","text":"Assistenter supplerer føreren. Tidlig, kontrolleret opbremsning bruger vejgrebet bedre og gør kørslen forudsigelig."},"v1-b31753cce082de8f":{"src":"assets/voice/jeppe-neural-v1/v1-b31753cce082de8f.mp3","text":"Kører over, fordi toget ser ud til at være langt væk."},"v1-b56ecd1a58630ff1":{"src":"assets/voice/jeppe-neural-v1/v1-b56ecd1a58630ff1.mp3","text":"Venter før krydset."},"v1-b5998b688c62090a":{"src":"assets/voice/jeppe-neural-v1/v1-b5998b688c62090a.mp3","text":"Betragter appen som erstatning for de praktiske lektioner."},"v1-b5e1b4180f352de9":{"src":"assets/voice/jeppe-neural-v1/v1-b5e1b4180f352de9.mp3","text":"Seks fejl er bestået."},"v1-b539935c379a8d16":{"src":"assets/voice/jeppe-neural-v1/v1-b539935c379a8d16.mp3","text":"Lader beskeden vente."},"v1-b68807f9e51bc8ed":{"src":"assets/voice/jeppe-neural-v1/v1-b68807f9e51bc8ed.mp3","text":"Regner grønt lys som fortrinsret over modkørende."},"v1-b62f8c2643aaa48d":{"src":"assets/voice/jeppe-neural-v1/v1-b62f8c2643aaa48d.mp3","text":"Presser igennem med hornet aktiveret."},"v1-b61d5cc07391f865":{"src":"assets/voice/jeppe-neural-v1/v1-b61d5cc07391f865.mp3","text":"Kanten skal forhandles med ro, ikke udfordres til rat-duel."},"v1-b6e3cd25358ed0f5":{"src":"assets/voice/jeppe-neural-v1/v1-b6e3cd25358ed0f5.mp3","text":"Ved bakning kræves fuld orientering. Kameraet kan have blinde områder, og gående på fortovet skal beskyttes."},"v1-b737287b5718245a":{"src":"assets/voice/jeppe-neural-v1/v1-b737287b5718245a.mp3","text":"Grønt lys blev lige mellemleder."},"v1-b75f2b74e2f04740":{"src":"assets/voice/jeppe-neural-v1/v1-b75f2b74e2f04740.mp3","text":"Kører først, når der er plads på den anden side."},"v1-b730a66b5d71a1cc":{"src":"assets/voice/jeppe-neural-v1/v1-b730a66b5d71a1cc.mp3","text":"Dækket er lovligt, når vejen er tør."},"v1-b6f3a1c26119f7ee":{"src":"assets/voice/jeppe-neural-v1/v1-b6f3a1c26119f7ee.mp3","text":"Er ét stop altid nok? Ved B 13 standser du helt ved stoplinjen. En mur spærrer udsynet derfra, men du kan derefter køre langsomt frem til et sted før krydset, hvor der er udsyn."},"v1-b872c096a7b85463":{"src":"assets/voice/jeppe-neural-v1/v1-b872c096a7b85463.mp3","text":"Grønt lys er adgang til vurderingen, ikke VIP-armbånd gennem motorcyklen."},"v1-b80345055f6032a8":{"src":"assets/voice/jeppe-neural-v1/v1-b80345055f6032a8.mp3","text":"Dytter for at flytte vigepligten til cyklisten."},"v1-b76433851c45f9e0":{"src":"assets/voice/jeppe-neural-v1/v1-b76433851c45f9e0.mp3","text":"Tidlig farttilpasning forbedrer udsyn, reaktion og greb. Bevægelsesenergien stiger kraftigt med hastigheden."},"v1-b80e264b999968fd":{"src":"assets/voice/jeppe-neural-v1/v1-b80e264b999968fd.mp3","text":"Ved udkørslen skal du holde tilbage for cyklisten og for gående, der krydser eller er på vej ud i feltet; stands om nødvendigt."},"v1-b8effd6b35464c8d":{"src":"assets/voice/jeppe-neural-v1/v1-b8effd6b35464c8d.mp3","text":"Hornet gør ikke vejen bredere."},"v1-b9614cad2a89233d":{"src":"assets/voice/jeppe-neural-v1/v1-b9614cad2a89233d.mp3","text":"Tro, at et gemt spørgsmål automatisk er korrekt."},"v1-b876335ab23bfa73":{"src":"assets/voice/jeppe-neural-v1/v1-b876335ab23bfa73.mp3","text":"Finder et andet lovligt sted."},"v1-b91c3804218507e8":{"src":"assets/voice/jeppe-neural-v1/v1-b91c3804218507e8.mp3","text":"Man må ikke fremtvinge passage eller blokere krydset. Grønt lys ophæver ikke pligten til hensyn."},"v1-bc11203242a1825e":{"src":"assets/voice/jeppe-neural-v1/v1-bc11203242a1825e.mp3","text":"Spotify er ikke et godkendt diagnoseværktøj."},"v1-bbb3209f9275fac0":{"src":"assets/voice/jeppe-neural-v1/v1-bbb3209f9275fac0.mp3","text":"Cyklisten kan flytte sig hurtigt. Gentag orienteringen og hold tilbage for ligeudkørende cykeltrafik."},"v1-ba86298c25b58349":{"src":"assets/voice/jeppe-neural-v1/v1-ba86298c25b58349.mp3","text":"Stiger om nødvendigt ud og skaber overblik."},"v1-bac4f5652141a39f":{"src":"assets/voice/jeppe-neural-v1/v1-bac4f5652141a39f.mp3","text":"Hvem holder du tilbage for? To små veje mødes uden signal, tavler, hajtænder eller særlig vejudformning. En bil kommer fra din højre side."},"v1-bcb07f68396011ce":{"src":"assets/voice/jeppe-neural-v1/v1-bcb07f68396011ce.mp3","text":"Lader cyklisten bremse for bilen."},"v1-bd612623f15f2a20":{"src":"assets/voice/jeppe-neural-v1/v1-bd612623f15f2a20.mp3","text":"Hattehylden er ikke business class for termoflasker."},"v1-bd275890546d2229":{"src":"assets/voice/jeppe-neural-v1/v1-bd275890546d2229.mp3","text":"Venter, så cyklisten ikke skal ændre fart eller placering."},"v1-bd4ed52f64e50b00":{"src":"assets/voice/jeppe-neural-v1/v1-bd4ed52f64e50b00.mp3","text":"Afsnit 9.5 er en praktisk øvelse på køreteknisk anlæg under kørelærerens ledelse. Appen forbereder regelforståelsen, men gennemfører ikke den fysiske træning."},"v1-c24fcc78acb86e0b":{"src":"assets/voice/jeppe-neural-v1/v1-c24fcc78acb86e0b.mp3","text":"Styrer først tilbage over kanten, når farten er lav nok."},"v1-c3f867d8ea0baf33":{"src":"assets/voice/jeppe-neural-v1/v1-c3f867d8ea0baf33.mp3","text":"Venter med al bremsning til midt i svinget."},"v1-bf47bb3ce2d7ca34":{"src":"assets/voice/jeppe-neural-v1/v1-bf47bb3ce2d7ca34.mp3","text":"En motorcykels lille lyssilhuet gør afstand og fart sværere at bedømme. Usikkerhed skal føre til sikkerhedsmargin."},"v1-be5473e5cd35b4e8":{"src":"assets/voice/jeppe-neural-v1/v1-be5473e5cd35b4e8.mp3","text":"Hvad gælder for den nye bilist? En 32-årig fik sit første B-kørekort for ét år siden og skal til middag. Personen mener, at den lave alkoholgrænse kun gælder 17-årige."},"v1-c5aafc3b2e190cb9":{"src":"assets/voice/jeppe-neural-v1/v1-c5aafc3b2e190cb9.mp3","text":"Tænder nærlys, så også baglygterne er tændt."},"v1-c6818f0a2bbad9e1":{"src":"assets/voice/jeppe-neural-v1/v1-c6818f0a2bbad9e1.mp3","text":"Kører forsigtigt frem og standser igen, hvis det er nødvendigt for at orientere mig."},"v1-c6808b8adee44459":{"src":"assets/voice/jeppe-neural-v1/v1-c6808b8adee44459.mp3","text":"Hvordan sætter du i gang? Du holder ved kantstenen. En cyklist kommer bagfra, og der er fri bane bag cyklisten."},"v1-c64852c0e8777871":{"src":"assets/voice/jeppe-neural-v1/v1-c64852c0e8777871.mp3","text":"Standser sikkert og undersøger problemet."},"v1-c7e7c27b1f92a0ca":{"src":"assets/voice/jeppe-neural-v1/v1-c7e7c27b1f92a0ca.mp3","text":"Flytter bilen uden for 10-meterområdet eller til en lovlig afmærket bås."},"v1-c68836e30e14a921":{"src":"assets/voice/jeppe-neural-v1/v1-c68836e30e14a921.mp3","text":"Møder til prøve og bruger appens badge som officiel attest."},"v1-c686a5b38cd06117":{"src":"assets/voice/jeppe-neural-v1/v1-c686a5b38cd06117.mp3","text":"Skal altid standse helt, selv når vigepligten kan overholdes uden stop."},"v1-c7bd7042574c6215":{"src":"assets/voice/jeppe-neural-v1/v1-c7bd7042574c6215.mp3","text":"Fra vejkant skal du altid give tegn i god tid. Du skal stadig orientere dig og holde tilbage, fordi tegnet ikke giver fortrinsret."},"v1-c84a2ef3bfa2c22f":{"src":"assets/voice/jeppe-neural-v1/v1-c84a2ef3bfa2c22f.mp3","text":"Kold luft er vejr, ikke søvn."},"v1-c88778f6a0db7b48":{"src":"assets/voice/jeppe-neural-v1/v1-c88778f6a0db7b48.mp3","text":"Betragter det som et muligt tegn på bremsefejl."},"v1-c7f60f8cff0ef62e":{"src":"assets/voice/jeppe-neural-v1/v1-c7f60f8cff0ef62e.mp3","text":"Holder lovligt ind, hvis den virkelig skal håndteres."},"v1-c83ef88f979a20cc":{"src":"assets/voice/jeppe-neural-v1/v1-c83ef88f979a20cc.mp3","text":"Undlader at køre, før fejlen er undersøgt."},"v1-cbf84b596295eb73":{"src":"assets/voice/jeppe-neural-v1/v1-cbf84b596295eb73.mp3","text":"Bremsetester den bagvedkørende."},"v1-ca57b74182ca861b":{"src":"assets/voice/jeppe-neural-v1/v1-ca57b74182ca861b.mp3","text":"Man må ikke køre ind på sporet uden sikker plads til at komme helt over."},"v1-cc616633c5cc3694":{"src":"assets/voice/jeppe-neural-v1/v1-cc616633c5cc3694.mp3","text":"Bakker kun, når manøvren kan ske uden fare."},"v1-cb02cf24f44dbd23":{"src":"assets/voice/jeppe-neural-v1/v1-cb02cf24f44dbd23.mp3","text":"Fem kilometer er billigere end en actionfilm i nødsporet."},"v1-cc7494f1aa6132dd":{"src":"assets/voice/jeppe-neural-v1/v1-cc7494f1aa6132dd.mp3","text":"Må standse i båsen, fordi det varer under tre minutter."},"v1-cd3069034ede7dbe":{"src":"assets/voice/jeppe-neural-v1/v1-cd3069034ede7dbe.mp3","text":"De almindelige hensynsregler gælder stadig."},"v1-cc726f1c9c91f535":{"src":"assets/voice/jeppe-neural-v1/v1-cc726f1c9c91f535.mp3","text":"Udsætter turen eller skaffer passende sikkerhedsudstyr."},"v1-cddce1bb27c8513c":{"src":"assets/voice/jeppe-neural-v1/v1-cddce1bb27c8513c.mp3","text":"Hvad gør du ved udkørslen? Du forlader en rundkørsel. En gående er på vej ud i fodgængerfeltet umiddelbart efter udkørslen, og en cyklist fortsætter langs rundkørslen."},"v1-caac42836dd15aaf":{"src":"assets/voice/jeppe-neural-v1/v1-caac42836dd15aaf.mp3","text":"Holder farten lav og styrer jævnt."},"v1-cfc40194b16f3ff9":{"src":"assets/voice/jeppe-neural-v1/v1-cfc40194b16f3ff9.mp3","text":"Holder tilbage for både biler og cyklist."},"v1-cf1a5a5b294a6bd0":{"src":"assets/voice/jeppe-neural-v1/v1-cf1a5a5b294a6bd0.mp3","text":"Dytter gentagne gange, så cyklisterne flytter sig."},"v1-cefbcddca1503070":{"src":"assets/voice/jeppe-neural-v1/v1-cefbcddca1503070.mp3","text":"Orienteringen skal gentages, fordi cyklister kan nå frem under forberedelsen. Den højresvingende skal holde tilbage for den ligeudkørende cyklist."},"v1-d08b17b13c7c60c9":{"src":"assets/voice/jeppe-neural-v1/v1-d08b17b13c7c60c9.mp3","text":"Både standsning og parkering er forbudt her."},"v1-d1db6b3760d2ff3b":{"src":"assets/voice/jeppe-neural-v1/v1-d1db6b3760d2ff3b.mp3","text":"Er fritaget for ansvar, når assistenten er tændt."},"v1-d22316ac0b67ea8d":{"src":"assets/voice/jeppe-neural-v1/v1-d22316ac0b67ea8d.mp3","text":"Overhaling er ikke Battle Royale."},"v1-d04e01966619e91f":{"src":"assets/voice/jeppe-neural-v1/v1-d04e01966619e91f.mp3","text":"Hvordan dækkes undervisningen? Køreskolens placering gør det umuligt at nå et letbaneområde, køre relevant dér og vende tilbage inden for en praktisk lektion på mindst 45 minutter. Kørelæreren planlægger derfor afsnit 7.21."},"v1-d3ebd5b204c44cbf":{"src":"assets/voice/jeppe-neural-v1/v1-d3ebd5b204c44cbf.mp3","text":"Accepterer omvejen."},"v1-d3848e893c6bfd8c":{"src":"assets/voice/jeppe-neural-v1/v1-d3848e893c6bfd8c.mp3","text":"Orienterer mig og giver tegn før skiftet."},"v1-d44b0d1f18a7547e":{"src":"assets/voice/jeppe-neural-v1/v1-d44b0d1f18a7547e.mp3","text":"Svinger, fordi cyklisten var bag bilen ved første spejlkig."},"v1-d42dd0fcc53c3fd4":{"src":"assets/voice/jeppe-neural-v1/v1-d42dd0fcc53c3fd4.mp3","text":"Afsnit 2.7 begynder med god plads til korrektion. Lav fart og fordelt orientering gør det muligt at bedømme bilens bredde og hjulplacering. Det skal øves praktisk med kørelærer."},"v1-d636c477ea8c45b9":{"src":"assets/voice/jeppe-neural-v1/v1-d636c477ea8c45b9.mp3","text":"Orienterer mig og skaber plads uden at udsætte fodgængerne for fare."},"v1-d683b82296274ae0":{"src":"assets/voice/jeppe-neural-v1/v1-d683b82296274ae0.mp3","text":"Standsning og parkering er forbudt på cykelsti og som hovedregel fortov. Den begrænsede fortovsundtagelse for visse køretøjer uden for tættere bebygget område gælder ikke her og aldrig på cykelstien."},"v1-d5f8d4fa4c24ebd0":{"src":"assets/voice/jeppe-neural-v1/v1-d5f8d4fa4c24ebd0.mp3","text":"Hvordan skifter du vognbane? Du vil fra højre til venstre bane. En bil ligger lidt bag dig i venstre bane, og der er ingen sammenfletningstavle eller ophørende striber."},"v1-d51b33f11d615b8d":{"src":"assets/voice/jeppe-neural-v1/v1-d51b33f11d615b8d.mp3","text":"Hvor må du øve dette? Efter at have læst om høje vejkanter vil du selv træne manøvren på en tom offentlig landevej. Vejen har en høj rabatkant, og der er ingen kørelærer eller afspærring."},"v1-d7cb77a7bc7ddce8":{"src":"assets/voice/jeppe-neural-v1/v1-d7cb77a7bc7ddce8.mp3","text":"Må køre alene kl. 19.45."},"v1-d749e633e139f6f5":{"src":"assets/voice/jeppe-neural-v1/v1-d749e633e139f6f5.mp3","text":"Hornet kan lave lyd, ikke lovgivning."},"v1-d750b40b7cf1f5bb":{"src":"assets/voice/jeppe-neural-v1/v1-d750b40b7cf1f5bb.mp3","text":"Omgivelserne varsler uforudsigelige gående. Skab udsyn, plads og standsemulighed."},"v1-d83e0497d47481c7":{"src":"assets/voice/jeppe-neural-v1/v1-d83e0497d47481c7.mp3","text":"Kraftig regn kan være lygtetændingstid. Brug mindst nærlys; særligt kørelys alene opfylder ikke kravet, når bagenden ikke er tilstrækkeligt belyst."},"v1-d97d15a9a9e3841a":{"src":"assets/voice/jeppe-neural-v1/v1-d97d15a9a9e3841a.mp3","text":"Kører ind, fordi grønt altid giver ubetinget ret."},"v1-d9ce611612da6502":{"src":"assets/voice/jeppe-neural-v1/v1-d9ce611612da6502.mp3","text":"Lader en frivillig appsession erstatte kørelærerens undervisning."},"v1-d9baacb73e9cf393":{"src":"assets/voice/jeppe-neural-v1/v1-d9baacb73e9cf393.mp3","text":"Forventer, at baghjulene kan komme tæt på hjørnet."},"v1-d8c4ec062f7bc83c":{"src":"assets/voice/jeppe-neural-v1/v1-d8c4ec062f7bc83c.mp3","text":"Når hindringen er på din side, må du ikke presse modkørende. Tilpas fart og vent på plads."},"v1-da54aec8128278b0":{"src":"assets/voice/jeppe-neural-v1/v1-da54aec8128278b0.mp3","text":"Sikrer den løse flaske."},"v1-db85f722f2648a28":{"src":"assets/voice/jeppe-neural-v1/v1-db85f722f2648a28.mp3","text":"Tre blink er stadig bare tre blink."},"v1-db6d62181cbe1e50":{"src":"assets/voice/jeppe-neural-v1/v1-db6d62181cbe1e50.mp3","text":"Lader appens samlede score erstatte kørelærerens vurdering."},"v1-db0ebf67b44bc7a8":{"src":"assets/voice/jeppe-neural-v1/v1-db0ebf67b44bc7a8.mp3","text":"Broer og skygge kan være glatte. Tilpas fart tidligt og brug jævne bevægelser."},"v1-dca8ebc001c86f38":{"src":"assets/voice/jeppe-neural-v1/v1-dca8ebc001c86f38.mp3","text":"Kameraet har ingen juridisk embedseksamen."},"v1-dd0c1ad06e24d4c9":{"src":"assets/voice/jeppe-neural-v1/v1-dd0c1ad06e24d4c9.mp3","text":"Håndbremsen er ikke bilens reserve-faldskærm."},"v1-dd736dd7c5293d86":{"src":"assets/voice/jeppe-neural-v1/v1-dd736dd7c5293d86.mp3","text":"Accelererer for at komme hurtigere forbi fejlen."},"v1-dbedb3111d79d91c":{"src":"assets/voice/jeppe-neural-v1/v1-dbedb3111d79d91c.mp3","text":"Venter, til vognbaneskiftet kan ske uden at genere bilen."},"v1-de636f4937963058":{"src":"assets/voice/jeppe-neural-v1/v1-de636f4937963058.mp3","text":"Regner med bakspejlet alene."},"v1-de769438a42fa1cc":{"src":"assets/voice/jeppe-neural-v1/v1-de769438a42fa1cc.mp3","text":"Bolden er et faretegn. Forudseenhed og lavere hastighed giver tid til en rigtig reaktion."},"v1-dd939aa6dfaccf84":{"src":"assets/voice/jeppe-neural-v1/v1-dd939aa6dfaccf84.mp3","text":"Må du holde seks meter fra krydset? I en by holder du langs kantstenen 6 m fra den nærmeste kant af den tværgående kørebane. Der er ingen afmærket parkeringsbås og ingen anden særregel."},"v1-dda1841be88caf74":{"src":"assets/voice/jeppe-neural-v1/v1-dda1841be88caf74.mp3","text":"Afsnit 7.22 er praktisk kørsel med fælles mål, opfølgning og refleksion. Appen kan forberede samtalen, men gennemfører eller dokumenterer ikke lektionen."},"v1-df47ff758db9fec0":{"src":"assets/voice/jeppe-neural-v1/v1-df47ff758db9fec0.mp3","text":"Måler de 10 m fra krydsets midte."},"v1-e01eaeedeb28672a":{"src":"assets/voice/jeppe-neural-v1/v1-e01eaeedeb28672a.mp3","text":"Hvilke valg er rigtige? I tæt regn om dagen er sigten kort. Bilens automatiske kørelys tænder kun lys foran, og trafikken bevæger sig langsommere."},"v1-dff9fe67f09d84f3":{"src":"assets/voice/jeppe-neural-v1/v1-dff9fe67f09d84f3.mp3","text":"Hvad gør du med cyklisten bagfra? Du vil højresvinge over en cykelsti. Ved første spejlkig er cyklisten bag bilen, men før svinget er cyklisten nået op langs din højre side."},"v1-dfd92d26dd489684":{"src":"assets/voice/jeppe-neural-v1/v1-dfd92d26dd489684.mp3","text":"Hvad gør du før afgang? Du har lånt en bil. Sædet står langt tilbage, sidespejlet viser mest himmel, og en metalflaske ligger løs på hattehylden."},"v1-e0b15c7082d9691e":{"src":"assets/voice/jeppe-neural-v1/v1-e0b15c7082d9691e.mp3","text":"Lader bilen vælge, fordi kameraet aldrig tager fejl."},"v1-e08f605b708cf471":{"src":"assets/voice/jeppe-neural-v1/v1-e08f605b708cf471.mp3","text":"Holder præcis 80, fordi tavlen kræver det."},"v1-e0631e9901d97efb":{"src":"assets/voice/jeppe-neural-v1/v1-e0631e9901d97efb.mp3","text":"Må du køre ind? Bommen ved en jernbaneoverkørsel er oppe, men trafikken holder stille på den anden side, og din bil kan ikke komme helt fri af sporet."},"v1-e0ab87938b4003da":{"src":"assets/voice/jeppe-neural-v1/v1-e0ab87938b4003da.mp3","text":"Hvordan bedømmer du situationen? I mørke ser du ét forlys fra en modkørende motorcykel langt fremme. Du overvejer at overhale en langsom bil."},"v1-e13e99fc2387e431":{"src":"assets/voice/jeppe-neural-v1/v1-e13e99fc2387e431.mp3","text":"Kører blindt over for rødt ind mellem fodgængerne."},"v1-e13fd52b9af38470":{"src":"assets/voice/jeppe-neural-v1/v1-e13fd52b9af38470.mp3","text":"Beder passageren vente."},"v1-e161faf2e40c823d":{"src":"assets/voice/jeppe-neural-v1/v1-e161faf2e40c823d.mp3","text":"Orienterer mig efter cyklisten og holder tilbage for den, før jeg krydser dens bane."},"v1-e1c5ae0017328d97":{"src":"assets/voice/jeppe-neural-v1/v1-e1c5ae0017328d97.mp3","text":"Flytter blikket frem mod den ønskede kurs."},"v1-e2144bbd77721b41":{"src":"assets/voice/jeppe-neural-v1/v1-e2144bbd77721b41.mp3","text":"Følger bilen foran uden selv at se tegnet."},"v1-e25470c546a0edae":{"src":"assets/voice/jeppe-neural-v1/v1-e25470c546a0edae.mp3","text":"Regner med, at modkørende kan bremse."},"v1-e1d944ee991eca22":{"src":"assets/voice/jeppe-neural-v1/v1-e1d944ee991eca22.mp3","text":"Træner kun øvelsen på godkendt køreteknisk anlæg med kørelærer."},"v1-e1f8f40954c72f4c":{"src":"assets/voice/jeppe-neural-v1/v1-e1f8f40954c72f4c.mp3","text":"Hvilket lys bruger du i regnen? Det er dag, men kraftig regn gør sigten dårlig. Bilens kørelys tænder kun forlygter foran, mens baglygterne er slukket."},"v1-e2e2459ff259212f":{"src":"assets/voice/jeppe-neural-v1/v1-e2e2459ff259212f.mp3","text":"Drikker kaffe og kører straks, fordi kaffe fjerner søvnbehovet."},"v1-e28294e8b859b4c9":{"src":"assets/voice/jeppe-neural-v1/v1-e28294e8b859b4c9.mp3","text":"Må fortsætte alene til kl. 20.59."},"v1-e34a92e4b44c2c52":{"src":"assets/voice/jeppe-neural-v1/v1-e34a92e4b44c2c52.mp3","text":"Traktoren er langsom; beslutningen behøver ikke være det."},"v1-e34df0d50dae36cb":{"src":"assets/voice/jeppe-neural-v1/v1-e34df0d50dae36cb.mp3","text":"Hvordan bruger du hjælpesystemerne? Under den afsluttende praktiske lektion følger du en planlagt GPS-rute. Systemet foreslår en sen vognbanemanøvre, mens tæt trafik gør manøvren usikker. Kørelæreren observerer din selvstændige kørsel."},"v1-e3ada30abb5071e2":{"src":"assets/voice/jeppe-neural-v1/v1-e3ada30abb5071e2.mp3","text":"Venter på udskridningen og improviserer."},"v1-e367c30c3135d3f5":{"src":"assets/voice/jeppe-neural-v1/v1-e367c30c3135d3f5.mp3","text":"Hajtænderne spiser ikke cyklister ud af reglen."},"v1-e3bd2741d831851b":{"src":"assets/voice/jeppe-neural-v1/v1-e3bd2741d831851b.mp3","text":"Sænker farten og standser om nødvendigt."},"v1-e3ef9bd0b4073efc":{"src":"assets/voice/jeppe-neural-v1/v1-e3ef9bd0b4073efc.mp3","text":"Planen kræver praktisk letbanekørsel, når en lektion på mindst 45 minutter gør den mulig. Ellers skal de praktiske færdigheder ved letbane undervises i teorilokalet."},"v1-e55c8c8912959e02":{"src":"assets/voice/jeppe-neural-v1/v1-e55c8c8912959e02.mp3","text":"Kontrollerer, at den anden fører faktisk overholder sine pligter."},"v1-e4f8405c0880519c":{"src":"assets/voice/jeppe-neural-v1/v1-e4f8405c0880519c.mp3","text":"Kan du begynde overhalingen? Du vil overhale på landevej med frit udsyn. I venstre spejl ser du en bil bagfra, som allerede har trukket ud for at overhale dig."},"v1-e539d7cd8a07427d":{"src":"assets/voice/jeppe-neural-v1/v1-e539d7cd8a07427d.mp3","text":"Orienterer mig omkring bilen under hele manøvren."},"v1-e4e41ead51682a78":{"src":"assets/voice/jeppe-neural-v1/v1-e4e41ead51682a78.mp3","text":"Arbejder med signaler, sporforløb, risici og korrekt handling."},"v1-e59b02ff07a47388":{"src":"assets/voice/jeppe-neural-v1/v1-e59b02ff07a47388.mp3","text":"Bruger blinklyset som fortrinsret."},"v1-e6a105a5704ad89d":{"src":"assets/voice/jeppe-neural-v1/v1-e6a105a5704ad89d.mp3","text":"Nødbremsen er brandalarmen, ikke køkkenuret."},"v1-e701560aa58f9225":{"src":"assets/voice/jeppe-neural-v1/v1-e701560aa58f9225.mp3","text":"Finder et sikkert sted at lade den utålmodige passere, hvis det er hensigtsmæssigt."},"v1-e6bf7010a2426f8c":{"src":"assets/voice/jeppe-neural-v1/v1-e6bf7010a2426f8c.mp3","text":"Hvad betyder blinklyset? En bil holder ved en sidevej og blinker til højre. Dens hjul står stille, og du kan ikke se førerens ansigt."},"v1-e7ddfe848184ee56":{"src":"assets/voice/jeppe-neural-v1/v1-e7ddfe848184ee56.mp3","text":"Bliver i min bane."},"v1-e7da4926e4805604":{"src":"assets/voice/jeppe-neural-v1/v1-e7da4926e4805604.mp3","text":"Sænker farten før svinget."},"v1-e72552786fef8af1":{"src":"assets/voice/jeppe-neural-v1/v1-e72552786fef8af1.mp3","text":"Standser først ved stoplinjen."},"v1-e7b9b5304fc7cd85":{"src":"assets/voice/jeppe-neural-v1/v1-e7b9b5304fc7cd85.mp3","text":"Vælger frit højre side, fordi der ikke kommer modkørende."},"v1-e7fda4b18e131c92":{"src":"assets/voice/jeppe-neural-v1/v1-e7fda4b18e131c92.mp3","text":"Indstiller sæde og spejle før jeg kører."},"v1-e83e639930622999":{"src":"assets/voice/jeppe-neural-v1/v1-e83e639930622999.mp3","text":"Lader båsen være fri til et køretøj med gyldig tilladelse."},"v1-e87c9771e9e60995":{"src":"assets/voice/jeppe-neural-v1/v1-e87c9771e9e60995.mp3","text":"Følger eventuelle anvisninger fra politi eller redningspersonale."},"v1-e7ed763f5bdc64fd":{"src":"assets/voice/jeppe-neural-v1/v1-e7ed763f5bdc64fd.mp3","text":"Følger de hvide linjer, fordi de er permanente."},"v1-ea0bef69b05042b5":{"src":"assets/voice/jeppe-neural-v1/v1-ea0bef69b05042b5.mp3","text":"Sørger som fører for, at barnet er korrekt sikret."},"v1-e8e37a73bcfbdaf4":{"src":"assets/voice/jeppe-neural-v1/v1-e8e37a73bcfbdaf4.mp3","text":"Forventer uændrede bremseegenskaber."},"v1-e8cd4b3a77724c84":{"src":"assets/voice/jeppe-neural-v1/v1-e8cd4b3a77724c84.mp3","text":"Rød advarsel og unormal motorlyd kan varsle en alvorlig fejl. Fortsat kørsel kan være farlig og skade motoren."},"v1-e9351f4987652eb2":{"src":"assets/voice/jeppe-neural-v1/v1-e9351f4987652eb2.mp3","text":"Det aktuelle format er 25 situationer, fire udsagn, mindst ét korrekt, 25 minutter og højst fem fejl."},"v1-ebd65be493b5a165":{"src":"assets/voice/jeppe-neural-v1/v1-ebd65be493b5a165.mp3","text":"Sort asfalt kan stadig have hemmelig vinterjakke på."},"v1-eaf03718c72a7e66":{"src":"assets/voice/jeppe-neural-v1/v1-eaf03718c72a7e66.mp3","text":"Fra og med kl. 20.00 til kl. 05.00 kræver 17-årsordningen en egnet ledsager, indtil føreren fylder 18 år."},"v1-eb681bed58b79da0":{"src":"assets/voice/jeppe-neural-v1/v1-eb681bed58b79da0.mp3","text":"Hvornår fuldfører du svinget? Du vil svinge til venstre i et signalreguleret kryds med grønt lys, men uden grøn venstrepil. En modkørende motorcykel fortsætter ligeud, og en bil foran dig spærrer kortvarigt noget af udsynet."},"v1-eb1089e187ee1513":{"src":"assets/voice/jeppe-neural-v1/v1-eb1089e187ee1513.mp3","text":"Hvad kan appen dokumentere? Du har gennemført alle NATKØRSEL-kapitler hjemme på eget initiativ. En kørelærer har ikke planlagt eller registreret det som selvstudium."},"v1-ee31d51faf2038ee":{"src":"assets/voice/jeppe-neural-v1/v1-ee31d51faf2038ee.mp3","text":"Holder tilbage og lader cyklisten fortsætte."},"v1-ec9b254d03be80ca":{"src":"assets/voice/jeppe-neural-v1/v1-ec9b254d03be80ca.mp3","text":"Holder tilbage for en bil fra højre."},"v1-ecf15acfd60fd14e":{"src":"assets/voice/jeppe-neural-v1/v1-ecf15acfd60fd14e.mp3","text":"Kan bruge samme solo-regel automatisk i udlandet."},"v1-eddd0fa120c46a92":{"src":"assets/voice/jeppe-neural-v1/v1-eddd0fa120c46a92.mp3","text":"Tager telefonen i hånden ved rødt og fortsætter med at skrive, når trafikken sætter i gang."},"v1-efdef9b393455dd2":{"src":"assets/voice/jeppe-neural-v1/v1-efdef9b393455dd2.mp3","text":"Skaber større mulighed for at reagere på noget skjult."},"v1-efc3e5349fe8f5a2":{"src":"assets/voice/jeppe-neural-v1/v1-efc3e5349fe8f5a2.mp3","text":"Bildøren skal ikke debutere som svingbom."},"v1-ef2418127daf1d4e":{"src":"assets/voice/jeppe-neural-v1/v1-ef2418127daf1d4e.mp3","text":"Ét lys kan stadig komme med hele fysikkens regelsæt."},"v1-ef372de05018b8c7":{"src":"assets/voice/jeppe-neural-v1/v1-ef372de05018b8c7.mp3","text":"Blade er naturens meget billige drift-mode."},"v1-f0eaa23929732486":{"src":"assets/voice/jeppe-neural-v1/v1-f0eaa23929732486.mp3","text":"Holder lav fart og er klar til at standse."},"v1-f0edc8e429d96fb6":{"src":"assets/voice/jeppe-neural-v1/v1-f0edc8e429d96fb6.mp3","text":"Undlader forsøget på offentlig vej."},"v1-f118ee6042a5a691":{"src":"assets/voice/jeppe-neural-v1/v1-f118ee6042a5a691.mp3","text":"Udkørsel fra ejendom og passage over fortov giver ubetinget vigepligt, også uden hajtænder."},"v1-f1f538a8b93ba91d":{"src":"assets/voice/jeppe-neural-v1/v1-f1f538a8b93ba91d.mp3","text":"Hvad gør du ved punkteringen? Et dæk punkterer på motorvejen. Du kan styre bilen ud i nødsporet, og der er en frakørsel langt væk."},"v1-f3fe50499025455c":{"src":"assets/voice/jeppe-neural-v1/v1-f3fe50499025455c.mp3","text":"Kører først, fordi en cykel ikke tæller som kørende færdsel."},"v1-f1ff92be3d335f20":{"src":"assets/voice/jeppe-neural-v1/v1-f1ff92be3d335f20.mp3","text":"Forebyggelse er sikrest: lav fart før det glatte område og undgå pludselige kraftpåvirkninger."},"v1-f2f00434d209c4e2":{"src":"assets/voice/jeppe-neural-v1/v1-f2f00434d209c4e2.mp3","text":"Åbning af vogndøre samt af- og påstigning skal ske uden fare eller unødig ulempe. Kontroller cykeltrafikken og vent."},"v1-f3f592ab7043208f":{"src":"assets/voice/jeppe-neural-v1/v1-f3f592ab7043208f.mp3","text":"Hvad gælder præcis kl. 20.00? En 17-årig kører alene i Danmark og holder lovligt ind kl. 19.59. Personen vil fortsætte kl. 20.00 uden ledsager."},"v1-f435040e5b7dd044":{"src":"assets/voice/jeppe-neural-v1/v1-f435040e5b7dd044.mp3","text":"Regner med, at dobbelt fart kun giver dobbelt risiko."},"v1-f4a928ea34168237":{"src":"assets/voice/jeppe-neural-v1/v1-f4a928ea34168237.mp3","text":"I Danmark må en 17-årig køre uden ledsager fra og med kl. 05.00 til kl. 20.00."},"v1-f48d3087e938b740":{"src":"assets/voice/jeppe-neural-v1/v1-f48d3087e938b740.mp3","text":"Når ingen har ubetinget vigepligt, gælder højre vigepligt også i et T-kryds. Vejens visuelle forløb ændrer ikke reglen alene."},"v1-f480504d1676b31c":{"src":"assets/voice/jeppe-neural-v1/v1-f480504d1676b31c.mp3","text":"Elcyklen har ikke læst dit første spejlkig som en kontrakt."},"v1-f601213e624bf53e":{"src":"assets/voice/jeppe-neural-v1/v1-f601213e624bf53e.mp3","text":"STOP har ingen “men det var søndag”-undtagelse."},"v1-f4e64670e52f0c3d":{"src":"assets/voice/jeppe-neural-v1/v1-f4e64670e52f0c3d.mp3","text":"Sænker farten yderligere før bumpet."},"v1-f75d010fd0bf4796":{"src":"assets/voice/jeppe-neural-v1/v1-f75d010fd0bf4796.mp3","text":"Tilpasser farten til den korte sigt."},"v1-f7414a1b8e525b43":{"src":"assets/voice/jeppe-neural-v1/v1-f7414a1b8e525b43.mp3","text":"Har du vigepligt fra gården? Du kører ud fra en privat gård, krydser et fortov og vil ind på vejen. En cyklist og en bil nærmer sig på vejen."},"v1-f942192bc41b1c24":{"src":"assets/voice/jeppe-neural-v1/v1-f942192bc41b1c24.mp3","text":"Slipper speederen og bremser kontrolleret i god tid."},"v1-fb01b1e67cd0e956":{"src":"assets/voice/jeppe-neural-v1/v1-fb01b1e67cd0e956.mp3","text":"Bruger højre vigepligt og kører foran bilen fra venstre."},"v1-f7a1d99896a2344c":{"src":"assets/voice/jeppe-neural-v1/v1-f7a1d99896a2344c.mp3","text":"Vælger en fart, hvor jeg kan reagere inden for det overskuelige område."},"v1-fae9522c4932bec4":{"src":"assets/voice/jeppe-neural-v1/v1-fae9522c4932bec4.mp3","text":"Hvordan håndterer du telefonen? Telefonen vibrerer i din håndholder med en vigtig besked. Du kører i tæt trafik og skal trykke flere gange for at læse den."},"v1-fd27399af614c519":{"src":"assets/voice/jeppe-neural-v1/v1-fd27399af614c519.mp3","text":"Passageren er et menneske, ikke en pitstoprekord."},"v1-fc0fd99076923f63":{"src":"assets/voice/jeppe-neural-v1/v1-fc0fd99076923f63.mp3","text":"Overhaler tæt, fordi bilen er hurtigere."},"v1-fc3fa3e8b7f5f34e":{"src":"assets/voice/jeppe-neural-v1/v1-fc3fa3e8b7f5f34e.mp3","text":"Kører først, fordi min vej ser lidt bredere ud."},"v1-fc3d2b9646b270b2":{"src":"assets/voice/jeppe-neural-v1/v1-fc3d2b9646b270b2.mp3","text":"Antager, at blinket er glemt, fordi lastbilen ligger mod venstre."},"v1-ff5f6ef6deafd8eb":{"src":"assets/voice/jeppe-neural-v1/v1-ff5f6ef6deafd8eb.mp3","text":"Bakker i nødsporet."},"v1-aa1be3969d270c16":{"src":"assets/voice/jeppe-neural-v1/v1-aa1be3969d270c16.mp3","text":"Antager, at alle børn venter på en voksen."},"v1-fd8eaa21f52b285b":{"src":"assets/voice/jeppe-neural-v1/v1-fd8eaa21f52b285b.mp3","text":"Tom tagboks: dyr hat, nul personlighed."},"v1-fec82eec83c84b5d":{"src":"assets/voice/jeppe-neural-v1/v1-fec82eec83c84b5d.mp3","text":"Svinger foran cyklisten, fordi cyklisten kommer fra højre på den nye vej."},"v1-aadf70561f1b6559":{"src":"assets/voice/jeppe-neural-v1/v1-aadf70561f1b6559.mp3","text":"Behandler tavlen som B 11 uden stoppligt."},"v1-aa5922ef9ba4190f":{"src":"assets/voice/jeppe-neural-v1/v1-aa5922ef9ba4190f.mp3","text":"Udkørsel fra område uden for vejen giver ubetinget vigepligt over for trafikken på vejen."},"v1-aa855ecbcee26d36":{"src":"assets/voice/jeppe-neural-v1/v1-aa855ecbcee26d36.mp3","text":"Den sikre plan er ingen alkohol før kørsel."},"v1-aa45dd1dfbe9a41b":{"src":"assets/voice/jeppe-neural-v1/v1-aa45dd1dfbe9a41b.mp3","text":"Hvordan bruger du øveprøven? I NATKØRSEL-øveprøven er du i tvivl om situation 8. Der er tid tilbage, og prøvefladen giver mulighed for markering og navigation."},"v1-00660d73e22af6c1":{"src":"assets/voice/jeppe-neural-v1/v1-00660d73e22af6c1.mp3","text":"Fordi den konkrete udførelse kan skabe fare eller unødig ulempe, som grundreglen kræver, at du undgår."},"v1-00c96e42dd0abba3":{"src":"assets/voice/jeppe-neural-v1/v1-00c96e42dd0abba3.mp3","text":"Sele, børn og ansvar. Sikkerhedssele reducerer risikoen for alvorlig skade og skal bruges på korte ture også. Børn under 135 cm skal som hovedregel bruge godkendt sikkerhedsudstyr tilpasset barnets højde og vægt. Føreren er ansvarlig for, at passagerer under 15 år bruger sele eller andet godkendt sikkerhedsudstyr."},"v1-0161ca68d9346b76":{"src":"assets/voice/jeppe-neural-v1/v1-0161ca68d9346b76.mp3","text":"Skævt slid tyder på fejl, sidevindsfølsomhed kan pege på forkert dæktryk, og forholdene skal straks afhjælpes."},"v1-022f440ed69cefdb":{"src":"assets/voice/jeppe-neural-v1/v1-022f440ed69cefdb.mp3","text":"Tavler, signaler og vejarbejde. B 11 Ubetinget vigepligt kræver, at man holder tilbage; fuldt stop kræves kun, hvis situationen kræver det. B 13 Stop kræver fuld standsning ved stoplinjen og derefter ubetinget vigepligt. C 55 angiver den højest tilladte hastighed fra tavlen, men forholdene kan kræve lavere fart. D 15 Påbudt passage viser med pilen, hvilken side tavlen skal passeres på. Ved vejarbejde gælder midlertidig gul afmærkning frem for modstridende hvid afmærkning."},"v1-0286b0592a39d0fc":{"src":"assets/voice/jeppe-neural-v1/v1-0286b0592a39d0fc.mp3","text":"ATV-typen følger personbilens udstyrskrav, men kan have en særregel om styrthjelm, hvis den er åben."},"v1-02bce5cd927ae6c7":{"src":"assets/voice/jeppe-neural-v1/v1-02bce5cd927ae6c7.mp3","text":"Parkeringsfærdigheden er et fysisk præstationskrav og skal trænes med kørelærer; mikrolektionen gennemfører ikke øvelsen."},"v1-02d680a9f04268eb":{"src":"assets/voice/jeppe-neural-v1/v1-02d680a9f04268eb.mp3","text":"Du holder for rødt i højre bane, og en ambulance nærmer sig bagfra med fri passage i venstre bane."},"v1-02aa7e9c7cb26a79":{"src":"assets/voice/jeppe-neural-v1/v1-02aa7e9c7cb26a79.mp3","text":"Forudseenhed, jævn fart og bevidst brug af biltypen reducerer energi, støj og unødige udledninger. Start, når turen starter. Start først forbrændingsmotoren umiddelbart før afgang. Undgå længere tomgang, og brug automatisk stop ved korte standsninger, hvis bilen har funktionen. Ved længere ventetid kan motoren slukkes. Det begrænser både energi, støj og luftforurening. Jævnhed og gearvalg. Undgå gentagne fartændringer. Ved fartreduktion slippes speederen helt, og i en bil med kobling undgås udkobling så vidt muligt. I en relevant manuelt gearet bil kan korrekt, tidligt gearvalg eksempelvis være skift fra 2. til 4. eller fra 3. til 5. gear efter kvik acceleration med cirka halv speeder. Modstand koster energi. Unødig vægt, for lavt dæktryk og en tagboks øger energiforbruget. Aircondition, klimaanlæg og andet elektrisk udstyr bruger også energi. Bilens eventuelle forbrugsvisning kan gøre virkningen synlig, så føreren kan justere sine vaner. Se rødt lys tidligt. Høj fart og aggressiv acceleration øger forbruget. Frem mod et signal bør føreren forudse et muligt stop og sænke farten tidligt i stedet for at fortsætte hurtigt og bremse hårdt. Energiøkonomisk teknik kan normalt spare 5-10 procent og i mange tilfælde op til 25 procent brændstof. Planlæg før du kører. Undgå korte, unødvendige ture. Når det er muligt, kan turen flyttes uden for myldretiden, deles med andre eller gennemføres i et mere energieffektivt og mindre forurenende køretøj. Den bedste sparemanøvre kan være at planlægge anderledes. Hybrid kræver opladning. Hybrid- og plug-in-hybridbiler kombinerer forbrændingsmotor og elmotor for at forbedre energiforbruget mest muligt. Plug-in-modellen er kun miljøvenlig og energieffektiv, når opladningsmuligheden gennem en ladestander udnyttes mest muligt. Den faktiske opladning er derfor afgørende for den tilsigtede energi- og miljøfordel. Elbilens rækkevidde. Elbiler udnytter generelt energien bedre end fossilbiler. Rækkevidden påvirkes af køremåde og årstid. På lange ture skal rute og ladestop planlægges omhyggeligt, gerne med relevante apps, og regeneration bør udnyttes mest muligt, når forholdene tillader det. Støj og røg er ikke gratis. Bilen skal betjenes uden unødig støj eller unødige mængder røg og gas. Forstyrrende kørsel ved bebyggelse skal undgås eller udføres med mindst mulig gene. Lokale bestemmelser kan desuden sætte en konkret grænse for tomgang."},"v1-0332433dc4dda745":{"src":"assets/voice/jeppe-neural-v1/v1-0332433dc4dda745.mp3","text":"Behold banen, afbryd om nødvendigt tegnet og vent på et sikkert ophold. Blinket oplyser om hensigten; det pålægger ikke den anden bil at give plads."},"v1-03aa2904c91fd281":{"src":"assets/voice/jeppe-neural-v1/v1-03aa2904c91fd281.mp3","text":"Orientering ved sving og krydsning af cykelsti skal trænes i rigtig trafik med kørelærer."},"v1-04246a43b580bee6":{"src":"assets/voice/jeppe-neural-v1/v1-04246a43b580bee6.mp3","text":"Sprinkler og viskere. I undervisningsbilen og sammen med kørelæreren: kontrollér væskemængden efter bilens løsning og instruktionsbog, aktivér vasker og viskere, og vurder om viskerne kan holde forruden ren. Spejlkontrol. Indstil siddestillingen først. Kontrollér derefter med kørelæreren, at spejle eller monitorer er rene, hele og korrekt indstillet for den konkrete bil. Den fysiske præstation vurderes ved bilen."},"v1-0437bd949510974f":{"src":"assets/voice/jeppe-neural-v1/v1-0437bd949510974f.mp3","text":"Hvorfor er trailerens tilladte totalvægt ikke det eneste, der skal kontrolleres?"},"v1-04a538de09e40370":{"src":"assets/voice/jeppe-neural-v1/v1-04a538de09e40370.mp3","text":"Hvordan kontrolleres ratslør i en bil med servostyring?"},"v1-04c550262fec791c":{"src":"assets/voice/jeppe-neural-v1/v1-04c550262fec791c.mp3","text":"Plan B beskriver præcis de to tegn og knytter dem henholdsvis til koblingen og til gear eller kobling."},"v1-04f1f9cd7d28a1a7":{"src":"assets/voice/jeppe-neural-v1/v1-04f1f9cd7d28a1a7.mp3","text":"Hastighed og bevægelsesenergi. Når hastigheden stiger, vokser både reaktionsstrækning og bremselængde. Bevægelsesenergien vokser kraftigt med hastigheden, så et sammenstød bliver mere alvorligt. En lille hastighedsnedsættelse kan give en stor sikkerhedsgevinst."},"v1-066f8cb8940944d8":{"src":"assets/voice/jeppe-neural-v1/v1-066f8cb8940944d8.mp3","text":"Du holder ved kantstenen og vil sætte i gang, mens en cyklist nærmer sig bagfra langs bilens højre side."},"v1-076dd8f4831e8129":{"src":"assets/voice/jeppe-neural-v1/v1-076dd8f4831e8129.mp3","text":"Fordi dens opladningsmulighed skal udnyttes mest muligt; køremåde, tomgang, vægt og turplanlægning har stadig betydning."},"v1-07e6765327a67820":{"src":"assets/voice/jeppe-neural-v1/v1-07e6765327a67820.mp3","text":"Hvorfor skal orienteringen gentages lige før højresvinget?"},"v1-08181ac39feaef4a":{"src":"assets/voice/jeppe-neural-v1/v1-08181ac39feaef4a.mp3","text":"Opspeedningen viser udstødningsfejl, mens mislydene viser, at batteriets kapacitet er blevet for lav."},"v1-08494d89dbbcdd68":{"src":"assets/voice/jeppe-neural-v1/v1-08494d89dbbcdd68.mp3","text":"Lovlighed og sikkerhed er to nært beslægtede ansvar, som skal være afklaret før og under kørslen. To slags ansvar. Ejeren eller den registrerede bruger har ansvaret for, at bilen er lovlig. Føreren har ansvaret for, at den er sikkerhedsmæssigt forsvarlig. En lånt bil flytter derfor ikke førerens pligt til at reagere på fejl, som kan gøre turen farlig. Opmærksom hele turen. Førerens kontrol slutter ikke, når bilen starter. Styring, bremser, lygter og horn skal fungere sikkert og efter reglerne, og en trailer skal være forsvarligt koblet. Nye lyde, lamper eller ændret adfærd undervejs kræver en konkret vurdering. Støj og udledning tæller også. Føreren skal være opmærksom på unødig støj og på fejl ved motor eller forureningsbegrænsende udstyr, som påvirker udledningen. Usædvanlig røg eller lyd er derfor ikke blot bilens humør; det kan være et tegn på ulovlig eller uforsvarlig stand."},"v1-08750c2fbf6a4a91":{"src":"assets/voice/jeppe-neural-v1/v1-08750c2fbf6a4a91.mp3","text":"Forklar tre koblingstilstande. Beskriv med ord, hvad der sker mellem motor og gearkasse, når koblingspedalen er oppe, helt nede og løftes langsomt. Afslut med at forklare, hvorfor øvelsen ikke passer til en elbil eller en bil uden koblingspedal."},"v1-08926d24b739f40a":{"src":"assets/voice/jeppe-neural-v1/v1-08926d24b739f40a.mp3","text":"Den afsluttende kørsel samler færdigheder og refleksion i et fysisk forløb med kørelæreren. Fælles mål. Kørelærer og elev opstiller gennem dialog fælles mål for hver lektion og følger op med refleksion. Målet kan handle om en svaghed, en vejtype eller selvstændig planlægning. Det gør turen læringsstyret frem for blot gennemkørt. Bil og hjælpemidler. Eleven videreudvikler kontrol af bilens stand, forståelse af førerassistentsystemer og energi- og miljørigtig kørsel. GPS og assistenter kan indgå i ruteplanen, men eleven skal stadig orientere sig og prioritere den faktiske trafik. Mennesker og vej. Forløbet skal udvikle indsigt i egne styrker og svagheder, samarbejde med især sårbare trafikanter og forståelse af skiftende vejrisici. Refleksionen skal føre til en mere selvstændig, hensynsfuld og ansvarlig køremåde."},"v1-08dfb7567f5c377d":{"src":"assets/voice/jeppe-neural-v1/v1-08dfb7567f5c377d.mp3","text":"Afsluttende sammensat kørsel. Afsnit 7.22 er afsluttende praktisk kørsel i skiftende situationer; kørelærer og elev fastlægger fælles mål og følger op med refleksion. Eleven skal øve selvstændig, hensynsfuld, ansvarlig og energi- og miljørigtig kørsel. Et samlet forløb kan omfatte kontrol af bilen, brug af førerstøttesystemer, ruteplanlægning eller GPS og tidligere vejmanøvrer. Førerstøtte og navigation er hjælpemidler; eleven skal fortsat orientere sig og reagere på den faktiske trafik. Appens scenarier kan forberede refleksion, men kan ikke gennemføre eller dokumentere den praktiske lektion med kørelærer."},"v1-08e18102d5250219":{"src":"assets/voice/jeppe-neural-v1/v1-08e18102d5250219.mp3","text":"Hvis føreren senere skal bruge en trailer, bør kobling, kontrol og kørsel læres på den konkrete kombination. Denne mikrolektion dokumenterer ikke sådan praktisk instruktion og er ikke et gennemført kategori B-krav."},"v1-08fb00a1c5f85608":{"src":"assets/voice/jeppe-neural-v1/v1-08fb00a1c5f85608.mp3","text":"Igangsætning og standsning bliver sikre, når observation, tydelig kommunikation og præcis betjening sker i den rigtige rækkefølge. Skab et hul før du bevæger bilen. Orientér dig fremad, i spejle og direkte mod skjulte områder, før du sætter i gang. Vurder ikke kun, om vejen er tom nu, men også om en cyklist eller bil kan nå frem, mens bilen forlader kanten. Blinklyset fortæller, det giver ikke plads. Giv tegn i god tid, når andre har nytte af det, men vent stadig på et sikkert hul. Et blinklys oplyser om din hensigt; det ændrer ikke andre trafikanters fart, placering eller ret til at fortsætte. Standsningen planlægges bagfra. Se tidligt efter et lovligt og overskueligt sted, kontrollér trafikken bagved, og sænk farten jævnt. Den sidste placering ved kanten bliver lettere, når du har skabt tid til styre- og bremsekorrektioner."},"v1-09767516d38ec97f":{"src":"assets/voice/jeppe-neural-v1/v1-09767516d38ec97f.mp3","text":"Stands, skab overblik, advar trafikken og flyt kun bilerne, hvis det er sikkert og pligterne kan opfyldes. Et lille uheld må ikke udvikle sig til en påkørsel."},"v1-0a52c15f0bfbdce2":{"src":"assets/voice/jeppe-neural-v1/v1-0a52c15f0bfbdce2.mp3","text":"Hvordan adskiller forudseenhed sig fra at gætte?"},"v1-0b0bd5794d628ffb":{"src":"assets/voice/jeppe-neural-v1/v1-0b0bd5794d628ffb.mp3","text":"Sænk farten, ret blikket længere frem på den ønskede linje, og brug korte kontrolblik til siden. Det længere blik afslører kursændringen tidligere, så ratbevægelserne kan blive mindre og bilen mere stabil."},"v1-0b1cee826ada0fca":{"src":"assets/voice/jeppe-neural-v1/v1-0b1cee826ada0fca.mp3","text":"Hvorfor kan du ikke behandle prøven som klassisk ét-svar-multiple-choice?"},"v1-0bcfa681f4c4fcb9":{"src":"assets/voice/jeppe-neural-v1/v1-0bcfa681f4c4fcb9.mp3","text":"Et sikkert venstresving kræver, at du fordeler opmærksomheden mellem modkørende, sideveje og udkørslen. Placering og bagfrakommende. Giv tegn i passende afstand, kontroller spejle og blind vinkel til venstre, og placér bilen i venstre del af egen kørselsretning eller anvist svingbane. Bagfrakommende motorcyklister kan forsøge at overhale netop dér. Modkørende bestemmer opholdet. Hold tilbage for modkørende, der fortsætter ligeud eller svinger til højre. Bedøm både afstand og hastighed, især for små hurtige køretøjer. Et grønt hovedsignal uden grøn venstrepil betyder ikke fri bane gennem de modkørende. Se udgangen før du kører. Vent, hvis en modkørende venstresvinger skjuler trafikken bag sig. Før afslutningen skal du også se efter gående og cyklister ved den vej, du svinger ind på, og sikre plads i den valgte bane."},"v1-0c097a241e2bf9b4":{"src":"assets/voice/jeppe-neural-v1/v1-0c097a241e2bf9b4.mp3","text":"Start ved afgang og behold lave gear for trækkraft; hold normal fart mod signalet, før der bremses jævnt."},"v1-0c5400c38729603b":{"src":"assets/voice/jeppe-neural-v1/v1-0c5400c38729603b.mp3","text":"Hvilken mulighed skal være planlagt før en overhaling begynder?"},"v1-0c9e2cbeb16b1bd4":{"src":"assets/voice/jeppe-neural-v1/v1-0c9e2cbeb16b1bd4.mp3","text":"Afbryd tidligt og træk sikkert tilbage bag traktoren, hvis opholdet stadig er åbent. Den planlagte afslutning har mistet nødvendig plads og sideafstand, og en fortsættelse kan presse cyklisten eller møde modkørende uden en sikker flugtvej."},"v1-0cf28c0bda6014fe":{"src":"assets/voice/jeppe-neural-v1/v1-0cf28c0bda6014fe.mp3","text":"Blindzoner er skiftende områder uden sikkert udsyn, som kræver placering, direkte orientering og forudseenhed. Spejlene overlapper, men dækker ikke alt. Sidespejl og bakspejl giver forskellige udsnit, og en trafikant kan bevæge sig fra ét udsnit til et skjult område. Følg trafikanter over tid, og supplér med direkte orientering før sideværts bevægelse. Blindzonen flytter sig. Når din bil eller den anden trafikant ændrer fart og retning, ændres det skjulte område også. En cyklist, du så for et øjeblik siden, skal derfor genfindes visuelt, før du krydser den forventede bane. Placering kan skabe tid. Undgå at blive liggende tæt ved siden af et stort køretøj, hvor føreren kan have svært ved at se dig. Skab afstand, og passér kun, når forløbet er tydeligt og kan afsluttes uden at blive fanget ved et sving."},"v1-0cfa2d85f7e66cbe":{"src":"assets/voice/jeppe-neural-v1/v1-0cfa2d85f7e66cbe.mp3","text":"Bilens lys skal både oplyse vejen og gøre køretøjet tydeligt uden at blænde andre. Det obligatoriske lyssæt. Bilen skal have to fjernlys, to asymmetriske nærlys, to positionslys, to baglys, normalt tre stoplys, mindst ét nummerpladelys, blinklys foran, bagpå og på siderne samt to røde, godkendte, mærkede og ikke-trekantede bagreflekser. Tre afstande og én plade. Fjernlys skal oplyse mindst 100 meter frem. Nærlys skal nå mindst 30 meter uden at blænde. Positionslys skal kunne ses mindst 300 meter væk. Nummerpladelyset skal gøre den bageste plade læselig mindst 20 meter bag bilen. Farver og par. Forlygter skal lyse hvidt eller gulligt, mens baglygter skal lyse rødt. Pærer skal sidde korrekt, og lygter i samme par skal have ens farve og lysstyrke. Alle lygter og reflekser skal være hele, rene og funktionsdygtige. Lange biler. En bil over 6 meter skal have godkendte og mærkede gule sidereflekser samt sidemarkeringslygter fordelt på siderne. Kravet er knyttet til bilens længde og skal ikke forveksles med de supplerende reflekser, som kan være tilladt på andre biler. Tilladte ekstra lygter og reflekser. Tilladt ekstraudstyr omfatter ekstra fjernlys, kørelys, ekstra stop- og baglygter, tågeforlygter, baklygter, tågebaglygter, søge- og arbejdslygter, afmærknings- og markeringslygter, parkeringslygter og overhalingsblink. Desuden må bilen have hvide reflekser foran, gule på siderne og supplerende røde bagpå. Udstyret følger særlige regler. Nærlysets grænse. En forkert monteret pære kan give et forkert lysbillede. Mod en væg kan lys-mørke-grænsen vurderes. Nærlyset må ikke blænde, og overkanten af lysgrænsen skal falde 1 centimeter for hver meter væk fra bilen. Rundt om bilen. Kontrollen omfatter hele og rene lygter og reflekser, kraftigere stoplys end baglys, synligt gult blinklys, samlet havariblink, hvidt nummerpladelys og et horn med klar, konstant tone. Hurtig blinkrytme betyder normalt, at mindst én blinklygte ikke virker."},"v1-0d276c5de7b625c2":{"src":"assets/voice/jeppe-neural-v1/v1-0d276c5de7b625c2.mp3","text":"Rækkefølge, koblingspunkt og jævn betjening kræver fysisk øvelse med kørelærer."},"v1-0d72ecc23aacd6c6":{"src":"assets/voice/jeppe-neural-v1/v1-0d72ecc23aacd6c6.mp3","text":"Du kommer for hurtigt ind i en våd kurve og overvejer både at dreje kraftigt og bremse hårdt."},"v1-0d834dfc21ee7c32":{"src":"assets/voice/jeppe-neural-v1/v1-0d834dfc21ee7c32.mp3","text":"Planen gør både skævt slid og den unormale styreadfærd til fejltegn og kræver umiddelbar afhjælpning af årsagen."},"v1-0dbc2b98d35f88e8":{"src":"assets/voice/jeppe-neural-v1/v1-0dbc2b98d35f88e8.mp3","text":"Om tavler, afmærkning eller vejens udformning allerede giver en af parterne ubetinget vigepligt."},"v1-0de342d7398142d1":{"src":"assets/voice/jeppe-neural-v1/v1-0de342d7398142d1.mp3","text":"Hvorfor skal du søge igen efter en cyklist, der kortvarigt forsvinder bag en forhindring?"},"v1-0fc362a6bb487fb4":{"src":"assets/voice/jeppe-neural-v1/v1-0fc362a6bb487fb4.mp3","text":"Fordi en ændret siddestilling også ændrer synsvinklen i spejlene og kan gøre den tidligere indstilling misvisende."},"v1-0fe477684f521017":{"src":"assets/voice/jeppe-neural-v1/v1-0fe477684f521017.mp3","text":"Systemet kan vise forkert; føreren afbryder funktionen, hvorefter den viste tavleinformation får forrang."},"v1-10a713028d7254eb":{"src":"assets/voice/jeppe-neural-v1/v1-10a713028d7254eb.mp3","text":"Hvordan kan et busstoppested ændre din kørsel, selv når ingen person står i kørebanen?"},"v1-10a783b9b4a33b24":{"src":"assets/voice/jeppe-neural-v1/v1-10a783b9b4a33b24.mp3","text":"Gearvælger med gearenes placering, parkeringsbremsens betjening og rattet."},"v1-1233a2b0e558d7fc":{"src":"assets/voice/jeppe-neural-v1/v1-1233a2b0e558d7fc.mp3","text":"Hvorfor skal sædet indstilles før spejlene?"},"v1-12866efe8861a152":{"src":"assets/voice/jeppe-neural-v1/v1-12866efe8861a152.mp3","text":"Må en 17-årig køre alene i Sverige klokken 12?"},"v1-13f136a71b6fc2d4":{"src":"assets/voice/jeppe-neural-v1/v1-13f136a71b6fc2d4.mp3","text":"Hvorfor skal du orientere dig igen mellem vendingens enkelte bevægelser?"},"v1-14188767315720cb":{"src":"assets/voice/jeppe-neural-v1/v1-14188767315720cb.mp3","text":"Ingenting: føreren skal fortsat observere, vurdere og handle og kan ikke overlade ansvaret til systemet."},"v1-14ae9ba964317c2d":{"src":"assets/voice/jeppe-neural-v1/v1-14ae9ba964317c2d.mp3","text":"STOP betyder stop. Ved STOP skal bilen standses helt ved stoplinjen; uden stoplinje standses før krydset, og om nødvendigt standses igen for at få udsyn. Efter standsning gælder den ubetingede vigepligt stadig. En rullende næsten-standsning opfylder ikke stopkravet."},"v1-14ce0bfbb0daac45":{"src":"assets/voice/jeppe-neural-v1/v1-14ce0bfbb0daac45.mp3","text":"I tæt tåge kan du kun se få vejmarkeringer frem, selv om bilen foran fortsætter med uændret fart."},"v1-1544286a19668522":{"src":"assets/voice/jeppe-neural-v1/v1-1544286a19668522.mp3","text":"Det peger alene på for lidt servovæske; styreforbindelserne kræver derfor ikke nærmere eftersyn."},"v1-158f986dd8adda91":{"src":"assets/voice/jeppe-neural-v1/v1-158f986dd8adda91.mp3","text":"Hvorfor bør registreringsoplysninger kontrolleres, selv når bilen ser stor nok ud til traileren?"},"v1-15a6c8830a94317e":{"src":"assets/voice/jeppe-neural-v1/v1-15a6c8830a94317e.mp3","text":"Følg den gule linjeføring med lavere fart og kontroller nabobanen. Midlertidig gul afmærkning styrer over den modstridende permanente hvide afmærkning, mens den lavere fart giver tid til at opdage flyttede baner og arbejdere."},"v1-15afdc582f20be68":{"src":"assets/voice/jeppe-neural-v1/v1-15afdc582f20be68.mp3","text":"En 17-årig vil køre alene hjem klokken 19.40, men turen forventes først afsluttet klokken 20.10."},"v1-15ca78d39a0bcc9b":{"src":"assets/voice/jeppe-neural-v1/v1-15ca78d39a0bcc9b.mp3","text":"En lovligt registreret bil lånes med påhængskøretøj. Hvilken ansvarsfordeling gengiver Plan B præcist?"},"v1-15e47d81a9509b21":{"src":"assets/voice/jeppe-neural-v1/v1-15e47d81a9509b21.mp3","text":"Nye bilister og gyldighed. I de første tre år efter første B-kørekort er den juridiske tærskel over 0,20 ‰ i blodet eller over 0,10 mg alkohol pr. liter udåndingsluft, uanset alder. Myndighedernes praktiske råd til nye bilister er at lade være med at drikke alkohol før kørsel. En bestået teoriprøve er gyldig i 18 måneder, men er ikke i sig selv et kørekort."},"v1-15f2a3369252ff62":{"src":"assets/voice/jeppe-neural-v1/v1-15f2a3369252ff62.mp3","text":"Danmark tillader kopier, men ved kørsel i udlandet kræver planen originaler eller en genpart udstedt af Motorstyrelsen."},"v1-16379a793c8a5001":{"src":"assets/voice/jeppe-neural-v1/v1-16379a793c8a5001.mp3","text":"Viskernes bevægelse opfylder kontrollen alene; sprinklervæsken kan vente, hvis der ikke forventes regn."},"v1-16463a5eaec4bedd":{"src":"assets/voice/jeppe-neural-v1/v1-16463a5eaec4bedd.mp3","text":"Farttilpasning og placering skal opleves og korrigeres under øvelseskørsel på by- og landevej."},"v1-17730b5c57cf92cd":{"src":"assets/voice/jeppe-neural-v1/v1-17730b5c57cf92cd.mp3","text":"Letbanetog følger et bundet spor og kan ikke undvige din fejlplacering. Lang bremselængde. Letbanetog har lang bremselængde og kan ikke styre uden om bilen. Kontroller tog, spor og sporets fortsatte forløb før krydsning, sving eller forbikørsel. Gå aldrig ud fra, at toget kan løse konflikten. Læs det rigtige signal. Følg hovedsignal og tavler for din egen kørselsretning. X 19 med hvide lys gælder for busser i rutekørsel, letbanekøretøjer og nulemissionsbiler, ikke automatisk din bil. V 43 markerer en bane for letbanekøretøjer. Undervisningsformen. Praktisk kørsel ved letbane er obligatorisk, når en lektion på mindst 45 minutter tillader turen til, ved og tilbage fra letbanen. Ellers skal de praktiske færdigheder undervises i teorilokalet; emnet må ikke blot udelades."},"v1-1870e723484008f6":{"src":"assets/voice/jeppe-neural-v1/v1-1870e723484008f6.mp3","text":"Hvilken rækkefølge styrer de første handlinger ved et uheld?"},"v1-17ea8e983d657560":{"src":"assets/voice/jeppe-neural-v1/v1-17ea8e983d657560.mp3","text":"Hvad er forskellen på at se et kontrollys og at forstå det?"},"v1-1777a9646f49d072":{"src":"assets/voice/jeppe-neural-v1/v1-1777a9646f49d072.mp3","text":"Forruden har indvendig film, sprinklervæsken er næsten tom, og viskerne bevæger sig. Hvilken kontrol og vurdering følger Plan B?"},"v1-189c6d4c79eb50ed":{"src":"assets/voice/jeppe-neural-v1/v1-189c6d4c79eb50ed.mp3","text":"Førerens holdning viser sig i de sikkerhedsmargener, der vælges, når tidspres, irritation eller gruppepres opstår. Normalisering flytter grænsen. Når en risikofyldt vane gentages uden uheld, kan den begynde at føles sikker. Fravær af en konsekvens er ikke bevis for god kørsel. Vurder handlingen efter risiko og regler, ikke efter tidligere held. Tidspres skal løses uden fartpres. Forsinkelse kan få en fører til at forkorte afstande og acceptere usikre huller. Anerkend presset, bevar den nødvendige margin, og lad ankomsttiden ændre sig frem for at flytte risikoen over på andre. Defensiv kørsel giver plads til andres fejl. Du kan følge reglerne og stadig møde en trafikant, der overser dig. Afstand, moderat fart og tydelig kommunikation skaber handlemuligheder, når andre handler uventet, uden at du behøver afgøre skyld i øjeblikket."},"v1-195b76418798e717":{"src":"assets/voice/jeppe-neural-v1/v1-195b76418798e717.mp3","text":"Du bakker ud fra en indkørsel; kameraet viser fri vej, men en hæk skjuler fortovet i højre side."},"v1-1978fe36ce3c66b8":{"src":"assets/voice/jeppe-neural-v1/v1-1978fe36ce3c66b8.mp3","text":"Hvilke to ting skal fortsat være opfyldt efter dit blink?"},"v1-195d8baa9e6ec0cd":{"src":"assets/voice/jeppe-neural-v1/v1-195d8baa9e6ec0cd.mp3","text":"Bilens mystiske røg er ikke en atmosfærisk feature."},"v1-190b616779f57afa":{"src":"assets/voice/jeppe-neural-v1/v1-190b616779f57afa.mp3","text":"Fri passage skabes med rolig koordinering, ikke ved at erstatte én nødsituation med en anden. Se hele situationen. Når et udrykningskøretøj nærmer sig med særligt lyd- eller lyssignal, skal du først lokalisere det og se, hvad andre gør. Sæt farten ned og skab plads tydeligt uden at skabe en ny fare. Pludselig opbremsning eller et uvarslet sideskift kan blokere mere end det hjælper. Rødt er stadig rødt. Et udrykningskøretøj bag dig ændrer ikke dit røde signal til grønt. Flyt kun bilen, hvis det kan ske lovligt og sikkert; ellers bliv forudsigeligt holdende, så udrykningsføreren kan vælge en anden passage. Efter passagen. Når udrykningen er forbi, skal du kontrollere spejle, blinde vinkler og øvrig trafik før du vender tilbage til normal placering. Flere udrykningskøretøjer kan følge efter, og andre trafikanter kan have flyttet sig uventet."},"v1-1a34b10582ac7969":{"src":"assets/voice/jeppe-neural-v1/v1-1a34b10582ac7969.mp3","text":"Hvad er målet, når du giver fri passage?"},"v1-1ac6e515582ee96a":{"src":"assets/voice/jeppe-neural-v1/v1-1ac6e515582ee96a.mp3","text":"Bremsekontrol og bremseprøve skal demonstreres og øves fysisk med kørelærer på et egnet sted."},"v1-1ba79c639efcba71":{"src":"assets/voice/jeppe-neural-v1/v1-1ba79c639efcba71.mp3","text":"Denne mulighed passer ikke her."},"v1-1c14e62443dceb2e":{"src":"assets/voice/jeppe-neural-v1/v1-1c14e62443dceb2e.mp3","text":"Bed passageren vente, kontrollér trafikken bagud, og åbn først, når cyklisten er passeret og området er frit. En pludselig dør i cyklistens linje efterlader meget lidt mulighed for at undvige og kan skabe alvorlig fare."},"v1-1cf164d8c3e5fe68":{"src":"assets/voice/jeppe-neural-v1/v1-1cf164d8c3e5fe68.mp3","text":"Ved vognbaneskift har den skiftende fører ansvaret; ved reel sammenfletning skal begge strømme tilpasse sig gensidigt."},"v1-1fb01b2b7e5fc72e":{"src":"assets/voice/jeppe-neural-v1/v1-1fb01b2b7e5fc72e.mp3","text":"Fordi samtalen eller opgaven kan beslaglægge forståelse og beslutningskapacitet, selv om begge hænder er på rattet."},"v1-1d2eea2aa2338e15":{"src":"assets/voice/jeppe-neural-v1/v1-1d2eea2aa2338e15.mp3","text":"Hvad er forskellen på en vejstrækning, der ser tom ud, og en strækning, der kan overskues som fri?"},"v1-204a655372ebaf8f":{"src":"assets/voice/jeppe-neural-v1/v1-204a655372ebaf8f.mp3","text":"Behandl det som vognbaneskift og vent på et sikkert ophold. Du krydser en vognbanelinje og har ansvaret for ikke at genere trafikken i banen."},"v1-214be3bd32940ec3":{"src":"assets/voice/jeppe-neural-v1/v1-214be3bd32940ec3.mp3","text":"Jo mere kraft dækkene bruger i én retning, desto mindre reserve er der til den anden."},"v1-2195a05d9a2e23bd":{"src":"assets/voice/jeppe-neural-v1/v1-2195a05d9a2e23bd.mp3","text":"Når udsyn, vejgreb, last, fart eller opmærksomhed gør reaktion og standsning mere krævende."},"v1-20f1f1d75e85a5f9":{"src":"assets/voice/jeppe-neural-v1/v1-20f1f1d75e85a5f9.mp3","text":"Fordi lavere indgangsfart bevarer vejgreb og handlemuligheder, mens en aktiv udskridning giver meget mindre reserve."},"v1-20b19d9b15f56e58":{"src":"assets/voice/jeppe-neural-v1/v1-20b19d9b15f56e58.mp3","text":"Lær systemernes typiske hjælp, deres sanser og grænser samt bilens konkrete signaler. Bilen sanser gennem teknik. Planen beskriver alle nyere biler som udstyret med førerassistenter, der kan vejlede eller gribe ind i faresituationer. Den beskriver kameraer, sensorer og radarer som fælles teknologier bag overvågningen. Det betyder ikke, at hvert system bruger alle tre samtidigt; mulige indgreb sker via bremser eller styring. Afstand, blind vinkel og vognbane. Adaptiv fartpilot kan tilpasse afstand og hastighed til forankørende. Blindvinkelassistent kan advare om trafikanter ved siden af bilen, og vognbaneassistent kan reagere, hvis bilen forlader en markeret bane. Advarsler kan være lys, lyd eller vibration; visse systemer kan også gribe ind. Parkering og nødbremsning. Parkeringssensorer vurderer afstand og advarer med lyd eller lys. En parkeringsassistent kan i nogle biler udføre bestemte parkeringsbevægelser. Frontalkollisions- og nødbremseassistent kan advare om sammenstødsrisiko og i faresituationer bremse automatisk, også ved visse parkerings- eller bakkemanøvrer. Træthed, tavler og lys. Træthedsregistrering kan advare med lyd, lys eller vibration. En tavleassistent kan vise genkendte tavler og sammen med adaptiv fartpilot ændre hastigheden efter dem. Lysassistenten kan tilpasse nær- og fjernlys. Systemer kan vise forkert, så føreren skal fortsat observere og bevare ansvaret. Kritisk fører, fuldt ansvar. Et system kan overse noget, misforstå omgivelserne eller give en misvisende oplysning. Føreren har stadig ansvaret for kørslen og kan ikke henvise til assistenten efter en forseelse eller et uheld. Bekvemmeligheden kan desuden øge uopmærksomheden, så aktiv overvågning er nødvendig. Lær præcis den bil, du skal køre. Systemnavne, symboler, lyde, indstillinger og indgreb varierer mellem biler. Du skal derfor kunne aflæse og forstå samtlige førerassistenter i undervisnings- og prøvebilen. Gennemgå både systemernes status og de nødvendige reaktioner med kørelæreren i den konkrete bil."},"v1-21a119488dcbf746":{"src":"assets/voice/jeppe-neural-v1/v1-21a119488dcbf746.mp3","text":"Præcis standsning og trinvis fremkørsel skal øves med kørelærer i kryds med forskelligt udsyn."},"v1-22854fa49abd2b65":{"src":"assets/voice/jeppe-neural-v1/v1-22854fa49abd2b65.mp3","text":"Bremsepedalen skal være en bremsepedal. Ikke en elevator mod gulvet."},"v1-22052965fc46408a":{"src":"assets/voice/jeppe-neural-v1/v1-22052965fc46408a.mp3","text":"Teoriprøvens format. Kategori B-prøven viser 25 trafikale situationer med fire udsagn til hver. Der er altid mindst ét korrekt udsagn, og der kan være flere. Prøven varer 25 minutter, og højst fem fejl giver bestået."},"v1-222b4b9566581ab0":{"src":"assets/voice/jeppe-neural-v1/v1-222b4b9566581ab0.mp3","text":"På motorvej gør den høje fart tidlig planlægning vigtigere end hurtige korrektioner. Tilkørsel. Tilpas hastigheden i accelerationsbanen, og kør kun ind uden fare eller unødig ulempe. Orienter tidligt og gentaget. Trafikken i den bane, du kører ind i, skal om nødvendigt sænke hastigheden for at lette indkørslen; reglen kræver ikke et pludseligt eller uforsvarligt vognbaneskift. Løbende kørsel. Hold til højre, vælg lang sikkerhedsafstand og se langt frem efter kø eller bremselys. Baneskift kræver fuld orientering; høj fart gør små fejlbedømmelser store. Overhaling skal afsluttes med sikker afstand før tilbagevenden. Havari og forbud. Bakning, vending, standsning og parkering er forbudt uden for anviste steder, bortset fra nødsituationer. Ved havari søges så langt væk fra kørebanen som muligt, andre advares, og personer placerer sig sikkert væk fra trafikken."},"v1-236a9c8eb18b503c":{"src":"assets/voice/jeppe-neural-v1/v1-236a9c8eb18b503c.mp3","text":"Hvorfor kan en lastbil først trække væk fra den side, den bagefter drejer imod?"},"v1-22cb2d3ef7a24ba9":{"src":"assets/voice/jeppe-neural-v1/v1-22cb2d3ef7a24ba9.mp3","text":"Fordi bremselængde og bevægelsesenergi vokser kraftigere end hastigheden; ved fordobling bliver bremselængden omtrent fire gange så stor."},"v1-23faead32b8c8f7c":{"src":"assets/voice/jeppe-neural-v1/v1-23faead32b8c8f7c.mp3","text":"Sænk farten og hold tilbage, så den kan passere uden at ændre kurs eller fart. Uden anden regulering gælder højre vigepligt."},"v1-2408f7ec0be092c9":{"src":"assets/voice/jeppe-neural-v1/v1-2408f7ec0be092c9.mp3","text":"Motorvej og tæt trafik. På motorvej bruges accelerationsbanen til at tilpasse hastigheden og finde et sikkert ophold. Bakning, vending, standsning og parkering er forbudt uden for anviste steder, bortset fra nødsituationer. Ved kø skal man holde afstand, følge trafikken og være forberedt på pludselige opbremsninger."},"v1-24317d49430e0a6a":{"src":"assets/voice/jeppe-neural-v1/v1-24317d49430e0a6a.mp3","text":"Du lokaliserer og udpeger de krævede dele i den konkrete bil sammen med kørelæreren."},"v1-2433aaf3e5267f7e":{"src":"assets/voice/jeppe-neural-v1/v1-2433aaf3e5267f7e.mp3","text":"Forudseenhed: et energihack uden rabatkode."},"v1-242eb9859271685e":{"src":"assets/voice/jeppe-neural-v1/v1-242eb9859271685e.mp3","text":"Rat og blik. Bilen søger ofte i den retning, føreren ser, så blikket skal flyttes mod den ønskede kørebane. Hænderne bør give et sikkert greb og mulighed for jævn ratbetjening. Ved lav fart kan store ratudslag være nødvendige, men omgivelserne skal stadig kontrolleres."},"v1-24407d9b9c418cea":{"src":"assets/voice/jeppe-neural-v1/v1-24407d9b9c418cea.mp3","text":"De første tre år efter det første B-kørekort gælder en lav alkoholgrænse uanset førerens alder. Treårsperioden. I de første tre år efter førstegangserhvervelse af kategori B er den juridiske grænse over 0,20 promille i blodet eller over 0,10 milligram alkohol pr. liter udåndingsluft. Perioden knytter sig til første B-kørekort, ikke fødselsalderen. Praktisk råd: nul alkohol. Færdselsstyrelsen beskriver 0,2-grænsen som i praksis nul alkohol før kørsel. Individuel forbrænding og forsinket promillestigning gør egen beregning usikker. Den robuste handling er at lade være med at drikke, når du skal køre. Teori er ikke førerret. En bestået teoriprøve er gyldig i 18 måneder. Den giver ikke ret til at køre alene og er ikke et kørekort. Førerretten kræver, at hele processen, herunder praktisk prøve og øvrige betingelser, er opfyldt."},"v1-24ae88e4e1bcda24":{"src":"assets/voice/jeppe-neural-v1/v1-24ae88e4e1bcda24.mp3","text":"De praktiske lektioner, manøvrebane og køreteknisk anlæg gennemføres fysisk og registreres i uddannelsesforløbet."},"v1-24ca2b6d89589a6a":{"src":"assets/voice/jeppe-neural-v1/v1-24ca2b6d89589a6a.mp3","text":"Udskridning og undvigelse må kun trænes som den lovpligtige fysiske undervisning på køreteknisk anlæg med kørelærer."},"v1-259798ffeff7412c":{"src":"assets/voice/jeppe-neural-v1/v1-259798ffeff7412c.mp3","text":"En elev har set mange appvideoer hjemme og vil springe de sidste registrerede lektioner over."},"v1-25f007799cbbbe82":{"src":"assets/voice/jeppe-neural-v1/v1-25f007799cbbbe82.mp3","text":"Planen behandler filmen som en selvstændig udsynsrisiko i modlys, og spejlkravene erstatter ikke kravet om en forrude, der kan holdes ren."},"v1-26a2faa3c3338010":{"src":"assets/voice/jeppe-neural-v1/v1-26a2faa3c3338010.mp3","text":"Du kører på en bred bygade ved et busstoppested, hvor en bus skjuler fortovet og flere passagerer er steget af."},"v1-27148954866aa31f":{"src":"assets/voice/jeppe-neural-v1/v1-27148954866aa31f.mp3","text":"Punkt 1.1.1.3 samler netop gearvælger og gearplaceringer, parkeringsbremsens betjening og rat."},"v1-2702a8a6310905e0":{"src":"assets/voice/jeppe-neural-v1/v1-2702a8a6310905e0.mp3","text":"Alkohol og stoffer. Alkohol forringer blandt andet dømmekraft, opmærksomhed og reaktion. Ulovlige stoffer og visse lægemidler kan gøre føreren ude af stand til at køre sikkert. Planlæg hjemtransport før festen; vurderingsevnen er et dårligt måleinstrument efter alkohol."},"v1-2712af5cf7c5bdfa":{"src":"assets/voice/jeppe-neural-v1/v1-2712af5cf7c5bdfa.mp3","text":"Bakning kræver lav fart og gentagen orientering, fordi bilens bevægelse og skjulte områder ændrer sig under hele manøvren. Bagenden bestemmer pladsbehovet. Når du bakker og drejer, flytter bilens bagende sig mod den valgte side, mens fronten kan svinge ud modsat. Kontrollér derfor både området bag bilen og pladsen ved forhjørnerne; ét spejl kan ikke dække hele bevægelsen. Orienteringen skal gentages. En fri rute ved manøvrens begyndelse er ikke en garanti for resten. Gående, cyklister eller køretøjer kan komme ind bag bilen. Bak så langsomt, at du kan standse straks, når udsynet ændres eller bliver utilstrækkeligt. Kameraet er kun ét udsnit. Et bakkamera kan vise lave genstande bag bilen, men billedet kan forvrænge afstand og udelade siderne. Kombinér kamera, spejle og direkte orientering, og stands ved tvivl i stedet for at udfylde et uset område med en antagelse."},"v1-29862251e61d7393":{"src":"assets/voice/jeppe-neural-v1/v1-29862251e61d7393.mp3","text":"En ABS-lampe, der ikke slukker kort efter igangsætning, er tegn på fejl; Plan B afgrænser kørslen til nærmeste værksted."},"v1-28463711e5b6bad4":{"src":"assets/voice/jeppe-neural-v1/v1-28463711e5b6bad4.mp3","text":"Hvorfor er et tændt kontrolsymbol for blinklys ikke i sig selv en fuld funktionskontrol?"},"v1-28fb713ffd8274bb":{"src":"assets/voice/jeppe-neural-v1/v1-28fb713ffd8274bb.mp3","text":"Slip speederen, øg afstanden og vær klar til at standse. Din ret ændrer ikke pligten til at forebygge fare, når fejlen er synlig, og den lave fart giver dig tid til at undgå sammenstødet."},"v1-28c5d1171db7ae83":{"src":"assets/voice/jeppe-neural-v1/v1-28c5d1171db7ae83.mp3","text":"Cykler og små køretøjer kræver gentagen observation, fordi de let skjules og hurtigt kan nå et konfliktpunkt. Vurder ankomst, ikke kun afstand. En cyklist kan se langt væk ud, men nå krydset, mens du gennemfører et sving. Følg udviklingen og sammenlign jeres forventede ankomst til samme punkt. Et enkelt afstandsblik er ikke nok. Små trafikanter forsvinder bag små ting. En stolpe, parkeret bil eller spejlramme kan dække en cyklist eller knallert i flere sekunder. Bevæg hovedet, skift synsvinkel og søg igen fra førerpladsen, især før du krydser en cykelsti eller et fortov. Gentag kontrollen efter standsning. Mens du holder for andre, fortsætter cyklister og små køretøjer med at flytte sig. Orientér dig derfor igen umiddelbart før igangsætning eller sving, selv om området var frit, da bilen standsede."},"v1-2a6f88ddcfb34eaf":{"src":"assets/voice/jeppe-neural-v1/v1-2a6f88ddcfb34eaf.mp3","text":"Det kan være slør i styreforbindelserne; ved væsentligt ratslør skal styreapparatet efterses."},"v1-2b9979f757cc66e5":{"src":"assets/voice/jeppe-neural-v1/v1-2b9979f757cc66e5.mp3","text":"Find et andet sted mindst fem meter før feltet eller efter det, hvis øvrige regler tillader det. Det er standsning, og standsningsforbuddet gælder uanset varigheden."},"v1-2c269970e4a85fb8":{"src":"assets/voice/jeppe-neural-v1/v1-2c269970e4a85fb8.mp3","text":"Blink, horn og lys. Tegngivning skal gives tydeligt og i god tid, når andre har gavn af den. Blinklys giver information; det giver ikke i sig selv ret til at køre først. Horn og lyssignal bruges som nødvendig advarsel, ikke som følelsesmæssig anmeldelse."},"v1-2cf78e00f981cbb9":{"src":"assets/voice/jeppe-neural-v1/v1-2cf78e00f981cbb9.mp3","text":"Ved uheld kommer menneskers sikkerhed før trafikafvikling og materielle skader. Stands og skab overblik. En trafikant, der bliver indblandet i et færdselsuheld, skal standse. Vurder først fare fra trafik, brand og ustabile køretøjer. Sikr stedet så langt det kan ske uden at udsætte dig selv eller andre for yderligere risiko. Hjælp og oplysninger. Hjælp personer, der kan være kommet til skade, og tilkald den nødvendige hjælp. De involverede skal kunne udveksle relevante identitets- og køretøjsoplysninger. Forlad ikke stedet, før dine pligter er håndteret forsvarligt. Havari er en ny risiko. Ved motorstop eller havari skal bilen så vidt muligt væk fra den kørende trafik. Advar andre, søg et sikkert opholdssted og vurder, om professionel hjælp er nødvendig. Reparation tæt ved hurtig trafik kan være farligere end selve fejlen."},"v1-2d04844291f8964c":{"src":"assets/voice/jeppe-neural-v1/v1-2d04844291f8964c.mp3","text":"Bevar kontrollen, orientér dig i den virkelige trafik og tilpas kørslen efter det, du kan se og sikkert vurdere."},"v1-2d8295342380a875":{"src":"assets/voice/jeppe-neural-v1/v1-2d8295342380a875.mp3","text":"Kryds uden tydelig regulering skal øves med kørelærer, fordi vejens udformning skal aflæses i bevægelse."},"v1-2db9caa4473fb3a9":{"src":"assets/voice/jeppe-neural-v1/v1-2db9caa4473fb3a9.mp3","text":"Slip speederen tidligt og brems jævnt frem mod en kontrolleret standsning. Du undgår unødig energiomsætning og bevarer overblik uden at ofre sikkerhed; hvis signalet skifter, vurderer du stadig situationen frem for at accelerere automatisk."},"v1-2d37b1904355024f":{"src":"assets/voice/jeppe-neural-v1/v1-2d37b1904355024f.mp3","text":"I rundkørsler flytter risikoen sig fra indkørslen til siden og udkørslen. Frem mod feltet. Nærm dig et fodgængerfelt med en fart, der gør det muligt at standse. Se efter personer, som er på vej ud i feltet, ikke kun dem der allerede går der. Bagfrakommende trafik ændrer ikke dette ansvar. Ind i rundkørslen. Læs vognbaner, signaler og vigepligt før indkørslen. Bedøm især cyklister og knallerter fra venstre, som let undervurderes. Lavere fart giver tid til at kontrollere både rundkørslen og eventuelle krydsende stier. Udkørslen. Giv tegn til højre før udkørslen, men brug ikke blinket som erstatning for orientering. Kontroller bagud til højre og frem mod gående, cyklister og knallerter, der krydser udkørslen. Hold tilbage, hvis din vej skærer deres."},"v1-2e61f7447be56e2c":{"src":"assets/voice/jeppe-neural-v1/v1-2e61f7447be56e2c.mp3","text":"Føreren svarer for både lovlig og sikker stand; ejeren svarer kun for bilens registreringsoplysninger."},"v1-2fafcd6f5f92734f":{"src":"assets/voice/jeppe-neural-v1/v1-2fafcd6f5f92734f.mp3","text":"Lånt bil. Du har stadig et føreransvar. Gruppechatten tager ikke din køretime."},"v1-2ee7debf5ce7846d":{"src":"assets/voice/jeppe-neural-v1/v1-2ee7debf5ce7846d.mp3","text":"Dækkene har lovlig mønsterdybde, men ét er skævt slidt, og bilen er usædvanligt sidevindsfølsom. Hvilken vurdering følger Plan B?"},"v1-2f1c598b507d2e59":{"src":"assets/voice/jeppe-neural-v1/v1-2f1c598b507d2e59.mp3","text":"Lys og dæk forbinder førerens hensigt med vejgreb, synlighed og mulighed for at blive forstået af andre. Lys skal både ses og vise. Lygter hjælper dig med at se, men gør også bilen læsbar for andre. Kontrollér derfor funktion, renhed og synlige skader. En lygte, der lyser, kan stadig være utilstrækkelig, hvis den er dækket eller beskadiget. Mønsteret leder vand væk. Dækmønster og dækkenes tilstand har betydning for kontakten med våd vej. Den lovlige mindste mønsterdybde er 1,6 mm, men føreren skal også reagere på skader, forkert tryk og forhold, der svækker vejgrebet. Blinkrytmen kan afsløre en fejl. En usædvanligt hurtig blinkrytme kan pege på, at en blinklygte ikke virker som forventet. Gå rundt om bilen og kontrollér alle relevante lygter i stedet for at antage, at lampen i instrumenthuset beviser funktionen udenfor."},"v1-2fcd886e958b0e0a":{"src":"assets/voice/jeppe-neural-v1/v1-2fcd886e958b0e0a.mp3","text":"Hvorfor kan man ikke bruge lugtesansen til at afgøre, om der er kulilte i bilen?"},"v1-301df17eff181d05":{"src":"assets/voice/jeppe-neural-v1/v1-301df17eff181d05.mp3","text":"Hold retningen langs kanten, brems forsigtigt og styr først tilbage ved lav fart efter instruktion. Et brat ratudslag kan udløse tab af kontrol på tværs af banen."},"v1-2aa2956b372bde83":{"src":"assets/voice/jeppe-neural-v1/v1-2aa2956b372bde83.mp3","text":"Afstand og møde. Afstanden til forankørende skal give tid og plads til at reagere, hvis den bremser. Afstanden skal øges, når vejgreb, udsyn eller opmærksomhed er dårligere. Ved møde på smal vej skal hastigheden sænkes, og den med hindringen på sin side må ofte vente."},"v1-2aaef09823dc0243":{"src":"assets/voice/jeppe-neural-v1/v1-2aaef09823dc0243.mp3","text":"En sikker afslutning på turen fortsætter, til døren er åbnet uden at skabe fare for forbipasserende. Dørzonen er en trafikzone. En cyklist kan være tættere på og hurtigere fremme, end spejlbilledet antyder. Kontrollér spejl og direkte bagud, før døren løsnes, og åbn først en smal sprække, så ny trafik stadig kan opdages. Passagerer skal inddrages. Føreren kan se forhold, som en passager overser, og bør sikre, at alle åbner mod et frit område. Giv en tydelig besked, især ved cykelsti eller kørebane, og vent med oplåsning, hvis nogen ellers åbner straks. Sikr bilen før opmærksomheden flyttes. Når bilen er standset, skal den sikres mod at bevæge sig, før føreren samler ting eller hjælper passagerer. En korrekt afslutningsrækkefølge frigør opmærksomhed til den sidste orientering og til at åbne døren sikkert i trafikken."},"v1-30c0962700aeb3c8":{"src":"assets/voice/jeppe-neural-v1/v1-30c0962700aeb3c8.mp3","text":"Bliv bag cyklisten og fuldfør først svinget, når stien er fri. Den ligeudkørende cyklist må ikke tvinges til at bremse af dit sving."},"v1-30f896d33ac60309":{"src":"assets/voice/jeppe-neural-v1/v1-30f896d33ac60309.mp3","text":"Hvorfor kan håndfri betjening stadig være distraherende?"},"v1-304e4e756e468a9c":{"src":"assets/voice/jeppe-neural-v1/v1-304e4e756e468a9c.mp3","text":"Førerens ansvar gælder ikke først efter en opdaget fejl; føreren skal hele tiden være opmærksom på bilens sikkerhedsmæssige stand."},"v1-30b1a93330964465":{"src":"assets/voice/jeppe-neural-v1/v1-30b1a93330964465.mp3","text":"Tunnel og jernbaneoverkørsel kræver tidlig observation, fri udvej og respekt for særlige signaler og begrænset plads. Lys og afstand ændres ved tunnelmundingen. Overgangen mellem dagslys og tunnel kan midlertidigt reducere detaljesynet. Sikr før indkørslen, at nærlyset og dermed baglyset er tændt, øg opmærksomheden og hold længere afstand, så en langsommere kø ikke først opdages inde i det mørkere rum. Tunnelen begrænser flugtveje. Standsning, vending og bakning i en tunnel kan skabe særlig fare, fordi plads, udsyn og adgang for hjælp er begrænset. Følg signaler og anvisninger, og hold den afstand, der giver mulighed for kontrolleret standsning. Kør kun over sporet med fri udgang. Ved jernbaneoverkørsel skal du udvise særlig forsigtighed og sikre, at passagen kan gennemføres uden unødigt ophold. Kør ikke ind, hvis køen foran kan efterlade bilen på sporet, selv om bommen er oppe."},"v1-32079fec4df90f6d":{"src":"assets/voice/jeppe-neural-v1/v1-32079fec4df90f6d.mp3","text":"Hvilke tre hovedtyper af karrosserikrav skal du kende?"},"v1-31a9a1d085cc8a33":{"src":"assets/voice/jeppe-neural-v1/v1-31a9a1d085cc8a33.mp3","text":"Bilens skærm viser en højere tilladt hastighed end et tydeligt midlertidigt skilt ved et vejarbejde."},"v1-316fcfa166f61596":{"src":"assets/voice/jeppe-neural-v1/v1-316fcfa166f61596.mp3","text":"Bliv holdende, orientér dig igen, og sæt først i gang, når cyklisten er passeret og der er et sikkert hul. Cyklisten kan ligge uden for spejlets dækkede område, og dit blinklys giver ikke ret til at skære ind i cyklistens bane."},"v1-328bc24822154ea9":{"src":"assets/voice/jeppe-neural-v1/v1-328bc24822154ea9.mp3","text":"Lygter og reflekser. Sammen med kørelæreren i undervisningsbilen: 1) kontrollér at alle lygter og reflekser er hele og rene, 2) sammenlign stoplys med baglys og se at stoplyset er væsentligt kraftigere, 3) kontrollér gult blinklys, som ses tydeligt i sollys, 4) tænd havariblink og se at alle blinklygter tænder samtidig, og 5) kontrollér at nummerpladelyset belyser den bageste nummerplade med hvidt lys. Hornet. På et egnet sted og efter kørelærerens anvisning: giv et kort signal og vurder, om tonen er klar og konstant. Undgå unødig brug; kontrollen skal udføres på bilen."},"v1-33a01b7064410fa1":{"src":"assets/voice/jeppe-neural-v1/v1-33a01b7064410fa1.mp3","text":"Hvorfor kan ét stop ved B 13 være utilstrækkeligt?"},"v1-33e72bd762859b60":{"src":"assets/voice/jeppe-neural-v1/v1-33e72bd762859b60.mp3","text":"Afslutningsrækkefølge og direkte orientering bør indøves i den konkrete undervisningsbil."},"v1-33effdede64fa438":{"src":"assets/voice/jeppe-neural-v1/v1-33effdede64fa438.mp3","text":"Valg af fart, placering og gear gennem kurver og bakker skal øves på vej med kørelærer."},"v1-32ba307f01df9f36":{"src":"assets/voice/jeppe-neural-v1/v1-32ba307f01df9f36.mp3","text":"Opfattelse og reaktion. Reaktionstid begynder, når en fare kan opfattes, og slutter, når føreren begynder at reagere. En sikker og rigtig reaktion er vigtigere end en hurtig, men forkert reaktion. Højere fart betyder længere strækning, før en reaktion overhovedet får virkning."},"v1-352b0c552c9afe69":{"src":"assets/voice/jeppe-neural-v1/v1-352b0c552c9afe69.mp3","text":"Fremkørsel og udsyn ved forskellige typer sideveje skal trænes med kørelæreren på vej."},"v1-3598b549c7c58130":{"src":"assets/voice/jeppe-neural-v1/v1-3598b549c7c58130.mp3","text":"Vejens omgivelser giver spor om, hvem der kan dukke op, og hvilken fejlmargin situationen kræver. Miljøet ændrer forventningen. Skole, butikker, boliger, busstoppested eller parkerede biler peger på forskellige bevægelser. Brug omgivelserne til at lede efter relevante trafikanter og mulige skjul, før nogen træder ud, kører ud eller på anden måde bevæger sig ind i din bane. Parkerede biler skaber flere risici. En parkeret bil kan skjule gående, begynde at køre eller åbne en dør. Skab sideafstand, se efter personer, lys og hjulretning, og tilpas farten, så du kan reagere på en begyndende bevægelse. Vejens udformning er ikke hele reglen. Bred belægning kan føles som invitation til høj fart, selv hvor sideveje og mennesker gør situationen kompleks. Lad risiko, udsyn og gældende regulering styre farten frem for vejens visuelle rummelighed alene."},"v1-34a08f175155a27a":{"src":"assets/voice/jeppe-neural-v1/v1-34a08f175155a27a.mp3","text":"Afmærkning fortæller både, hvad du skal gøre, og hvor tidligt du skal begynde at gøre det. B 11 og B 13. B 11 og hajtænder betyder ubetinget vigepligt, men ikke automatisk fuldt stop. B 13 STOP kræver derimod fuld standsning ved stoplinjen; bagefter består den ubetingede vigepligt, så udsyn og trafik skal vurderes på ny. Påbud og hastighed. En påbudstavle viser en handling eller retning, som skal følges. En hastighedstavle angiver den højst tilladte fart, men giver aldrig krav på at køre så hurtigt. Udsyn, føre og trafik kan kræve væsentligt lavere hastighed. Gul afmærkning. Midlertidig gul vejafmærkning bruges blandt andet ved vejarbejde og går foran modstridende hvid afmærkning. Følg den gule linjeføring tidligt, sænk farten og forvent smallere baner, flyttede svingpunkter og arbejdere tæt på kørearealet."},"v1-34f5518c6fbb8d83":{"src":"assets/voice/jeppe-neural-v1/v1-34f5518c6fbb8d83.mp3","text":"Dæk og hjul skal passe sammen, være korrekt monteret og afsløre fejl gennem slid, lyd og styreadfærd. Hjulene skal passe sammen. Dæk, fælge og hjullejer skal være ubeskadigede. På samme aksel skal dækkene have samme dimension og type, bortset fra et nødhjul til midlertidig brug. Dæktrykket skal følge fabrikantens forskrift, og åbenbart uegnede dæk må ikke anvendes. Læs dækkets type. Almindelige dæk er beregnet til højere temperaturer end vinterdæk. M+S sammen med bjerg- og snefnugsymbol viser et vinterdæk; M+S alene kan være et helårsdæk. Symbolet skal læses, ikke gættes ud fra mønsterets dramatiske udseende. Pigdæk og tunge biler. Pigdæk må bruges fra 1. november til 15. april og skal sidde på alle hjul, også på en eventuel tilkoblet påhængsvogn. El- og hybridbiler har ofte større dækslid på grund af højere vægt og regenerationsfunktion. Tre konkrete kontroller. Hovedmønstret skal være mindst 1,6 millimeter på alle hjul og kan vurderes ved slidindikatorer. Dæk og fælge skal være uden skader. Et retningsbestemt dæk skal vende i korrekt omløbsretning efter markeringen på siden. Slid peger videre. Ujævnt eller skævt slid kan skyldes forkert dæktryk, hjul, hjulindstilling, bremser eller støddæmpere. Over- eller understyring og større sidevindsfølsomhed kan også pege på dæktrykket. Årsagen skal straks findes og afhjælpes. Lyt til ophænget. Knirk under kørsel kan komme fra hjulophæng, fjedre eller støddæmpere. Unormal støj eller vibration fra hjulleje eller ophæng kan også være tegn på fejl. Lyden er et signal om undersøgelse, ikke et soundtrack bilen selv har valgt."},"v1-35c18f6c798280ef":{"src":"assets/voice/jeppe-neural-v1/v1-35c18f6c798280ef.mp3","text":"Du har markeret fire spørgsmål og har tre minutter tilbage efter sidste scenarie."},"v1-35fbed02276cb011":{"src":"assets/voice/jeppe-neural-v1/v1-35fbed02276cb011.mp3","text":"En sikker tilbagevenden eller afbrydelse, hvis udsyn, modkørende eller en ny hindring ændrer situationen."},"v1-3606a30663a2045b":{"src":"assets/voice/jeppe-neural-v1/v1-3606a30663a2045b.mp3","text":"Fortsæt efter skiltning uden at række efter telefonen, og find senere et lovligt sted at standse og ændre ruten. Krydset kræver observation og valg; en håndholdt opgave fjerner blik og tanke netop dér, hvor situationen udvikler sig hurtigt."},"v1-36102b6fa70f05ca":{"src":"assets/voice/jeppe-neural-v1/v1-36102b6fa70f05ca.mp3","text":"Vælg gearidé til situationen. Sorter fem tænkte situationer i behov for lavt gear, højt gear eller bakgear: igangsætning, stejl nedkørsel, rolig kørsel ved højere fart, langsom fremdrift og baglæns placering. Forklar valget ud fra trækkraft og bevægelsesretning."},"v1-39ce9fc2596b45b3":{"src":"assets/voice/jeppe-neural-v1/v1-39ce9fc2596b45b3.mp3","text":"Hvad er den centrale forskel i ansvar?"},"v1-397fe8660829004c":{"src":"assets/voice/jeppe-neural-v1/v1-397fe8660829004c.mp3","text":"Førerretten og registreringen fjerner ikke køretøjstypens særlige regler om indretning, udstyr og eventuelt førerudstyr."},"v1-36c6d4691f99cd96":{"src":"assets/voice/jeppe-neural-v1/v1-36c6d4691f99cd96.mp3","text":"Førerassistenter. Førerassistenter kan advare eller gribe ind, men føreren har fortsat ansvaret for kørslen. Kameraer og sensorer kan fejle eller give misvisende oplysninger. Adaptiv fartpilot fjerner ikke behovet for at holde øje med vej, afstand og hastighed."},"v1-368c961f4c447aa5":{"src":"assets/voice/jeppe-neural-v1/v1-368c961f4c447aa5.mp3","text":"Føreren skal afstå fra kørsel, når træthed, sygdom eller påvirkende midler gør fuldt betryggende kørsel usikker. Selvvurderingen skal ske før afgang. Gentagne koncentrationssvigt, oversete tegn eller vanskelighed ved at holde opmærksomheden er relevante advarsler, ikke noget der skal afprøves i trafik. Vurder køreevnen ærligt før turen og på ny, hvis tilstanden ændrer sig. Medicin kan ændre køreevnen. Et lægemiddel kan påvirke opmærksomhed, reaktion eller dømmekraft, og virkningen kan variere. Følg præparatets advarsler og den faglige information, du har fået; kør ikke, hvis du ikke kan føre bilen på fuldt betryggende måde. En pause er en beslutning, ikke et bevis. At standse kan give mulighed for at revurdere tilstanden, men en kort pause garanterer ikke, at køreevnen er genoprettet. Fortsæt kun, hvis du reelt kan køre fuldt betryggende; ellers skal turen ikke fortsætte."},"v1-39f0356cd6e2e64e":{"src":"assets/voice/jeppe-neural-v1/v1-39f0356cd6e2e64e.mp3","text":"Hvilken beskrivelse gengiver Plan B's energirigtige teknik for en relevant manuelt gearet forbrændingsbil præcist?"},"v1-3c6374a12e4d4827":{"src":"assets/voice/jeppe-neural-v1/v1-3c6374a12e4d4827.mp3","text":"Trafiksanerede områder. I opholds- og legeområder kan gående og legende børn færdes på hele vejarealet, og motorkørsel sker på deres betingelser. Hastigheden skal normalt være under 15 km/t; føreren holder tilbage og fortsætter først, når de gående har set bilen og givet plads, og ingen kan komme farligt nær den. Parkering i opholds- og legeområde må kun ske på særligt afmærkede pladser. I gågade kræves særlig hensyn til gående; i cykelgade skal motorkørende vise særlig agtpågivenhed og må ikke unødigt hindre andre kørende. Bump, forsætninger og andre fartdæmpere kan kræve lavere fart end områdets angivne maksimum."},"v1-3b39eb46ff9b9a62":{"src":"assets/voice/jeppe-neural-v1/v1-3b39eb46ff9b9a62.mp3","text":"Du skal kende navnet på udstyret og kunne finde det i netop den bil, du undervises i. Kontakterne omkring dig. Ratlås, tænding, elektrisk starter, lys, horn, visker, vasker, ventilation, el-bagrude og spejlindstilling kan være samlet eller placeret forskelligt. Du skal også finde anordninger til fronthjelm, motorhjelm og lågen til bilens drivmiddel. Hjelmbetegnelserne kan dække samme klap eller forskellige klapper i den konkrete bil. Fødder, hænder og parkering. Pedalerne ligger i fast rækkefølge, men koblingspedalen findes kun i relevante biler. Gearvælgeren kan være mellem sæderne, ved rattet eller på instrumentbordet. Parkeringsbremsen kan være et håndtag, en pedal eller en kontakt. Rattet skal også kunne udpeges uden tøven. Sele og væskesteder. Selen består ikke kun af spændet: du skal også kunne vise dens fastgørelsespunkter. Under hjelmen skal du kende dækslet til sprinklervæske og de øvrige relevante beholdere i bilen. Nogle elbiler har ikke motorolie eller hydraulisk servostyringsolie, så undervisningsbilen afgør listen."},"v1-3c01e6836cb6d4af":{"src":"assets/voice/jeppe-neural-v1/v1-3c01e6836cb6d4af.mp3","text":"Attesten dokumenterer registrering og centrale vægte og bruges ved vurdering af bil og påhængskøretøj. Registrering og dokument. En bil, der bruges på færdselslovens område, skal være registreret og have en registreringsattest. Ved kørsel i mange andre lande skal originalen medbringes. Inden en tur over grænsen må du derfor undersøge dokumentkravet for de lande, rejsen går gennem. Vægtene står på attesten. Registreringsattesten oplyser bilens egenvægt eller køreklar vægt og dens tilladte totalvægt. Den kan også vise, hvor tungt et påhængskøretøj bilen må kobles med, samt en eventuel største tilladt vogntogsvægt. Felterne bruges samlet, ikke som løse gæt. To køretøjer, to attester. Bilens og påhængskøretøjets registreringsattester bruges til at vurdere, om de må sammenkobles. Under kørsel med påhængskøretøj skal begge attester med. I udlandet kræves originalerne eller en genpart udstedt af Motorstyrelsen, mens kopier kan medbringes i Danmark. Elbilens vægt påvirker lasten. Elkøretøjer har ofte højere egenvægt og derfor lavere lasteevne. Det er ikke en regel om, at enhver elbil kan laste mindre end enhver anden bil; den konkrete registreringsattest viser de relevante vægte for netop køretøjet."},"v1-3d1fc32d61a167f7":{"src":"assets/voice/jeppe-neural-v1/v1-3d1fc32d61a167f7.mp3","text":"Du vil svinge til højre. En cyklist ligger skjult ved bilens højre baghjørne, mens cykelstien fortsætter ligeud."},"v1-3cddda902aba2ef4":{"src":"assets/voice/jeppe-neural-v1/v1-3cddda902aba2ef4.mp3","text":"Både en forbrændingsbil og en elbil har et batteri, men batteriets rolle er ikke den samme. Hvilken forklaring stemmer med Plan B?"},"v1-3f2ae40f409450fb":{"src":"assets/voice/jeppe-neural-v1/v1-3f2ae40f409450fb.mp3","text":"Planen beskriver batteristrøm til forbrændingsmotorens startmotor og batteristrøm til elbilens drivende elmotor."},"v1-3edf021bffc4ed44":{"src":"assets/voice/jeppe-neural-v1/v1-3edf021bffc4ed44.mp3","text":"Fordi signalet gælder bestemte køretøjer; du skal følge signalet og afmærkningen for din egen kørselsretning."},"v1-3fcf849f210ff238":{"src":"assets/voice/jeppe-neural-v1/v1-3fcf849f210ff238.mp3","text":"Placering ved udrykning skal trænes og drøftes med kørelæreren i virkelige, lovlige trafiksituationer."},"v1-3f2e727dd5837327":{"src":"assets/voice/jeppe-neural-v1/v1-3f2e727dd5837327.mp3","text":"Lyset i et kryds er mørkt. Du ser B 11 og hajtænder foran din bane, mens en bil nærmer sig på den tværgående vej."},"v1-3fa08060d89a7ff9":{"src":"assets/voice/jeppe-neural-v1/v1-3fa08060d89a7ff9.mp3","text":"Planen fraråder længere tomgang, anbefaler højt gear og siger, at udkobling så vidt muligt bør undgås ved fartreduktion."},"v1-3f7409709b1023a2":{"src":"assets/voice/jeppe-neural-v1/v1-3f7409709b1023a2.mp3","text":"I forbrændingsbilen antænder batteriet brændstoffet direkte; i elbilen drejer batteriet en startmotor ved igangsætning."},"v1-404c2c721d575691":{"src":"assets/voice/jeppe-neural-v1/v1-404c2c721d575691.mp3","text":"Advarselslampen har skrevet i gruppechatten. Læs beskeden."},"v1-3fdbdfec40a3aa3e":{"src":"assets/voice/jeppe-neural-v1/v1-3fdbdfec40a3aa3e.mp3","text":"Den kan have brug for et bredere indledende forløb, fordi køretøjet er langt og baghjulene skærer tættere gennem svinget."},"v1-407f51c9194529a5":{"src":"assets/voice/jeppe-neural-v1/v1-407f51c9194529a5.mp3","text":"Bliv før sporet, og kør først frem, når der er fri plads til at passere hele overkørslen uden ophold. Et åbent signal fjerner ikke risikoen ved at blive fanget på sporet; fri udgang skal være sikret før indkørsel."},"v1-40575f3f20152c1d":{"src":"assets/voice/jeppe-neural-v1/v1-40575f3f20152c1d.mp3","text":"Digital prøveadfærd. Den digitale teoriprøve afholdes på et prøvested og kræver fysisk fremmøde. Kandidaten kan gå tilbage, ændre svar og markere spørgsmål til senere. I NATKØRSEL tæller et scenarie som én app-fejl, hvis et eller flere valg er forkerte eller mangler; dette må ikke kaldes dokumenteret identisk med myndighedens optælling."},"v1-43b74a6a57235ce1":{"src":"assets/voice/jeppe-neural-v1/v1-43b74a6a57235ce1.mp3","text":"For at føre motorens roterende bevægelse blødt videre gennem gearkassen til hjulene."},"v1-439a57639c488043":{"src":"assets/voice/jeppe-neural-v1/v1-439a57639c488043.mp3","text":"Fordi den udvendige lygte stadig kan være defekt eller skjult; den faktiske funktion skal kontrolleres på bilen."},"v1-413c8aa2de464c24":{"src":"assets/voice/jeppe-neural-v1/v1-413c8aa2de464c24.mp3","text":"Fordi stoplinjen opfylder stopkravet, men udsynet kan kræve en ny standsning for at overholde den fortsatte vigepligt."},"v1-43c8e23298cd2194":{"src":"assets/voice/jeppe-neural-v1/v1-43c8e23298cd2194.mp3","text":"Træthed, sygdom og medicin. Træthed kan give langsommere reaktion og korte perioder uden reel opmærksomhed. Sygdom og medicin kan gøre kørsel uforsvarlig, også selv om medicinen er lovligt udleveret. Kaffe eller et åbent vindue gør ikke en udmattet fører køreklar."},"v1-4435fa28a91c61eb":{"src":"assets/voice/jeppe-neural-v1/v1-4435fa28a91c61eb.mp3","text":"Hvorfor er følelsen af at være upåvirket et usikkert beslutningsgrundlag?"},"v1-44688a4c5b3c2a7a":{"src":"assets/voice/jeppe-neural-v1/v1-44688a4c5b3c2a7a.mp3","text":"At skabe en tydelig, sikker vej for udrykningen uden at bringe andre eller dig selv i ny fare."},"v1-443798bf2fecf0a8":{"src":"assets/voice/jeppe-neural-v1/v1-443798bf2fecf0a8.mp3","text":"Uheld og havari. Ved færdselsuheld skal man standse og hjælpe personer, der kan være kommet til skade. Stedet skal sikres uden at udsætte hjælperen eller andre for ny fare. Ved havari skal bilen så vidt muligt væk fra kørebanen og andre trafikanter advares."},"v1-4412fd46da808711":{"src":"assets/voice/jeppe-neural-v1/v1-4412fd46da808711.mp3","text":"Lavt gear ved igangsætning og stejle bakker, højt gear ved høj fart og bakgear baglæns."},"v1-468ce0643afca1fe":{"src":"assets/voice/jeppe-neural-v1/v1-468ce0643afca1fe.mp3","text":"Hvem har ansvaret, når en lovlig bil udvikler en sikkerhedsrelevant fejl under kørslen?"},"v1-463b1da19487cf2d":{"src":"assets/voice/jeppe-neural-v1/v1-463b1da19487cf2d.mp3","text":"Du skal kunne forbinde symbolet med dets betydning og vide, hvilken reaktion der er nødvendig i den konkrete bil."},"v1-459df829d2dc6d62":{"src":"assets/voice/jeppe-neural-v1/v1-459df829d2dc6d62.mp3","text":"Lovlig mønsterdybde betyder, at skævslid og sidevindsfølsomhed kan afvente det næste almindelige serviceeftersyn."},"v1-463d951e059399aa":{"src":"assets/voice/jeppe-neural-v1/v1-463d951e059399aa.mp3","text":"Vognbaneskift og sammenfletning. Ved vognbaneskift har den skiftende fører ansvaret for, at manøvren kan ske uden fare eller unødig ulempe. Spejle, skulderblik og tydeligt tegn bruges før et vognbaneskift. Ved sammenfletning skal trafikanterne tilpasse sig gensidigt til den fælles bane."},"v1-472101f998a7077b":{"src":"assets/voice/jeppe-neural-v1/v1-472101f998a7077b.mp3","text":"Planen kræver tilstrækkelig sprinklervæske og fungerende viskere og beskriver, at indvendig film kan gøre udsynet umuligt i modlys."},"v1-48a46d9c85376eba":{"src":"assets/voice/jeppe-neural-v1/v1-48a46d9c85376eba.mp3","text":"Fuld nedtrædning afbryder forbindelsen til gearkassen, og langsom opløftning overfører bevægelsen blødt efter skiftet."},"v1-4871d1ae24503cb0":{"src":"assets/voice/jeppe-neural-v1/v1-4871d1ae24503cb0.mp3","text":"Egenvægt eller køreklar vægt, tilladt totalvægt, tilladt vægt for et eventuelt påhængskøretøj og eventuel største vogntogsvægt."},"v1-480296de7eeade19":{"src":"assets/voice/jeppe-neural-v1/v1-480296de7eeade19.mp3","text":"Seler, ruder, viskere og spejle skal give beskyttelse og udsyn i den konkrete bil. Sele og nakkestøtte. Bilen skal normalt have sikkerhedssele på alle siddepladser, og selerne skal være uden skader. Påbudte nakkestøtter må ikke fjernes, når pladsen bruges. Beskyttelsen begynder altså før kørslen med udstyr, der er til stede og intakt. Ruden skal kunne holdes ren. Forruden skal som hovedregel være hel og uden skader. Visker og vasker skal kunne holde den ren. Hvis det ikke lykkes, er det tegn på fejl i et af systemerne, også selv om udsynet virker acceptabelt i tørvejr. Spejle eller kamera. Bilen skal have et indvendigt førerspejl og et udvendigt førerspejl på hver side. Spejlene skal være rene og ubeskadigede. De kan erstattes af en kamera- og monitorløsning. Find derfor først ud af, hvilken løsning den konkrete bil er udstyret med. Trekanten skal være ved hånden. En godkendt advarselstrekant bør medbringes, så den kan opstilles i de situationer, hvor der er pligt til det. Den hjælper ikke meget hjemme i garagen, når bilen står havareret et andet sted. Udsynets skjulte film. Sprinklervæske skal være tilstrækkelig, viskerne skal rense ruden, og spejlene skal være hele, rene og korrekt indstillede. En tynd indvendig film kan være næsten usynlig i gråvejr, men gøre udsynet meget dårligt ved lav sol eller blændende lygter."},"v1-494f8c8ce0616702":{"src":"assets/voice/jeppe-neural-v1/v1-494f8c8ce0616702.mp3","text":"Når udsyn, siddestilling eller bil ikke svarer til forudsætningen, så referencepunktet ikke længere kan bekræftes."},"v1-49a2b27163ab5172":{"src":"assets/voice/jeppe-neural-v1/v1-49a2b27163ab5172.mp3","text":"Lysstyrken kontrolleres ved tydelig synlighed i sollys, mens den hurtige rytme knyttes til manglende funktion i en blinklygte."},"v1-48fd79d004f92204":{"src":"assets/voice/jeppe-neural-v1/v1-48fd79d004f92204.mp3","text":"Fælles mål, kombination af tidligere færdigheder og efterfølgende refleksion over elevens konkrete valg."},"v1-48b40c1d7576e0d8":{"src":"assets/voice/jeppe-neural-v1/v1-48b40c1d7576e0d8.mp3","text":"Fordi pedaladfærd, retningsstabilitet og advarsler kan afsløre fejl, som bliver kritiske ved en kraftigere eller gentagen bremsning."},"v1-4ad8ba8cb8acb9e9":{"src":"assets/voice/jeppe-neural-v1/v1-4ad8ba8cb8acb9e9.mp3","text":"Du holder langs en cykelsti, og passageren rækker straks efter dørhåndtaget, mens en cyklist nærmer sig bagfra."},"v1-4bacedcc1359a85e":{"src":"assets/voice/jeppe-neural-v1/v1-4bacedcc1359a85e.mp3","text":"I forbrændingsbilen forsyner batteriet startmotoren; i elbilen forsyner batteriet den motor, der driver bilen."},"v1-4a644bbad3dcecdf":{"src":"assets/voice/jeppe-neural-v1/v1-4a644bbad3dcecdf.mp3","text":"Fordi køretøjstypen kan have egne regler om blandt andet mål, vægt, bremser, lys, dæk, spejle, hjelm og tilkobling."},"v1-4bfdb6c0fdeaa135":{"src":"assets/voice/jeppe-neural-v1/v1-4bfdb6c0fdeaa135.mp3","text":"Motor, miljø og papirer. Olie og kølervæske kontrolleres efter bilens anvisninger; advarsler må ikke bare ignoreres. Unormal røg eller støj kan være tegn på fejl, der kræver kontrol. Registreringsattesten beskriver bilen og er vigtig ved blandt andet ejerskifte og kørsel med påhæng."},"v1-4d38fba0c0797e3a":{"src":"assets/voice/jeppe-neural-v1/v1-4d38fba0c0797e3a.mp3","text":"Hvorfor er et spejlblik alene utilstrækkeligt før døråbning?"},"v1-4d6c7112a1bd2ae0":{"src":"assets/voice/jeppe-neural-v1/v1-4d6c7112a1bd2ae0.mp3","text":"Efter læsning hænger traileren korrekt på bilen, men en tung genstand kan glide frit på ladet ved opbremsning."},"v1-4c00ebbbb6212786":{"src":"assets/voice/jeppe-neural-v1/v1-4c00ebbbb6212786.mp3","text":"Planen peger på flere mulige årsager, blandt andet dæktryk, hjulindstilling, bremser og støddæmpere; dækombytning alene løser ikke årsagen."},"v1-4c611489a527699a":{"src":"assets/voice/jeppe-neural-v1/v1-4c611489a527699a.mp3","text":"En bil har en løs skarp pynteliste, en sikkerhedsfarlig rustskade og en bagageklap, hvis lås ikke holder. Hvilken observation hører specifikt til låsekravet i 1.2.8.3?"},"v1-4e7b450024955797":{"src":"assets/voice/jeppe-neural-v1/v1-4e7b450024955797.mp3","text":"I Danmark kan kopier af begge attester medbringes; i udlandet kræves originaler eller Motorstyrelsens genpart."},"v1-4e666945fbe18305":{"src":"assets/voice/jeppe-neural-v1/v1-4e666945fbe18305.mp3","text":"Alle led følger planens konkrete råd om starttidspunkt, tomgang, acceleration, gearvalg og forudseende farttilpasning ved signalregulerede kryds."},"v1-4da81146d88581b5":{"src":"assets/voice/jeppe-neural-v1/v1-4da81146d88581b5.mp3","text":"Belæsning og påhæng. Last skal placeres og sikres, så den ikke forskyder sig eller falder af. Belæsning ændrer bilens styre-, bremse- og stabilitetsegenskaber. En påhængsvogn ændrer vogntogets længde og kræver mere omtanke ved sving og bakning."},"v1-4ed0d27354416b67":{"src":"assets/voice/jeppe-neural-v1/v1-4ed0d27354416b67.mp3","text":"Udskridning og undvigelse. Tidlig hastighedstilpasning er den vigtigste måde at undgå kritiske manøvrer på. Ved tab af vejgreb skal føreren undgå panikbevægelser og søge at genvinde kontrol. Praktisk træning i udskridning og undvigelse hører til på køreteknisk anlæg."},"v1-4f3e950f8fb2f000":{"src":"assets/voice/jeppe-neural-v1/v1-4f3e950f8fb2f000.mp3","text":"Hvad gør den afsluttende kørsel til mere end en lang køretur?"},"v1-4f6cffa440c3fcf0":{"src":"assets/voice/jeppe-neural-v1/v1-4f6cffa440c3fcf0.mp3","text":"Motor og hjul kan holde pause fra hinanden. Koblingen styrer relationen."},"v1-4fb41f5dd21ad462":{"src":"assets/voice/jeppe-neural-v1/v1-4fb41f5dd21ad462.mp3","text":"Ejeren svarer for begge forhold, indtil føreren under kørslen bliver opmærksom på en konkret fejl."},"v1-4fa980f407f6121a":{"src":"assets/voice/jeppe-neural-v1/v1-4fa980f407f6121a.mp3","text":"Spejl, blindvinkelkontrol, placering og lav svingfart skal samles i fysisk krydstræning med kørelærer."},"v1-50cf5dce88909e5a":{"src":"assets/voice/jeppe-neural-v1/v1-50cf5dce88909e5a.mp3","text":"Hvornår bør du opgive en indlært parkeringsreference og standse?"},"v1-50803c037726b7ba":{"src":"assets/voice/jeppe-neural-v1/v1-50803c037726b7ba.mp3","text":"Din bane fortsætter gennem en punkteret linje ind i nabobanen; den forsvinder ikke som ved sammenfletning."},"v1-5146bc389a06563f":{"src":"assets/voice/jeppe-neural-v1/v1-5146bc389a06563f.mp3","text":"Planen tillader forsigtige nødvendige ture, hvis føreren undgår hårde opbremsninger og holder lav hastighed."},"v1-50a9db893cf0d831":{"src":"assets/voice/jeppe-neural-v1/v1-50a9db893cf0d831.mp3","text":"Telefon og distraktion. Håndholdt teleudstyr må ikke bruges under kørsel. Også håndfri samtaler, skærme, passagerer og stærke følelser kan stjæle opmærksomhed. Hvis noget kræver betjening, er den sikre løsning ofte at holde lovligt ind først."},"v1-5293679b9e7142cf":{"src":"assets/voice/jeppe-neural-v1/v1-5293679b9e7142cf.mp3","text":"Gearvælger med gearenes placering, tændingskontakten og rattet."},"v1-51c161f464a60861":{"src":"assets/voice/jeppe-neural-v1/v1-51c161f464a60861.mp3","text":"Papirerne kender bilens grænser. Din optimisme gør ikke."},"v1-5194cad889ebdd94":{"src":"assets/voice/jeppe-neural-v1/v1-5194cad889ebdd94.mp3","text":"Fortsæt til et sted med tilstrækkeligt udsyn og plads, og gennemfør kun vendingen efter ny orientering før hver bevægelse. Ved bakketoppen kan en trafikant dukke op sent, mens bilen spærrer flere retninger under vendingen."},"v1-55271ec1d7b1bbc6":{"src":"assets/voice/jeppe-neural-v1/v1-55271ec1d7b1bbc6.mp3","text":"Hold tilbage før du krydser fortov og cykelareal. Udkørsel fra et område uden for vejen giver ubetinget vigepligt uden særskilt tavle."},"v1-56a642e0b019c642":{"src":"assets/voice/jeppe-neural-v1/v1-56a642e0b019c642.mp3","text":"For lidt kølervæske kan skade motoren, men planen knytter ikke disse to konkrete symptomer til kølesystemet."},"v1-5573f6e5d1ce8b78":{"src":"assets/voice/jeppe-neural-v1/v1-5573f6e5d1ce8b78.mp3","text":"Fortsæt til næste frakørsel i stedet for at presse et sent baneskift igennem. Ruteomvejen er ufarlig; et brat sideskift ved høj fart er ikke."},"v1-55adb64d25291159":{"src":"assets/voice/jeppe-neural-v1/v1-55adb64d25291159.mp3","text":"Du har grønt, men ingen venstrepil. En varebil modsat venter også på venstresving og skjuler en motorcykel bag sig."},"v1-566fdfd441b1df01":{"src":"assets/voice/jeppe-neural-v1/v1-566fdfd441b1df01.mp3","text":"Systemet kan vise forkert; føreren sænker farten, men fartpiloten overtager ansvaret for tavlefortolkningen."},"v1-57f225b81cc6e3da":{"src":"assets/voice/jeppe-neural-v1/v1-57f225b81cc6e3da.mp3","text":"Bakningens styrevirkning, udsyn og standsninger skal øves fysisk på lukket øvelsesplads og senere i trafik."},"v1-58074f0c4a0916e4":{"src":"assets/voice/jeppe-neural-v1/v1-58074f0c4a0916e4.mp3","text":"Lad bilen stå og brug den transportløsning, der blev planlagt uden egen kørsel. Vennens indtryk og turens længde siger ikke, om opmærksomhed og reaktion er sikre eller lovens krav er opfyldt."},"v1-56fbc67e4bc07b8c":{"src":"assets/voice/jeppe-neural-v1/v1-56fbc67e4bc07b8c.mp3","text":"Tavleassistenten viser en anden hastighed end den tavle, føreren netop har observeret. Hvilket udsagn om systemet og ansvaret følger Plan B?"},"v1-56c851793fd2c916":{"src":"assets/voice/jeppe-neural-v1/v1-56c851793fd2c916.mp3","text":"Vurder også udsagn tre og fire ud fra situationen i stedet for at stoppe ved det første korrekte. Der kan være flere korrekte svar i samme scenarie."},"v1-591e916f872ed244":{"src":"assets/voice/jeppe-neural-v1/v1-591e916f872ed244.mp3","text":"Ved begge ture skal attesterne for både det trækkende køretøj og påhængskøretøjet medbringes."},"v1-59d8ca2364a89c5c":{"src":"assets/voice/jeppe-neural-v1/v1-59d8ca2364a89c5c.mp3","text":"Motorcykler og knallerter. Tohjulede kan være svære at bedømme korrekt på afstand, især i mørke. Motorcyklister kan ændre placering for at få udsyn eller undgå ujævnheder. En lille silhuet betyder ikke nødvendigvis lav hastighed."},"v1-58f866a932261c8c":{"src":"assets/voice/jeppe-neural-v1/v1-58f866a932261c8c.mp3","text":"Hvem bestemmer? En politibetjents anvisning går foran lyssignaler, tavler og almindelige regler. Lyssignaler går foran modstridende vigepligtsafmærkning, når signalet virker. Hvis et lyssignal er ude af drift, følges synlig vigepligtsafmærkning og ellers de almindelige regler."},"v1-58e71e4d6d222c35":{"src":"assets/voice/jeppe-neural-v1/v1-58e71e4d6d222c35.mp3","text":"17-årige bilister. En 17-årig må køre alene i Danmark kl. 05.00-20.00. Kl. 20.00-05.00 kræves en ledsager, indtil føreren fylder 18 år. Den danske 17-årsordning giver ikke automatisk ret til at køre i udlandet."},"v1-59df3fb835d20ed7":{"src":"assets/voice/jeppe-neural-v1/v1-59df3fb835d20ed7.mp3","text":"Lovlig placering, orientering og sikring af bilen skal øves fysisk med kørelærer; afstande skal bedømmes på stedet."},"v1-5b8f226141db8c7d":{"src":"assets/voice/jeppe-neural-v1/v1-5b8f226141db8c7d.mp3","text":"Speedometer, temperaturmåler og kontrollys for motor."},"v1-5a33f1717383144d":{"src":"assets/voice/jeppe-neural-v1/v1-5a33f1717383144d.mp3","text":"På køreteknisk anlæg mærker du, at bilen begynder at skride ud i en glat kurve."},"v1-5a731369be958394":{"src":"assets/voice/jeppe-neural-v1/v1-5a731369be958394.mp3","text":"Styringen skal overføre rattets bevægelser præcist og uden unødig modstand, slør eller mislyde. Fra rat til forhjul. Når rattet drejes, føres bevægelsen gennem styreapparatets forbindelser og led til forhjulene. Under kørsel søger styringen normalt tilbage mod ligeud, når grebet lettes. Funktionen hjælper bilen med at følge en stabil linje, men føreren skal bevare kontrollen. Servo og ESC har forskellige roller. Hydraulisk eller elektrisk servo gør rattet lettere at dreje. Nyere biler skal have ESC, som kan bremse ét eller flere hjul for at mindske udskridning eller væltning, især i sving. Et servosvigt gør styringen tungere; fortsat kørsel kan være uforsvarlig og ulovlig. Lovkravet kan mærkes. Styreapparatet skal gøre bilen let, sikker og hurtig at styre. Der må ikke være væsentligt slør. Ved lav fart skal rattet kunne drejes fra side til side uden ujævn modstand eller mislyde, som kan afsløre en fejl. Ratslør og servovæske. Ved kontrol skal hjulene straks følge rattets bevægelse. Har bilen servostyring, skal servoen være aktiveret. En eventuel servobeholder kontrolleres efter fabrikantens forskrift, typisk mellem min- og maxmærket eller ved at sikre, at den relevante kontrollampe ikke lyser. Fejlene fortæller en historie. Tung styring kan skyldes for lidt servovæske, en slidt eller knækket drivrem eller fejl i elektrisk servo. Følger hjulene ikke rattet straks, kan der være slør. For lidt væske eller væsentligt ratslør kræver eftersyn."},"v1-5d636cd506de2fe9":{"src":"assets/voice/jeppe-neural-v1/v1-5d636cd506de2fe9.mp3","text":"Regnen begynder på en nedadgående landevej, mens du ligger tættere på bilen foran end før."},"v1-5ce057fbe507c3d6":{"src":"assets/voice/jeppe-neural-v1/v1-5ce057fbe507c3d6.mp3","text":"Bommen er oppe, men bilkøen efter jernbaneoverkørslen står så tæt, at der ikke er plads til din bil på den anden side."},"v1-5db7e524cffa714a":{"src":"assets/voice/jeppe-neural-v1/v1-5db7e524cffa714a.mp3","text":"Bagud til venstre, mod modkørende og tværgående trafik samt frem mod gående, cyklister og plads på den nye vej."},"v1-5c57e3b01de5c00e":{"src":"assets/voice/jeppe-neural-v1/v1-5c57e3b01de5c00e.mp3","text":"Hvorfor løftes koblingspedalen langsomt efter et gearskift?"},"v1-5def7d7877bbdfe9":{"src":"assets/voice/jeppe-neural-v1/v1-5def7d7877bbdfe9.mp3","text":"Du skal koble hver geartype til den anvendelse, som Plan B beskriver. Hvilken samlet kobling er korrekt?"},"v1-5e3d005f4d8acac6":{"src":"assets/voice/jeppe-neural-v1/v1-5e3d005f4d8acac6.mp3","text":"Rattet skal styre bilen. Din tro på mirakler er ikke en reservedel."},"v1-5dc45141550d03db":{"src":"assets/voice/jeppe-neural-v1/v1-5dc45141550d03db.mp3","text":"Ansvarsrunden. Gå bilen rundt sammen med kørelæreren, peg på de områder føreren skal følge, og forklar ansvarsdelingen. Kørelæreren stiller spørgsmål til ejerens, brugerens og førerens ansvar ved den konkrete bil."},"v1-5eea2da3e92da25a":{"src":"assets/voice/jeppe-neural-v1/v1-5eea2da3e92da25a.mp3","text":"Holdning og risikoblindhed. Rutine kan give overdreven tro på egne evner og gøre farer mindre synlige for føreren. Tidspres er ikke en grund til at presse andre eller reducere sikkerhedsmarginen. En ansvarlig fører retter sin kørsel efter egne begrænsninger og andres mulige fejl."},"v1-61548177cc24c222":{"src":"assets/voice/jeppe-neural-v1/v1-61548177cc24c222.mp3","text":"En cyklist, som du så i højre spejl, forsvinder fra spejlet kort før dit planlagte højresving."},"v1-61d0a16b5f537e84":{"src":"assets/voice/jeppe-neural-v1/v1-61d0a16b5f537e84.mp3","text":"Du er i tvivl om udsagn tre, men sikker på udsagn et og to i et scenarie med fire svarmuligheder."},"v1-5ef23ad9c2167683":{"src":"assets/voice/jeppe-neural-v1/v1-5ef23ad9c2167683.mp3","text":"Planen tillader kun kørsel direkte til nærmeste værksted, fordi bilens bremseegenskaber er ændret."},"v1-5f45012b6904b2e7":{"src":"assets/voice/jeppe-neural-v1/v1-5f45012b6904b2e7.mp3","text":"Kør uden alkohol og anvend den lave grænse i hele treårsperioden. Reglen følger tiden siden første B-kørekort, ikke førerens alder. Færdselsstyrelsen formidler derfor den robuste praktiske regel som ingen alkohol, når en ny bilist skal køre."},"v1-634f8885c6507473":{"src":"assets/voice/jeppe-neural-v1/v1-634f8885c6507473.mp3","text":"Hvilket spørgsmål skal du stille før du bruger højre vigepligt?"},"v1-638f7db31d51faed":{"src":"assets/voice/jeppe-neural-v1/v1-638f7db31d51faed.mp3","text":"Hvordan viser du, at du kan udpege betjeningsudstyret i undervisningsbilen?"},"v1-622c5370380f908e":{"src":"assets/voice/jeppe-neural-v1/v1-622c5370380f908e.mp3","text":"Hvad er accelerationsbanens vigtigste funktion?"},"v1-652bd365be21b9d1":{"src":"assets/voice/jeppe-neural-v1/v1-652bd365be21b9d1.mp3","text":"Koblingen styrer forbindelsen mellem motor og gearkasse i biler med manuel koblingspedal. Forbindelsen kan åbnes. Koblingen forbinder motor og gearkasse eller skiller dem ad. Grundideen er, at en plade kan presses mod en roterende del ved krumtappen, så bevægelsen går videre til gearkassen. Når koblingspedalen trædes helt ned, afbrydes forbindelsen. Pedalen beskytter og blødgør. I en bil med koblingspedal kan pedalen trædes helt i bund under motorstart for at skåne startmotoren. Ved gearskift skal den helt i bund, så gearkassen ikke beskadiges. Når pedalen løftes langsomt, føres motorkraften blødt videre til hjulene. Hydraulik og biltype. Nogle manuelle koblinger bruger hydraulik, og så skal væskeniveauet være tilstrækkeligt. Biler med automatgear og elbiler har ingen koblingspedal. Det betyder ikke, at alle transmissioner er ens; kun at føreren ikke betjener en særskilt koblingspedal."},"v1-66794868b5e2ff58":{"src":"assets/voice/jeppe-neural-v1/v1-66794868b5e2ff58.mp3","text":"Lavt gear ved igangsætning, højt gear på stejle bakker og bakgear ved kørsel baglæns."},"v1-6609997ee736dbf5":{"src":"assets/voice/jeppe-neural-v1/v1-6609997ee736dbf5.mp3","text":"Tavleassistenten kan kobles med adaptiv fartpilot, men fejlmuligheden består, og føreren fritages ikke for ansvar."},"v1-66689bc597918240":{"src":"assets/voice/jeppe-neural-v1/v1-66689bc597918240.mp3","text":"Tunge køretøjers størrelse og bevægelse kræver ekstra plads, tid og forståelse for deres svingforløb. Baghjulene følger en snævrere linje. Når et langt køretøj drejer, kan baghjulene skære tættere om hjørnet end førerhuset. Hold dig væk fra indersiden af svinget, også hvis der først ser ud til at være plads ved siden af køretøjet. Langsom acceleration ændrer hullet. Et tungt køretøj kan bruge længere tid på at sætte i gang og komme gennem et kryds. Pres ikke ind i den plads, føreren har valgt. Hullet kan være nødvendigt for både længde, svingradius og udsyn. Afstand giver gensidigt udsyn. Meget tæt kørsel bag en lastbil skjuler vej, tegn og trafik længere fremme. Øget afstand giver dig tidligere information og flere handlemuligheder og gør samtidig din bil lettere at opdage i lastbilens spejle."},"v1-6550b065ecf0c753":{"src":"assets/voice/jeppe-neural-v1/v1-6550b065ecf0c753.mp3","text":"Væsker, støj, røg og ændret kraftoverførsel giver tidlige tegn på fejl i drivlinjen. Olie og kølervæske. Motorolie kontrolleres i tilstrækkelig mængde mellem min- og maxmærker på oliepinden, via bilens instrumenter eller efter instruktionsbogen. Kølervæske kontrolleres efter instruktionsbogen. For lidt olie eller kølervæske kan skade motoren alvorligt under kørsel. Kulilte kan ikke lugtes. En utæt udstødning eller kørsel med åben bagklap kan føre kulilte ind i bilen. Gassen er lugtfri og farlig selv i små mængder. Lugt er derfor ingen sikker test; fejl og uhensigtsmæssig brug skal forebygges. Røg, støj og kraftoverførsel. Unormal udstødningsrøg peger på dårlig forbrænding, og usædvanlig støj ved gasgivning på udstødningsfejl. Stiger motorens omdrejninger uden tilsvarende fart, kan koblingen glide. Kraftige mislyde ved gearskift eller kryb med koblingen nede er også fejltegn. Elbilens batteri ændrer sig. Et højvoltsbatteri mister normalt kapacitet med alder og slid, så rækkevidden bliver kortere. Følg fabrikantens råd for at begrænse unødigt slid. Opvarmning eller køling af kabine og batteri, mens bilen stadig lader, kan forbedre rækkevidden. Lovlig stand undervejs. Føreren skal løbende være opmærksom på unødig støj og på fejl ved motor eller forureningsbegrænsende udstyr, der påvirker udledningen. En ny lyd eller røgsky er ikke noget, man gemmer til næste olieskift uden vurdering."},"v1-66ec33896ff2e476":{"src":"assets/voice/jeppe-neural-v1/v1-66ec33896ff2e476.mp3","text":"Hvilke tre retninger skal din opmærksomhed dække i et venstresving?"},"v1-67b51c74ab2f35db":{"src":"assets/voice/jeppe-neural-v1/v1-67b51c74ab2f35db.mp3","text":"Mindstekravet til mønsterdybde ophæver ikke de øvrige fejltegn; planen siger, at disse fejl skal afhjælpes umiddelbart."},"v1-668aa3d6f3139df6":{"src":"assets/voice/jeppe-neural-v1/v1-668aa3d6f3139df6.mp3","text":"Kategori B kan omfatte flere køretøjstyper, men hver type kan have særlige krav til indretning og udstyr. Flere typer under kategori B. Særregler kan gælde for varebil, påhængskøretøj til person- og varebil, quadricykel, trehjulet motorcykel, ATV, stor knallert, traktor og motorredskab, selv når køretøjet kan føres med kategori B. Førerretten gør dem ikke teknisk ens. Mål og vægt varierer. Reglerne vedrører især længde, bredde, tilladt last og tilladt totalvægt. Derfor kan man ikke overføre personbilens grænser eller antage, at et køretøj må lastes ud fra den plads, der ser ledig ud. Udstyr følger køretøjet. Bremser, lygter, dæk og spejle kan være reguleret særligt. For nogle typer er styrthjelm relevant, og for påhængskøretøj gælder særlige tilkoblingskrav. Kravene findes i reglerne for den konkrete køretøjstype; dokumenterne bruges som støtte, når de indeholder relevante oplysninger."},"v1-673bcbf04cc26139":{"src":"assets/voice/jeppe-neural-v1/v1-673bcbf04cc26139.mp3","text":"Den digitale prøve giver navigation og markering, men afholdes stadig fysisk på et prøvested. Fysisk fremmøde. Den digitale teoriprøve foregår online på en prøvelokation og kræver fysisk fremmøde. Den er ikke en hjemmeprøve. MitID skal medbringes til den digitale teoriprøve sammen med den øvrige krævede dokumentation. Navigation. I den digitale prøve kan kandidaten gå frem og tilbage, ændre valg og markere spørgsmål til senere. Brug markeringen til reel tvivl, men efterlad tid til at kontrollere, at alle fire udsagn er vurderet. Appens resultat er eget. NATKØRSEL bruger sin egen øvebedømmelse og egne scenarier. Den må forklare format og træne arbejdsgangen, men må ikke fremstille sin fejloptælling som myndighedens dokumenterede beregning eller et resultat som garanti for beståelse."},"v1-68a691e174f95221":{"src":"assets/voice/jeppe-neural-v1/v1-68a691e174f95221.mp3","text":"Lygte- og dækkontrol skal udføres på en rigtig bil; teksten kan ikke erstatte den praktiske demonstration."},"v1-68ae1ea399f66db7":{"src":"assets/voice/jeppe-neural-v1/v1-68ae1ea399f66db7.mp3","text":"Bliv holdende, følg motorcyklens bevægelse over flere observationer, og drej kun ved et tydeligt sikkert hul. Den smalle profil kan få afstand og fart til at virke mindre kritiske, end de faktisk er."},"v1-6803eb996d77651e":{"src":"assets/voice/jeppe-neural-v1/v1-6803eb996d77651e.mp3","text":"Efter kraftig regn opdager du en skade i et fordæk, samtidig med at blinklyset slår hurtigere end normalt."},"v1-6a5fa8001b490d7c":{"src":"assets/voice/jeppe-neural-v1/v1-6a5fa8001b490d7c.mp3","text":"Bliv holdende, søg cyklisten igen fra en bedre synsvinkel, og sving først, når den forventede bane er fri. Cyklisten kan fortsat bevæge sig mod krydset bag varebilen og nå højresvingsområdet, før bilen er gennem svinget."},"v1-6ac1def5af493527":{"src":"assets/voice/jeppe-neural-v1/v1-6ac1def5af493527.mp3","text":"Fordi påvirkningen kan svække både køreevnen og evnen til at bedømme denne svækkelse."},"v1-6bea6065d3b50ffa":{"src":"assets/voice/jeppe-neural-v1/v1-6bea6065d3b50ffa.mp3","text":"Hvad skal du vurdere ud over, om vejen ser fri ud i selve øjeblikket?"},"v1-6c011d5c86e31400":{"src":"assets/voice/jeppe-neural-v1/v1-6c011d5c86e31400.mp3","text":"Hvad adskiller energirigtig kørsel fra langsom tøven?"},"v1-6b7f1a328ed6bd1c":{"src":"assets/voice/jeppe-neural-v1/v1-6b7f1a328ed6bd1c.mp3","text":"Kategori B betyder, at særregler bortfalder, når ATV'en er registreret og dens tilladte totalvægt er kendt."},"v1-6f33e9e8d061c969":{"src":"assets/voice/jeppe-neural-v1/v1-6f33e9e8d061c969.mp3","text":"Gearvælgeren, parkeringsbremsens betjening og sikkerhedsselens fastgørelsespunkter."},"v1-71ab9bc8c879d48d":{"src":"assets/voice/jeppe-neural-v1/v1-71ab9bc8c879d48d.mp3","text":"Plan B knytter den væsentligt hurtigere blinkrytme direkte til, at én eller flere blinklygter normalt er ude af funktion."},"v1-6f50a6f8adec33c3":{"src":"assets/voice/jeppe-neural-v1/v1-6f50a6f8adec33c3.mp3","text":"Fordi skjul ikke stopper cyklistens bevægelse; personen kan være nået tættere på konfliktpunktet uden at være synlig."},"v1-6f2ec9fc73e95e2f":{"src":"assets/voice/jeppe-neural-v1/v1-6f2ec9fc73e95e2f.mp3","text":"Tunnel og jernbane. Ved indkørsel i tunnel kan øjnene bruge tid på at vænne sig til lysforskellen. I tunnel bør føreren kende flugtveje og følge tavler, signaler og personalets anvisninger. Ved jernbaneoverkørsel må man aldrig køre ind, hvis der ikke er plads til at komme helt fri."},"v1-72f9f1b153bd3705":{"src":"assets/voice/jeppe-neural-v1/v1-72f9f1b153bd3705.mp3","text":"Du nærmer dig rødt lys med god afstand og ingen bagvedkørende tæt på."},"v1-7399ad543341835c":{"src":"assets/voice/jeppe-neural-v1/v1-7399ad543341835c.mp3","text":"Planens særregler er ikke begrænset til styrthjelm; de kan også vedrøre mål, vægt, bremser, lygter, dæk og spejle."},"v1-7225e3cbcea4c6d8":{"src":"assets/voice/jeppe-neural-v1/v1-7225e3cbcea4c6d8.mp3","text":"Stejl bakke og bakgear er parret rigtigt, men planen knytter høje gear til høj hastighed, ikke lav hastighed."},"v1-7361d04d82288832":{"src":"assets/voice/jeppe-neural-v1/v1-7361d04d82288832.mp3","text":"Forbrændingsmotorens bevægelse føres gennem kobling og gear, mens elbilens batteri leverer strøm til elmotoren under drift."},"v1-74894ad06065ff41":{"src":"assets/voice/jeppe-neural-v1/v1-74894ad06065ff41.mp3","text":"I Danmark kan kopier af begge attester medbringes; i udlandet er almindelige kopier af begge tilstrækkelige."},"v1-7489ea2851793820":{"src":"assets/voice/jeppe-neural-v1/v1-7489ea2851793820.mp3","text":"Bilen er ikke et escape room. Find knapperne, før plottet begynder."},"v1-74d53b511de16cba":{"src":"assets/voice/jeppe-neural-v1/v1-74d53b511de16cba.mp3","text":"Hvordan kan faste punkter i omgivelserne hjælpe ved vurdering af en motorcykel?"},"v1-746bb25da72c97c6":{"src":"assets/voice/jeppe-neural-v1/v1-746bb25da72c97c6.mp3","text":"Følg kørelærerens modul- og lektionsplan og brug kun selvstudie, når det er planlagt og registreret efter reglerne. Frivillig appbrug erstatter ikke lovpligtig undervisning. Kun selvstudie, som kørelæreren har planlagt, kontrolleret og registreret inden for de tilladte dele, kan tælle i forløbet."},"v1-7510b4eb9d8ce494":{"src":"assets/voice/jeppe-neural-v1/v1-7510b4eb9d8ce494.mp3","text":"Hvad er forskellen på B 11 og B 13 før vigepligten vurderes?"},"v1-756f365be5c4ea2c":{"src":"assets/voice/jeppe-neural-v1/v1-756f365be5c4ea2c.mp3","text":"Bliv holdende, til barnet har set bilen, givet plads og ikke kan komme farligt nær. Lav fart alene opfylder ikke kravet til passage."},"v1-7559d331cab9a2e3":{"src":"assets/voice/jeppe-neural-v1/v1-7559d331cab9a2e3.mp3","text":"Sving og cyklister. Ved højresving skal man holde tilbage for cyklister og andre, der fortsætter ligeud langs vejen. Orientering skal ske tidligt og gentages lige før svinget, fordi en cyklist kan være kommet frem. Placering og lav hastighed skal gøre hensigten tydelig og give tid til at standse."},"v1-750f3efcac40c32d":{"src":"assets/voice/jeppe-neural-v1/v1-750f3efcac40c32d.mp3","text":"Fodgængere og rundkørsler. Ved fodgængerfelt skal føreren nærme sig med en hastighed, der gør det muligt at holde tilbage. Ved ind- og udkørsel af rundkørsel kræver cyklister og gående særlig orientering. Blink ud af rundkørslen fortæller om hensigten, men ophæver ikke pligten til at holde tilbage."},"v1-76fbd8b4a68ce352":{"src":"assets/voice/jeppe-neural-v1/v1-76fbd8b4a68ce352.mp3","text":"Den gælder fra første kategori B-kørekort og gennem de første tre år, uanset hvor gammel føreren er."},"v1-790140184439d290":{"src":"assets/voice/jeppe-neural-v1/v1-790140184439d290.mp3","text":"Når du kan gennemføre uden at tvinge den trafik, du viger for, til at sænke farten eller ændre placering."},"v1-78e72e8a576b1bac":{"src":"assets/voice/jeppe-neural-v1/v1-78e72e8a576b1bac.mp3","text":"GPS’en foreslår et sent baneskift, som tæt trafik gør usikkert under den afsluttende lektion."},"v1-78ffc1200032c25a":{"src":"assets/voice/jeppe-neural-v1/v1-78ffc1200032c25a.mp3","text":"Kontrollér motorolie. På den konkrete bil viser kørelæreren den korrekte metode: oliepind, instrumentvisning eller instruktionsbog. Udfør kontrollen uden værktøj efter fabrikantens anvisning, og forklar hvordan du afgør, om oliemængden er tilstrækkelig. Kontrollér kølervæske. Find beholder eller relevant visning med kørelæreren, og følg instruktionsbogen. Åbn aldrig et varmt system på egen hånd. Den praktiske kontrol skal udføres og vurderes ved bilen."},"v1-7cad3d124f5e0ad8":{"src":"assets/voice/jeppe-neural-v1/v1-7cad3d124f5e0ad8.mp3","text":"Hvad gør du, hvis bremsepedalen pludselig kan trædes længere ned end sædvanligt?"},"v1-797e9688763027c7":{"src":"assets/voice/jeppe-neural-v1/v1-797e9688763027c7.mp3","text":"Fordi dækkene så ikke samtidig skal levere en stor bremsekraft og den sidekraft, der holder bilen i kurven."},"v1-7b83634eb04c6ad9":{"src":"assets/voice/jeppe-neural-v1/v1-7b83634eb04c6ad9.mp3","text":"Kørsel i mørke trænes i den obligatoriske mørkelektion. Tåge, regn, blænding og anden nedsat sigt indgår som risikoforhold; mikrolektionen dokumenterer ingen praktisk erfaring med disse forhold."},"v1-7beda3b283f8b1c4":{"src":"assets/voice/jeppe-neural-v1/v1-7beda3b283f8b1c4.mp3","text":"Læs forbrugsvisningen. I undervisningsbilen viser kørelæreren den eventuelle energivisning. Aflæs den før og efter rolige og ujævne hastighedsændringer under lovlig undervisning, og forklar hvordan køremåden påvirker visningen. Biltypecheck. Afgør sammen med kørelæreren, om bilen er forbrændingsbil, hybrid, plug-in-hybrid eller elbil, og peg på de relevante stop-, lade- eller regenerationsfunktioner. Funktionerne afhænger af bilen."},"v1-7d281bcbfc20eaba":{"src":"assets/voice/jeppe-neural-v1/v1-7d281bcbfc20eaba.mp3","text":"Fordi hvert scenarie har fire udsagn, mindst ét er korrekt, og flere kan være korrekte."},"v1-7cf9d6680eba8eb4":{"src":"assets/voice/jeppe-neural-v1/v1-7cf9d6680eba8eb4.mp3","text":"Et barn leger foran bilen i et E 51-område og har endnu ikke set dig, selv om der er plads ved siden af."},"v1-7cbd50dda07a14f1":{"src":"assets/voice/jeppe-neural-v1/v1-7cbd50dda07a14f1.mp3","text":"Fortsæt sikkert og lad ruten blive beregnet om; drøft bagefter beslutningen med kørelæreren. Navigation er et hjælpemiddel, mens selvstændig sikker vurdering er læringsmålet. En omvej er acceptabel; et presset baneskift skaber unødig risiko for trafikken omkring bilen."},"v1-7d0f09e344000b56":{"src":"assets/voice/jeppe-neural-v1/v1-7d0f09e344000b56.mp3","text":"Selen virker på alle ture, og førerens ansvar bliver skærpet, når passageren er et barn. Kort tur, samme kræfter. Sikkerhedssele begrænser kroppens bevægelse ved opbremsning og sammenstød. Lav fart eller kort afstand gør ikke kroppen vægtløs. Brug selen korrekt, og sørg for at den ligger tæt uden vrid over kroppens stærke områder. Børn under 135 cm. Børn under 135 centimeter skal som hovedregel bruge godkendt sikkerhedsudstyr, der passer til højde og vægt. Udstyret skal monteres efter anvisningen; en løs eller forkert placeret sele kan ikke erstattes af en voksens hånd. Førerens ansvar. Føreren er ansvarlig for, at passagerer under 15 år bruger sele eller andet krævet sikkerhedsudstyr. Kontrollen skal ske før bilen kører. En ældre passagers eget ansvar fjerner ikke værdien af at sikre alle."},"v1-7db18ed537e2afa5":{"src":"assets/voice/jeppe-neural-v1/v1-7db18ed537e2afa5.mp3","text":"Fordi en cyklist kan være kommet frem i blind vinkel siden den første kontrol."},"v1-7db543aaa6022084":{"src":"assets/voice/jeppe-neural-v1/v1-7db543aaa6022084.mp3","text":"Få årsagen undersøgt og straks afhjulpet; den kan være dæktryk, hjulindstilling, bremser, støddæmpere eller andre hjulfejl."},"v1-7d30e2f8d6727582":{"src":"assets/voice/jeppe-neural-v1/v1-7d30e2f8d6727582.mp3","text":"Start tidligt og varm motoren roligt i tomgang; accelerér derefter forsigtigt i lave gear og koble ud ved fartreduktion."},"v1-7d2e556156c94725":{"src":"assets/voice/jeppe-neural-v1/v1-7d2e556156c94725.mp3","text":"Prøven kræver fysisk fremmøde, og navigationen foregår inden for den officielle prøve og dens tidsramme."},"v1-7e1c09155840dae9":{"src":"assets/voice/jeppe-neural-v1/v1-7e1c09155840dae9.mp3","text":"Hvorfor må du ikke handle efter letbanens hvide signal?"},"v1-7e1a9ffb6626b647":{"src":"assets/voice/jeppe-neural-v1/v1-7e1a9ffb6626b647.mp3","text":"ABS-lampen slukker ikke kort efter igangsætning. Hvilken kørselsadgang angiver Plan B præcist for denne fejl?"},"v1-7e3a34df2e9f80da":{"src":"assets/voice/jeppe-neural-v1/v1-7e3a34df2e9f80da.mp3","text":"Fordi andre trafikanter kan komme ind i området, mens bilen skifter retning og holder stille."},"v1-7efe5ea357bb20df":{"src":"assets/voice/jeppe-neural-v1/v1-7efe5ea357bb20df.mp3","text":"Vending. En vending kræver tilstrækkeligt udsyn og plads samt løbende orientering. Manøvren skal afbrydes, hvis en trafikant pludselig kommer ind i området. På motorvej og til- eller frakørselsvej er vending og bakning forbudt."},"v1-7f83eef881cd95ec":{"src":"assets/voice/jeppe-neural-v1/v1-7f83eef881cd95ec.mp3","text":"Afbrydelse kan være en forsigtig handling, men displayets oplysning får ikke forrang, og førerens ansvar består fortsat."},"v1-7febf05f4bd5a507":{"src":"assets/voice/jeppe-neural-v1/v1-7febf05f4bd5a507.mp3","text":"At give plads til farttilpasning, orientering og valg af et sikkert ophold før indkørsel."},"v1-7f0c9376bb2b1bb8":{"src":"assets/voice/jeppe-neural-v1/v1-7f0c9376bb2b1bb8.mp3","text":"Skoler, butikker og stoppesteder. Vejens omgivelser kan varsle børn, ældre eller gående, der handler uventet. Parkerede biler kan skjule personer, der er på vej ud på kørebanen. Ved stoppesteder og butikker bør føreren forvente krydsende og distraherede trafikanter."},"v1-811de10f804b930a":{"src":"assets/voice/jeppe-neural-v1/v1-811de10f804b930a.mp3","text":"En overhaling er kun sikker, når hele forløbet og en mulig afbrydelse er planlagt på forhånd. Før beslutningen. Kontroller forbud, vejforløb, modkørende, bagfrakommende og pladsen foran den, du vil overhale. Øg afstanden til et stort køretøj for bedre udsyn længere fremad. Begynd ikke, hvis nogen bagfra allerede overhaler. Under overhalingen. Hold tilstrækkelig sideafstand og gennemfør effektivt uden at overskride hastighedsgrænsen. Bevar overblik fremad og bagud. Hvis en skjult hindring eller modkørende gør pladsen tvivlsom, afbryd tidligt i stedet for at håbe. Sikker tilbagevenden. Træk først ind, når den overhalede er synlig i det indvendige spejl, medmindre et tidligere indtræk er nødvendigt for at afværge fare. Sørg for afstand både foran og bag den overhalede efter manøvren."},"v1-81646a50ca2bdd8a":{"src":"assets/voice/jeppe-neural-v1/v1-81646a50ca2bdd8a.mp3","text":"Planen beskriver ikke den hurtige rytme som en selvtest; den er normalt et tegn på en ikke-fungerende blinklygte."},"v1-83a56f2a04cb47cf":{"src":"assets/voice/jeppe-neural-v1/v1-83a56f2a04cb47cf.mp3","text":"Planen deler ansvaret netop sådan og pålægger føreren særskilt at sikre en forsvarlig tilkobling ved kørsel med påhængskøretøj."},"v1-818d50947b850b78":{"src":"assets/voice/jeppe-neural-v1/v1-818d50947b850b78.mp3","text":"Motorlampen hører til 1.1.2.2, men speedometer og temperaturmåler er instrumenter under 1.1.2.1."},"v1-81244dc4f4d3029d":{"src":"assets/voice/jeppe-neural-v1/v1-81244dc4f4d3029d.mp3","text":"Afsnit 7.22 er afsluttende fysisk øvelseskørsel med kørelærer; appen kan kun forberede og støtte refleksion."},"v1-8540eab70ba6a30e":{"src":"assets/voice/jeppe-neural-v1/v1-8540eab70ba6a30e.mp3","text":"Ingen farlige kanter eller fremspring, ingen sikkerhedsfarlig skade eller rust og låse, der holder døre og klapper lukkede."},"v1-8514282ede53bc2b":{"src":"assets/voice/jeppe-neural-v1/v1-8514282ede53bc2b.mp3","text":"Du kan få hjælp fra bilen. Du kan ikke give ansvaret til en NPC."},"v1-84ea8c6b97d35d3e":{"src":"assets/voice/jeppe-neural-v1/v1-84ea8c6b97d35d3e.mp3","text":"Udsyn, vejgreb, vejforløb, trafik og den afstand du behøver for at opdage, reagere og standse."},"v1-84953aa1f2138193":{"src":"assets/voice/jeppe-neural-v1/v1-84953aa1f2138193.mp3","text":"En vending er først forsvarlig, når sted, udsyn, trafik og manøvrens mange bevægelser kan kontrolleres samlet. Vælg stedet kritisk. Vending kræver plads og udsyn i flere retninger gennem hele manøvren. Undgå steder, hvor bakke, sving, tæt trafik eller skjulte trafikanter kan gøre en del af forløbet uoverskueligt. Kør videre til et bedre sted ved tvivl. Hver del kræver ny orientering. En trepunktsvending består af flere igangsætninger, standsninger og retningsskift. Trafikbilledet kan ændre sig mellem dem. Gentag derfor orienteringen før hver bevægelse i stedet for at behandle hele vendingen som én beslutning. Nogle veje udelukker manøvren. På motorvej må føreren ikke vende eller bakke. Fejlkørsel skal derfor løses ved at fortsætte til en lovlig afkørsel. En sen ruteændring er aldrig grund til en manøvre, der bryder vejens sikre trafikretning."},"v1-855215bcd4be3a9e":{"src":"assets/voice/jeppe-neural-v1/v1-855215bcd4be3a9e.mp3","text":"Korrekt indstilling og orientering skal øves fysisk i undervisningsbilen med en kørelærer."},"v1-86cfbd99d1f379ef":{"src":"assets/voice/jeppe-neural-v1/v1-86cfbd99d1f379ef.mp3","text":"Du opdager en forkert rute på en smal vej lige før en uoverskuelig bakketop og overvejer at vende straks."},"v1-85a67719a341c374":{"src":"assets/voice/jeppe-neural-v1/v1-85a67719a341c374.mp3","text":"Stempelbevægelsen bliver til rotation i krumtappen, som føres videre gennem kobling og gear til hjulene."},"v1-856a94c5d435fbc9":{"src":"assets/voice/jeppe-neural-v1/v1-856a94c5d435fbc9.mp3","text":"Følg kørelærerens instruktion, undgå panikbevægelser og søg roligt at genvinde vejgreb og kurs. Bratte input kan bruge det sidste greb og forværre udskridningen. Øvelsen skal netop give fysisk erfaring under kontrollerede forhold, som en tekstforklaring ikke kan erstatte."},"v1-8702cb812acd7fcc":{"src":"assets/voice/jeppe-neural-v1/v1-8702cb812acd7fcc.mp3","text":"Du har påbegyndt en parkering, men kan ikke længere se den lave pullert ved bilens højre forhjørne."},"v1-873c42436201df0b":{"src":"assets/voice/jeppe-neural-v1/v1-873c42436201df0b.mp3","text":"Fordi det kun skelner standsning fra parkering; steder med standsningsforbud er stadig ulovlige."},"v1-874ee54a0c7f2aba":{"src":"assets/voice/jeppe-neural-v1/v1-874ee54a0c7f2aba.mp3","text":"Ved vejarbejde peger gule banestriber mod venstre, mens de gamle hvide striber fortsætter ligeud."},"v1-885e27913ab179e0":{"src":"assets/voice/jeppe-neural-v1/v1-885e27913ab179e0.mp3","text":"Slip speederen roligt, øg afstanden og vælg en fart før kurven, der mindsker behovet for kraftig bremsning under svinget. Vand kan reducere dækkenes kontakt, og samtidige store styre- og bremsekrav bruger mere af det begrænsede vejgreb."},"v1-89eb7e3542e66464":{"src":"assets/voice/jeppe-neural-v1/v1-89eb7e3542e66464.mp3","text":"Overhalingsbedømmelse skal udvikles gradvist med kørelærer; appen kan ikke træne reel afstand og hastighed."},"v1-89c7ae08166f4eef":{"src":"assets/voice/jeppe-neural-v1/v1-89c7ae08166f4eef.mp3","text":"Den første kan indeholde skjult trafik; den anden er synlig langt nok til, at den planlagte manøvre kan afsluttes sikkert."},"v1-88732c07bd8986fa":{"src":"assets/voice/jeppe-neural-v1/v1-88732c07bd8986fa.mp3","text":"Standsning og parkering. Standsning kortere end tre minutter er ikke parkering; af- og påstigning samt aktiv af- og pålæsning regnes heller ikke som parkering. Uden afmærket bås må man hverken standse eller parkere i et kryds eller nærmere end 10 m fra den tværgående kørebanes nærmeste kant. Man må hverken standse eller parkere på et fodgængerfelt eller nærmere end 5 m foran feltet. Standsning og parkering er forbudt på cykelsti, gangsti og som hovedregel fortov; den begrænsede fortovsundtagelse uden for tættere bebygget område gælder ikke cykelsti. P-tavler, undertavlers tidsrum og reserverede båse skal følges; en handicapbås kræver gyldigt parkeringskort."},"v1-887150c5104e9acd":{"src":"assets/voice/jeppe-neural-v1/v1-887150c5104e9acd.mp3","text":"Begrænset sigt ændrer, hvor tidligt føreren kan opdage en fare, og dermed hvilken fart og afstand der er forsvarlig. Du skal kunne reagere inden for det synlige. Tåge, mørke, regn eller blænding forkorter den strækning, du kan overskue. Tilpas farten, så ny information kan nå at føre til en sikker reaktion, og øg afstanden til den forankørende. Lysvalg påvirker både dig og andre. Brug den belysning, som forholdene kræver, og skift i tide, så andre ikke blændes. Mere lys er ikke altid bedre: tåge og nedbør kan sende lyset tilbage og gøre kontraster sværere at se. Efter blænding kræves ny sikkerhedsmargin. Når en modkørendes lys kortvarigt forringer synet, skal blikket søge vejens højre begrænsning uden at låse sig fast i lyset. Sænk farten efter behov, fordi synet ikke straks giver samme detaljer som før."},"v1-8ace06bc9c3af20a":{"src":"assets/voice/jeppe-neural-v1/v1-8ace06bc9c3af20a.mp3","text":"Hvorfor er en plug-in-hybrid ikke automatisk energi- og miljørigtig?"},"v1-8a2b30fc78da44ed":{"src":"assets/voice/jeppe-neural-v1/v1-8a2b30fc78da44ed.mp3","text":"Opspeedningen tyder på koblingsfejl; mislydene ved vanskelig gearskiftning tyder på fejl i gear eller kobling."},"v1-8a34173a57278e63":{"src":"assets/voice/jeppe-neural-v1/v1-8a34173a57278e63.mp3","text":"Tåge, regn og sol. Dårligt udsyn kræver lavere hastighed og større mulighed for at standse inden for det overskuelige område. Nærlys er normalt lys ved dårlig sigt; særligt kørelys er ikke nok i lygtetændingstiden. Fjernlys kan blænde og kan gøre udsynet dårligere i tæt nedbør eller tåge."},"v1-8ad514eb2261b02a":{"src":"assets/voice/jeppe-neural-v1/v1-8ad514eb2261b02a.mp3","text":"Bak i meget lav fart, stands før fortovet, og skab nyt udsyn med direkte orientering til begge sider. En gående kan nærme sig uden for kameraets felt, og først den nye position giver et tilstrækkeligt beslutningsgrundlag."},"v1-8b69ce063b164507":{"src":"assets/voice/jeppe-neural-v1/v1-8b69ce063b164507.mp3","text":"Dækket er din kontakt med virkeligheden. Bogstaveligt talt."},"v1-8b759c4b6a6ab429":{"src":"assets/voice/jeppe-neural-v1/v1-8b759c4b6a6ab429.mp3","text":"Planen lægger den lovlige stand hos ejeren eller den registrerede bruger, mens føreren har ansvaret for den sikkerhedsmæssigt forsvarlige stand."},"v1-8b6a9775df27ae22":{"src":"assets/voice/jeppe-neural-v1/v1-8b6a9775df27ae22.mp3","text":"Når bilen skal have stor trækkraft eller køre langsomt, eksempelvis ved igangsætning, acceleration eller en stejl bakke."},"v1-8c1aea60382b8f16":{"src":"assets/voice/jeppe-neural-v1/v1-8c1aea60382b8f16.mp3","text":"Start og standsning. Ved igangsætning fra vejkant skal der altid gives tegn i god tid; tegnet giver ikke fortrinsret. Hastigheden ved igangsætning skal være så lav, at bilen hele tiden kan kontrolleres. Standsning bør ske roligt og på et sted, hvor bilen ikke skaber fare eller unødig ulempe."},"v1-8ceea5da7dba2949":{"src":"assets/voice/jeppe-neural-v1/v1-8ceea5da7dba2949.mp3","text":"Hvorfor kan det være farligt blot at følge baglygterne foran i tåge?"},"v1-8e17b6d71e2ccc46":{"src":"assets/voice/jeppe-neural-v1/v1-8e17b6d71e2ccc46.mp3","text":"Det er lovligt at lade bilen stå, men udsagnet gengiver ikke planen: den tillader den snævert afgrænsede kørsel til nærmeste værksted."},"v1-8d8118913ff0da21":{"src":"assets/voice/jeppe-neural-v1/v1-8d8118913ff0da21.mp3","text":"Vent med svinget, orientér dig direkte mod højre, og genfind cyklisten eller fastslå sikkert, hvor personen er. At cyklisten ikke længere ses, betyder ikke, at banen er fri; cyklisten kan være flyttet ind i bilens skjulte område."},"v1-8eeb4af966457c7c":{"src":"assets/voice/jeppe-neural-v1/v1-8eeb4af966457c7c.mp3","text":"De fem moduler. Den moderniserede kategori B-uddannelse er bygget op i fem moduler. Minimumsforløbet omfatter 30 teorilektioner og 24 praktiske lektioner på mindst 45 minutter. Egen hjemmebrug tæller ikke automatisk som undervisning; kørelæreren kan planlægge og registrere højst syv selvstudielektioner i egnede dele af afsnit 1, 3, 6, 9 og 10, dog ikke afsnit 10 i modul 1."},"v1-8f33aaacecefcc0d":{"src":"assets/voice/jeppe-neural-v1/v1-8f33aaacecefcc0d.mp3","text":"Bliv bag traktoren med afstand, og vent med overhaling, til den nødvendige modgående strækning kan overskues. Fravær af en synlig bil er ikke fri bane, når bakketoppen skjuler den del af vejen, som overhalingen kræver."},"v1-8eed67fdd924c3fb":{"src":"assets/voice/jeppe-neural-v1/v1-8eed67fdd924c3fb.mp3","text":"Sænk farten og vent bag varebilen, hvor bussen har fri passage. Hindringen er på din side, og et samtidigt møde ville fjerne sikker sideafstand."},"v1-8f69d519205a9794":{"src":"assets/voice/jeppe-neural-v1/v1-8f69d519205a9794.mp3","text":"Sænk straks farten, skab sideafstand og vær klar til at standse, mens du søger efter et barn bag bilerne. Bolden er et tidligt tegn på mulig bevægelse; handling før barnet bliver synligt giver mere plads og reaktionstid."},"v1-8f26d7b179a9de94":{"src":"assets/voice/jeppe-neural-v1/v1-8f26d7b179a9de94.mp3","text":"Kategori B-forløbet er modulopbygget, så teori og praksis udvikles i en fast læringsmæssig rækkefølge. Fem moduler. Den moderniserede uddannelse er opdelt i fem moduler, hvor teori og praksis hænger sammen. Teorien til en praktisk øvelse gennemgås før øvelsen, og eleven bevæger sig fra lettere til mere krævende situationer. Minimumslektioner. For kategori B omfatter minimumsforløbet 30 teorilektioner og 24 praktiske lektioner af mindst 45 minutter. Tallene er minimum; kørelæreren skal tilrettelægge yderligere undervisning, hvis eleven ikke har nået de krævede mål. Selvstudie er styret. Hjemmearbejde tæller ikke automatisk som lovpligtig undervisning. Kørelæreren kan planlægge og registrere højst syv selvstudielektioner i egnede dele af afsnit 1, 3, 6, 9 og 10, med de begrænsninger bekendtgørelsen angiver."},"v1-902821a21c4d28a1":{"src":"assets/voice/jeppe-neural-v1/v1-902821a21c4d28a1.mp3","text":"Kategori B er ikke et “jeg kører alt”-abonnement."},"v1-90072970a15a00ca":{"src":"assets/voice/jeppe-neural-v1/v1-90072970a15a00ca.mp3","text":"Kør langsomt frem og stands igen, før du kommer ind i tværtrafikkens bane. Stoppligten er opfyldt, men vigepligten kræver fortsat sikkert udsyn."},"v1-90f909e0562d3d8e":{"src":"assets/voice/jeppe-neural-v1/v1-90f909e0562d3d8e.mp3","text":"Find et sikkert og lovligt sted at standse, og fortsæt ikke, medmindre du igen kan køre fuldt betryggende. De gentagne svigt viser, at vigtig information ikke bliver bearbejdet; at presse videre kan gøre næste oversete forhold farligt."},"v1-8ff3e871e5e30a24":{"src":"assets/voice/jeppe-neural-v1/v1-8ff3e871e5e30a24.mp3","text":"Et kørekort som 17-årig giver førerret med særlige tids-, ledsager- og landegrænser indtil 18 år. Dag og nat. En 17-årig med kørekort må køre alene i Danmark mellem klokken 05.00 og 20.00. Fra 20.00 til 05.00 skal en ledsager være med, indtil føreren fylder 18 år. Ansvaret for reglen ligger hos føreren. Ledsagerens krav. Ledsageren skal blandt andet være mindst 24 år, have haft gyldigt dansk eller færøsk kørekort i mindst fem år, ikke have været frakendt førerretten de seneste fem år og sidde foran med kørekortet tilgængeligt. Kun Danmark. Indtil 18-årsdagen må den 17-årige kun køre i Danmark. Det gælder også i timer, hvor solokørsel er tilladt. Et dansk plastikkørekort eller en ledsager udvider ikke ordningen til kørsel i udlandet."},"v1-91a3a28a1217d6f6":{"src":"assets/voice/jeppe-neural-v1/v1-91a3a28a1217d6f6.mp3","text":"Du låner en bil til at trække en trailer og ser samtidig en ukendt advarselslampe ved start."},"v1-917d49da6a331ad5":{"src":"assets/voice/jeppe-neural-v1/v1-917d49da6a331ad5.mp3","text":"Du stopper korrekt ved linjen, men en hæk skjuler trafikken fra højre. En meter fremme kan du se uden at spærre."},"v1-915276c51a20d790":{"src":"assets/voice/jeppe-neural-v1/v1-915276c51a20d790.mp3","text":"Hvorfor er kategori B alene ikke nok til at afgøre et særligt køretøjs udstyrskrav?"},"v1-91ba6688877174ff":{"src":"assets/voice/jeppe-neural-v1/v1-91ba6688877174ff.mp3","text":"Lys, horn og dæk. Lygter og reflekser skal være hele og rene, så bilen kan ses og signalerne forstås. Dæk skal have mindst 1,6 mm mønsterdybde i hovedmønstret og være ubeskadigede. Et blinklys, der blinker usædvanligt hurtigt, kan være tegn på en defekt blinklygte."},"v1-91f2578e7ada7b34":{"src":"assets/voice/jeppe-neural-v1/v1-91f2578e7ada7b34.mp3","text":"Kontrollen gælder både tilstrækkelig sprinklervæske og viskernes evne til faktisk at holde forruden ren, uanset vejrudsigten."},"v1-9286837dbb14d6c3":{"src":"assets/voice/jeppe-neural-v1/v1-9286837dbb14d6c3.mp3","text":"Sænk farten og hold tilbage før deres krydsning. Udkørslen skærer deres linjer, og blinket ændrer ikke din pligt til sikker passage."},"v1-924d3a025fcf9450":{"src":"assets/voice/jeppe-neural-v1/v1-924d3a025fcf9450.mp3","text":"Højre vigepligt. Hvor ingen har ubetinget vigepligt, skal man som udgangspunkt holde tilbage for kørende fra højre. Højre vigepligt kræver også kontrol af, om andre faktisk overholder deres pligt. Reglen gælder ikke som erstatning for reglerne om vognbaneskift og sammenfletning."},"v1-9241b48921d990a1":{"src":"assets/voice/jeppe-neural-v1/v1-9241b48921d990a1.mp3","text":"Parkering starter med at skelne mellem opholdets formål og stedets konkrete forbud. Standsning eller parkering. Parkering er enhver hensætning, men standsning under tre minutter samt nødvendig af- og påstigning eller aktiv af- og pålæsning regnes ikke som parkering. Et standsningsforbud er derfor bredere og rammer også korte frivillige ophold. Kryds og fodgængerfelt. Uden afmærket bås må du hverken standse eller parkere i et kryds eller nærmere end 10 meter fra den tværgående kørebanes nærmeste kant. Ved fodgængerfelt gælder forbuddet i feltet og 5 meter foran. Sti, fortov og reserveret plads. Standsning og parkering er forbudt på cykelsti og gangsti og som hovedregel på fortov. En handicapbås kræver gyldigt parkeringskort. Læs altid undertavlens tidsrum og pile; en lovlig plads kan være reserveret eller tidsbegrænset."},"v1-92c273addcdc0675":{"src":"assets/voice/jeppe-neural-v1/v1-92c273addcdc0675.mp3","text":"Hvorfor er en åben bom ikke alene nok til at begynde passage af en jernbaneoverkørsel?"},"v1-93d87b4cbc2e9d11":{"src":"assets/voice/jeppe-neural-v1/v1-93d87b4cbc2e9d11.mp3","text":"I Danmark er bilens kopi nok; i udlandet er påhængskøretøjets originale attest alene tilstrækkelig."},"v1-928d98f25c7f17e7":{"src":"assets/voice/jeppe-neural-v1/v1-928d98f25c7f17e7.mp3","text":"En sikker kørestilling gør betjeningen rolig og udsynet pålideligt, før bilen bevæger sig. Byg fra sædet. Indstil først sæde og ryglæn, så pedaler og rat kan betjenes uden at strække kroppen. Indstil derefter spejlene fra den færdige siddestilling. Flytter du sædet bagefter, ændrer du også det udsnit, spejlene viser. Udsyn er et system. Forrude, sideruder og spejle supplerer hinanden, men de fjerner ikke alle skjulte områder. Brug spejlene som tidlig information, og supplér med direkte orientering, når en manøvre kan bringe cyklister, gående eller andre tæt på bilen. Kabinen skal tåle en opbremsning. En løs telefon eller flaske kan flytte sig ved en pludselig opbremsning og forstyrre både fører og pedaler. Placér genstande stabilt, spænd sikkerhedsselen korrekt, og lær betjeningsgrebene, mens bilen holder stille."},"v1-935f5057c890e686":{"src":"assets/voice/jeppe-neural-v1/v1-935f5057c890e686.mp3","text":"Instrumenter, lamper, displaybeskeder og lyde skal forstås i den konkrete undervisningsbil. Målere fortæller om bilen. Speedometeret viser kørehastigheden. Bilen kan desuden have en omdrejningstæller og en temperaturmåler. Du skal kunne finde, aflæse og forstå de instrumenter, der findes i den konkrete undervisnings- og prøvebil, fordi deres placering og udformning kan variere mellem biler. Kontrollys er ikke pynt. Kontrollys kan gælde åbne døre, bilens elektriske system, lygter, blinklys og parkeringsbremse. Andre varsler gælder ABS, ESC, motor, airbag, bremsesystem og eventuelt olietryk. I undervisningsbilen skal du lære hvert relevant symbols betydning og den reaktion, som situationen kræver. Display og lyd kræver vurdering. En besked eller alarmlyd kan handle om kørsel, miljø eller sikkerhed. Læs hele beskeden, find det tilhørende symbol og reager efter bilens anvisning og kørelærerens instruktion. Et højt bip er ikke automatisk farligere end et stille symbol; betydningen skal forstås."},"v1-94aab6cb1723df12":{"src":"assets/voice/jeppe-neural-v1/v1-94aab6cb1723df12.mp3","text":"Hvorfor er højre blink alene utilstrækkeligt ved udkørsel?"},"v1-9706c57ff1fd6b3b":{"src":"assets/voice/jeppe-neural-v1/v1-9706c57ff1fd6b3b.mp3","text":"Rustskaden har et sådant omfang, at den er farlig for færdselssikkerheden."},"v1-9775e05a515b4d87":{"src":"assets/voice/jeppe-neural-v1/v1-9775e05a515b4d87.mp3","text":"Bremsning og vejgreb. Dæk kan kun overføre begrænsede kræfter til vejen. Hård bremsning og kraftig styring samtidig kan overskride vejgrebet. Elektroniske systemer hjælper, men kan ikke skabe greb på en glat vej."},"v1-94738c2a5903b5d4":{"src":"assets/voice/jeppe-neural-v1/v1-94738c2a5903b5d4.mp3","text":"Mønster og skader. På samtlige hjul på den konkrete bil viser kørelæreren hovedmønster og eventuelle slidindikatorer. Kontrollér mindst 1,6 millimeter i hovedmønstret samt synlige skader på dæk og fælge. Omløbsretning. Find pil eller anden retningsmarkering på et retningsbestemt dæk sammen med kørelæreren, og kontrollér den mod hjulets fremadgående rotation. Kravet gælder kun, når dækket er retningsbestemt."},"v1-987683bbf19f9a79":{"src":"assets/voice/jeppe-neural-v1/v1-987683bbf19f9a79.mp3","text":"Denne mulighed passer her."},"v1-992c186f2248a0c6":{"src":"assets/voice/jeppe-neural-v1/v1-992c186f2248a0c6.mp3","text":"En bold ruller ud fra en række parkerede biler, men der er endnu ingen person synlig."},"v1-97e7cfa11699e585":{"src":"assets/voice/jeppe-neural-v1/v1-97e7cfa11699e585.mp3","text":"Kurver og bakker skjuler det næste vejstykke, så farten skal vælges ud fra det, der kan ses, ikke det man håber er frit. Den skjulte del kan allerede være optaget. Bag en kurve eller bakketop kan der stå et køretøj, være kø eller ligge en forhindring. Kør ind med en fart og placering, der giver handlemulighed inden for den synlige frie strækning. Farten vælges før kurven. Tidlig farttilpasning giver ro til at se gennem kurven og styre stabilt. En sen kraftig opbremsning kan flytte opmærksomheden fra vejforløbet og kræve mere vejgreb, netop mens bilen også skal dreje. Overhaling kræver dokumenteret udsyn. Før en overhaling skal hele den nødvendige strækning kunne overskues. Ved bakketop eller uoverskuelig kurve kan modkørende være skjult, og en kort tilsyneladende fri strækning er derfor ikke et sikkert hul."},"v1-9857dab49eaf731e":{"src":"assets/voice/jeppe-neural-v1/v1-9857dab49eaf731e.mp3","text":"Forstå den enkle kraftvej i forbrændingsbil, elbil og hybrid uden at gøre dig til mekaniker. Forbrændingsmotorens kraftvej. I en forbrændingsmotor antændes en blanding af luft og brændstof. Det bevæger stemplerne. Deres bevægelse omdannes til rotation i krumtappen, og rotationen føres videre gennem kobling og gear til hjulene. Speederen regulerer motorens omdrejninger, ikke direkte hjulenes fart. Startmotoren låner strøm. En forbrændingsmotor kommer i gang med hjælp fra en elektrisk startmotor, som får strøm fra batteriet. Når motoren er startet, skal nøgle eller startknap slippes med det samme. Ellers fortsætter startmotoren unødigt og kan tage skade. Elbil og hybrid er forskellige. En elbil drives af en elmotor, der får strøm fra bilens batteri. I en hybrid kan elmotoren være kombineret med en forbrændingsmotor. Derfor skal du skelne mellem ren elektrisk drift og en drivlinje, hvor to motortyper indgår."},"v1-9a399e4c00df6095":{"src":"assets/voice/jeppe-neural-v1/v1-9a399e4c00df6095.mp3","text":"Sænk farten før toppen og behold en placering med afstand til midten. Du skal kunne reagere inden for den vejstrækning, du faktisk kan overskue."},"v1-9a614777a8442494":{"src":"assets/voice/jeppe-neural-v1/v1-9a614777a8442494.mp3","text":"Igangsætning og bakgear er parret rigtigt, men en stejl bakke hører til anvendelserne for lave gear, ikke høje."},"v1-99445faa53dc814a":{"src":"assets/voice/jeppe-neural-v1/v1-99445faa53dc814a.mp3","text":"Følg skiltningen, sænk hastigheden i god tid, og hold øje med arbejdere og ændrede baneforløb. Assistentens data kan være uaktuelle, mens skiltning og den konkrete risiko på stedet gælder for din kørsel."},"v1-998541e125106b36":{"src":"assets/voice/jeppe-neural-v1/v1-998541e125106b36.mp3","text":"Undlad at køre, placér og fastgør genstanden forsvarligt, og kontrollér, at registreringsoplysninger, førerret og faktisk belastning passer sammen. En korrekt kobling forhindrer ikke løs last i at forskyde balancen eller skabe fare under turen."},"v1-9b6d27ae7f638419":{"src":"assets/voice/jeppe-neural-v1/v1-9b6d27ae7f638419.mp3","text":"Hvad gør du først, når et lyssignal er ude af drift?"},"v1-9b3eb0ad7ae4a870":{"src":"assets/voice/jeppe-neural-v1/v1-9b3eb0ad7ae4a870.mp3","text":"Du har forkørselsret, men en ældre cyklist fra sidevejen ser ikke mod dig og ruller frem."},"v1-9b00876aee0656be":{"src":"assets/voice/jeppe-neural-v1/v1-9b00876aee0656be.mp3","text":"Bliv holdende, kontrollér dækket og de udvendige blinklygter, og få fejlene bragt i orden før turen. Dækket påvirker vejgrebet, og et svigtende blinksignal kan gøre dine manøvrer uklare for andre trafikanter."},"v1-9a77ea7d95a8c56c":{"src":"assets/voice/jeppe-neural-v1/v1-9a77ea7d95a8c56c.mp3","text":"Den vigtigste udskridningsmanøvre sker før udskridningen: korrekt fart før kurven eller hindringen. Forebyg først. For høj indgangsfart, brat styring og glat føre øger risikoen for tab af vejgreb. Sænk farten på den lige strækning før kurven. Når bilen allerede skrider, er handlemulighederne mindre og mere følsomme. Undvigelse kræver ro. Ved en pludselig hindring kan både bremsning og undvigelse være nødvendig. Se mod den sikre vej, undgå unødigt voldsomme ratbevægelser og tilpas handlingen til grebet. En panikbevægelse kan skabe en ny udskridning. Erfaring kan ikke læses. Planen kræver øvelser på almindeligt og glat underlag, så eleven mærker forskellen i fart, bremsning og styring. En forklaring kan forberede rækkefølgen, men kan ikke give den fysiske erfaring med bilens reaktion."},"v1-9c2fba437b21ebe6":{"src":"assets/voice/jeppe-neural-v1/v1-9c2fba437b21ebe6.mp3","text":"Du blinker for at skifte bane, men en bil ligger stadig tæt ved siden af dig."},"v1-9d2c7f4e21f45b63":{"src":"assets/voice/jeppe-neural-v1/v1-9d2c7f4e21f45b63.mp3","text":"Det er normalt tegn på, at én eller flere af bilens blinklygter ikke virker."},"v1-9c725f3a17e4e29e":{"src":"assets/voice/jeppe-neural-v1/v1-9c725f3a17e4e29e.mp3","text":"Starttidspunktet passer, men de lave gear og den sene farttilpasning strider mod rådene om højt gear og tidlig tilpasning før signalet."},"v1-9d79391fa0762d69":{"src":"assets/voice/jeppe-neural-v1/v1-9d79391fa0762d69.mp3","text":"På en 80-vej skjuler en bakketop kørebanen foran, og der kan være en langsom traktor på den anden side."},"v1-9dff480136e9e79e":{"src":"assets/voice/jeppe-neural-v1/v1-9dff480136e9e79e.mp3","text":"Hvilke to ting adskiller digital prøveadfærd fra en hjemmequiz?"},"v1-9dbabc4ff03f80e3":{"src":"assets/voice/jeppe-neural-v1/v1-9dbabc4ff03f80e3.mp3","text":"Hvorfor skal bilens forhjørner kontrolleres, selv om bilen bevæger sig baglæns?"},"v1-9d96e67a0073f783":{"src":"assets/voice/jeppe-neural-v1/v1-9d96e67a0073f783.mp3","text":"Planlæg ledsager eller anden transport for hele perioden efter klokken 20.00. Solokørsel er kun tilladt til klokken 20.00, ikke efter turens starttidspunkt. Hele den del af turen, der ligger efter grænsen, kræver en egnet ledsager."},"v1-9d8c5441623e251e":{"src":"assets/voice/jeppe-neural-v1/v1-9d8c5441623e251e.mp3","text":"Forlæns parkering ved vejkant. Øvelsen i afsnit 2.7 trænes praktisk på lukket øvelsesplads med kørelærer; appen kan kun forberede observationer og rækkefølge. Ved forlæns parkering ved højre vejkant skal farten være så lav, at føreren kan bedømme bilens bredde og hjulenes placering. Blik og orientering skal fordeles mellem pladsen, bilens hjørner og trafikanter omkring manøvren. På øvelsespladsen trænes først med god plads til korrektion og derefter på et mere begrænset område. Slutstillingen skal være parallel med kanten og med højre hjul højst 20 cm fra kanten; et korrekt appsvar gennemfører ikke den praktiske færdighed."},"v1-9eb93462dd4d1297":{"src":"assets/voice/jeppe-neural-v1/v1-9eb93462dd4d1297.mp3","text":"Lavt gear på stejle bakker, højt gear ved lav hastighed og bakgear ved kørsel baglæns."},"v1-9e05f7536c7a9f66":{"src":"assets/voice/jeppe-neural-v1/v1-9e05f7536c7a9f66.mp3","text":"Planen knytter forbrændingsbilens batteri til den elektriske startmotor og elbilens batteri til den drivende elmotor."},"v1-9eb80d916fa6f883":{"src":"assets/voice/jeppe-neural-v1/v1-9eb80d916fa6f883.mp3","text":"Forudseenhed kobler synlige tegn til mulige risici og skaber sikkerhedsmargin, men behandler ikke muligheden som et sikkert faktum."},"v1-9e5eefcbe36ccfc2":{"src":"assets/voice/jeppe-neural-v1/v1-9e5eefcbe36ccfc2.mp3","text":"En lastbil foran dig trækker mod venstre før et højresving, og der åbner sig kortvarigt plads langs dens højre side."},"v1-9f3a77c3566b5e96":{"src":"assets/voice/jeppe-neural-v1/v1-9f3a77c3566b5e96.mp3","text":"Hvilke vægtoplysninger skal du kunne finde på en registreringsattest?"},"v1-a04b8d0ab90b918f":{"src":"assets/voice/jeppe-neural-v1/v1-a04b8d0ab90b918f.mp3","text":"Ejeren eller brugeren svarer for lovlig stand; føreren svarer for sikker stand og forsvarlig trailerkobling."},"v1-9ed6eeae9b286a4f":{"src":"assets/voice/jeppe-neural-v1/v1-9ed6eeae9b286a4f.mp3","text":"Baneskift og sammenfletning ligner hinanden, men fordeler ansvaret forskelligt. Ved vognbaneskift. Den, der skifter vognbane, skal sikre, at det sker uden fare eller unødig ulempe. Brug spejle, blindvinkelkontrol og tegn, og bedøm både afstand og hastighed. Et blink skaber ikke et sikkert ophold. Ved sammenfletning. Når vognbaner uden vigepligtsmarkering løber sammen til én, skal trafikanterne gensidigt tilpasse fart og placering. Se langt frem, vælg et ophold tidligt og undgå at konkurrere om samme punkt på vejen. Læs afmærkningen. En punkteret linje mellem baner peger ofte på vognbaneskift; ophører linjen, kan der være sammenfletning. Hajtænder eller vigepligtstavle ændrer situationen igen. Afgør derfor manøvren ud fra den konkrete afmærkning, ikke vane."},"v1-9f5380ff39ffc3dd":{"src":"assets/voice/jeppe-neural-v1/v1-9f5380ff39ffc3dd.mp3","text":"Gearkassen tilpasser motorens rotation til den trækkraft og bevægelse, bilen har brug for. Gearkassen tilpasser rotationen. Gearkassen ændrer, hvordan motorens roterende bevægelse overføres til hjulene. I den enkle forklaring griber tandhjul i forskellige størrelser ind i hinanden. Føreren vælger gear i en manuel bil, mens en automatisk transmission foretager valget automatisk. Lave gear giver trækkraft. Lave gear passer til igangsætning, acceleration, langsom kørsel og stejle bakker, hvor bilen har brug for stor trækkraft. Det gælder både opad og nedad. Valget handler altså ikke kun om lav fart, men om den kraft og kontrol situationen kræver. Høje gear og bakgear. Højere gear bruges ved højere fart og kan skåne motoren samt begrænse brændstofforbruget i en forbrændingsbil. Bakgear sørger for bevægelse baglæns. Automatgear kan vise valgene på en anden måde, men føreren skal stadig forstå forskellen på fremad og bak."},"v1-a3f8af48e7d0cf95":{"src":"assets/voice/jeppe-neural-v1/v1-a3f8af48e7d0cf95.mp3","text":"De er minimum; alle læringsmål skal stadig nås, og kørelæreren kan kræve mere undervisning."},"v1-a0b90a91b136348f":{"src":"assets/voice/jeppe-neural-v1/v1-a0b90a91b136348f.mp3","text":"Fordi den forankørende kan køre for hurtigt, og lysene kan trække dit blik væk fra farer i dit eget synlige område."},"v1-a2fa185973b9a5bb":{"src":"assets/voice/jeppe-neural-v1/v1-a2fa185973b9a5bb.mp3","text":"Hjulene skal normalt følge rattets bevægelse straks. Forsinket reaktion kan vise slør, og væsentligt ratslør udløser krav om eftersyn."},"v1-a0a3959c9b6fda5a":{"src":"assets/voice/jeppe-neural-v1/v1-a0a3959c9b6fda5a.mp3","text":"Våd og glat vej. Regn, sne, is, grus og fedtet belægning kan reducere vejgrebet. Hastighed og afstand skal tilpasses, før grebet bliver kritisk. Pludselige rat- eller pedalbevægelser kan lettere udløse tab af vejgreb."},"v1-a53ee99b3f6043e9":{"src":"assets/voice/jeppe-neural-v1/v1-a53ee99b3f6043e9.mp3","text":"En utålmodig passager presser dig til at tage et lille hul i tæt trafik, fordi I er sent på den."},"v1-a65220143f3fb9f5":{"src":"assets/voice/jeppe-neural-v1/v1-a65220143f3fb9f5.mp3","text":"Du er ved at overhale en traktor, da en cyklist bliver synlig længere fremme i din tilbagevendingsbane."},"v1-a5c8a4f4fd3c006a":{"src":"assets/voice/jeppe-neural-v1/v1-a5c8a4f4fd3c006a.mp3","text":"Vending er en praktisk manøvre og skal øves på lukket øvelsesplads og i relevante trafiksituationer med kørelærer."},"v1-a5169b38312d20e2":{"src":"assets/voice/jeppe-neural-v1/v1-a5169b38312d20e2.mp3","text":"Sikker kørsel kræver, at føreren opdager, forstår og handler på tegn, før situationen bliver akut. At se er ikke det samme som at opdage. Øjnene kan være rettet mod vejen, uden at den relevante fare bliver bearbejdet. Søg systematisk efter ændringer, kanter, sideveje og mennesker, og spørg dig selv, hvad der kan bevæge sig ind i din bane. Fart forkorter beslutningen. Når farten stiger, tilbagelægges mere vej, mens føreren opdager, vurderer og reagerer. Tilpas derfor farten før komplekse steder, så observationerne kan omsættes til en rolig handling frem for en sen nødbeslutning. Forudseenhed bygger på tegn. En bold ved vejkanten, et åbent bildørshåndtag eller hjul, der drejer, kan varsle næste bevægelse. Brug sådanne tegn til at skabe plads og bremseberedskab, uden at antage at den varslede handling med sikkerhed sker."},"v1-a6ecd12e297a629b":{"src":"assets/voice/jeppe-neural-v1/v1-a6ecd12e297a629b.mp3","text":"ABS, ESC og airbag er alle udtrykkeligt med i kontrolområderne under 1.1.2.2."},"v1-a66cc6c733473e06":{"src":"assets/voice/jeppe-neural-v1/v1-a66cc6c733473e06.mp3","text":"Vejgreb og korrekt reaktion på glat føre skal opleves under fysisk køreundervisning, herunder på køreteknisk anlæg."},"v1-a6ca199576dc495e":{"src":"assets/voice/jeppe-neural-v1/v1-a6ca199576dc495e.mp3","text":"Vurder et tænkt karrosseriproblem. For hvert eksempel afgør du, hvilket princip der er berørt: en skarp løs pynteliste, en rustskade af sikkerhedsfarligt omfang eller en bagageklap, som ikke kan låses. Forklar den mulige fare frem for at diagnosticere en reparation."},"v1-a6dfd814eed0246d":{"src":"assets/voice/jeppe-neural-v1/v1-a6dfd814eed0246d.mp3","text":"Tohjulede kan være svære at bedømme, fordi deres smalle profil skjuler fart, afstand og placering. Smal profil giver usikker afstand. En motorcykel fylder lidt i synsfeltet, så ændringen i størrelse kan være sværere at aflæse end for en bil. Se flere gange med mellemrum, og vurder bevægelsen i forhold til faste punkter i omgivelserne. Hele kørebanen kan blive brugt. En motorcyklist kan ændre placering i banen for udsyn, vejgreb eller afstand til farer. Planlæg derfor ikke en passage ud fra, at motorcyklen bliver ved kantlinjen eller holder samme sideplacering. Genfind før du krydser banen. Ved venstresving skal en modkørende motorcykels fart og afstand vurderes med ekstra forsigtighed. Hvis observationerne ikke giver et sikkert hul, vent. En fejlvurdering placerer bilen direkte på tværs af motorcyklens kurs."},"v1-a803baebaf33f9f3":{"src":"assets/voice/jeppe-neural-v1/v1-a803baebaf33f9f3.mp3","text":"Dit bilsignal viser rødt, mens et hvidt X 19-signal giver letbanetoget passage."},"v1-a7caeb1298750ad0":{"src":"assets/voice/jeppe-neural-v1/v1-a7caeb1298750ad0.mp3","text":"Maksimal bremsning og forskelle i vejgreb skal erfares på godkendt køreteknisk anlæg med kørelærer."},"v1-a7ba3b7da58a8227":{"src":"assets/voice/jeppe-neural-v1/v1-a7ba3b7da58a8227.mp3","text":"Nej. Indtil 18 år gælder ordningen kun i Danmark, selv i tidsrummet for solokørsel."},"v1-a7976e7063be7df3":{"src":"assets/voice/jeppe-neural-v1/v1-a7976e7063be7df3.mp3","text":"Følg kraftvejen på en skitse. Peg på energikilden og forklar mundtligt vejen frem mod hjulene for henholdsvis en forbrændingsbil, en elbil og en hybrid. Brug biltype som første spørgsmål, så startmotor og kobling ikke fejlagtigt overføres til alle biler."},"v1-a9881e12044f6ad3":{"src":"assets/voice/jeppe-neural-v1/v1-a9881e12044f6ad3.mp3","text":"Fordi en cyklist kan være i et skjult område eller nå frem, mens døren åbnes; direkte kontrol og langsom åbning giver ny information."},"v1-a9292ee5277d6230":{"src":"assets/voice/jeppe-neural-v1/v1-a9292ee5277d6230.mp3","text":"Slå lampen op, afklar bilens tilstand, og sammenhold registreringsoplysningerne for bil, trailer og førerret før afgang. Så undgår du både at overse en teknisk fejl og at vælge en kombination, som bilen eller din førerret ikke dækker."},"v1-a89d83cff6245f95":{"src":"assets/voice/jeppe-neural-v1/v1-a89d83cff6245f95.mp3","text":"Styring og bremser. Bremsepedalen må ikke kunne trædes i bund ved hårdt tryk og må normalt ikke synke ved konstant tryk; pedalvandringen afhænger af bilfabrikatet. Bilen må ikke trække tydeligt til siden ved en normal opbremsning på jævn vej. Fejl i styretøj eller bremser skal undersøges, før bilen bruges videre."},"v1-a880f54410016602":{"src":"assets/voice/jeppe-neural-v1/v1-a880f54410016602.mp3","text":"Bremsekontrollen skal opdage afvigelser, før de bliver til manglende kontrol i trafikken. Pedalen giver information. Bremsepedalens modstand og vandring skal opleves som normal for bilen. En pedal, der synker ved vedvarende tryk eller føles markant anderledes, kan varsle en fejl. Undersøg afvigelsen, før bilen bruges i trafik. Retning under bremsning. Ved en forsigtig bremseprøve på et egnet sted skal bilen bevare en stabil retning. Trækker den tydeligt til en side, er bremsekraften muligvis ujævn. Det øger risikoen for at forlade sporet ved hårdere bremsning. Reagér før turen. En kontrollampe, unormal lyd eller ændret bremsevirkning skal ikke normaliseres, fordi bilen stadig kan standse. Sammenhold signalet med bilens betjeningsvejledning, og undlad videre kørsel, hvis bremsesikkerheden ikke kan fastslås før turen."},"v1-ab929b29d7fe91b8":{"src":"assets/voice/jeppe-neural-v1/v1-ab929b29d7fe91b8.mp3","text":"Fjernlys mindst 100 meter, nærlys mindst 30 meter uden at blænde og positionslys synligt på mindst 300 meter."},"v1-ab506bb609c94d57":{"src":"assets/voice/jeppe-neural-v1/v1-ab506bb609c94d57.mp3","text":"Gå tilbage til markeringerne og kontroller alle fire udsagn i hver, før du afslutter. Den digitale navigation giver mulighed for revision, men ikke ekstra tid efter prøvens afslutning."},"v1-ab1d2c9f5172e1a4":{"src":"assets/voice/jeppe-neural-v1/v1-ab1d2c9f5172e1a4.mp3","text":"Stands, orientér dig på ny, og korrigér eller afbryd manøvren, før bilen flyttes videre. Referencepunktet kan ikke erstatte synlig kontrol; når en forhindring forsvinder, er dens afstand blevet usikker."},"v1-abb3ec20c7d65e0a":{"src":"assets/voice/jeppe-neural-v1/v1-abb3ec20c7d65e0a.mp3","text":"Vent på et tydeligt sikkert hul og accepter forsinkelsen uden at diskutere beslutningen midt i manøvren. Passagerens tidspres ændrer ikke trafikkens bevægelser; sikkerhedsmarginen giver mulighed for at håndtere en andens uventede handling."},"v1-ae0352cbaded02ec":{"src":"assets/voice/jeppe-neural-v1/v1-ae0352cbaded02ec.mp3","text":"Planen siger udtrykkeligt, at de nævnte kategori B-køretøjer kan være omfattet af særlige regler om disse forhold."},"v1-ad56762aa2ba8bc1":{"src":"assets/voice/jeppe-neural-v1/v1-ad56762aa2ba8bc1.mp3","text":"Du skal have orienteret dig, og manøvren skal kunne ske uden fare eller unødig ulempe."},"v1-acc67cd0393f47c0":{"src":"assets/voice/jeppe-neural-v1/v1-acc67cd0393f47c0.mp3","text":"Døre og udstigning. Før en dør åbnes, skal fører og passagerer sikre sig, at ingen cyklist eller anden trafik udsættes for fare. Åbning af vogndøre samt af- og påstigning skal ske uden fare eller unødig ulempe. Efter parkering skal bilen sikres mod at sætte i gang og mod uberettiget brug."},"v1-adfdbd6c76ec6a41":{"src":"assets/voice/jeppe-neural-v1/v1-adfdbd6c76ec6a41.mp3","text":"Kørsel ved letbane. Letbanespor og tog kræver skærpet opmærksomhed, fordi et letbanetog har lang bremselængde og ikke kan undvige sporet. Føreren skal følge de signaler og tavler, der gælder for bilens kørselsretning, og må ikke forveksle dem med signaler for letbanen. Ved passage og sving over spor skal føreren kontrollere togets placering og sporets fortsatte forløb. Andre trafikanter kan overse biler, fordi deres opmærksomhed er rettet mod letbanen; hastighed og afstand skal tilpasses dette. Praktisk letbanekørsel indgår, når en lektion på mindst 45 minutter tillader kørsel til, ved og tilbage fra letbanen; ellers undervises de praktiske færdigheder i teorilokalet."},"v1-b0f1bc5c71a8e42f":{"src":"assets/voice/jeppe-neural-v1/v1-b0f1bc5c71a8e42f.mp3","text":"Dørlukning hører til 1.1.2.2, men omdrejningstælleren ligger i 1.1.2.1 og akustiske alarmer i 1.1.2.3."},"v1-ae4f4d42955e57cc":{"src":"assets/voice/jeppe-neural-v1/v1-ae4f4d42955e57cc.mp3","text":"Efter et mindre sammenstød holder begge biler midt i en mørk landevej, og ingen virker skadet."},"v1-af7ccc1b188d3b17":{"src":"assets/voice/jeppe-neural-v1/v1-af7ccc1b188d3b17.mp3","text":"Lad bilen stå, og få bremsesystemets tilstand afklaret, før du kører ud. Den ændrede pedalvandring kan være tegn på en fejl; en prøve i trafikken udsætter både dig og andre for en unødig risiko."},"v1-b0713c2545fcb51e":{"src":"assets/voice/jeppe-neural-v1/v1-b0713c2545fcb51e.mp3","text":"Ved sving krydser din bil ofte den linje, som cyklister og knallerter fortsætter i. Orientering i flere tempi. Se tidligt i spejle og blind vinkel før placering, og gentag kontrollen lige før svinget. En cyklist kan nå fra bag bilen til siden på få sekunder. Ét skulderblik langt fra krydset er derfor ikke nok. Placering uden fælde. Placér bilen tydeligt til højre før højresving, når forholdene tillader det, så der ikke skabes en farlig smal åbning. Er en cyklist allerede ved siden af, bliver du bagved og lader cyklisten fortsætte først. Dobbeltrettet cykelsti. En dobbeltrettet cykelsti kan sende cyklister mod din forventede retning. Se efter undertavle og kontroller begge retninger ved ind- og udkørsel. Hold tilbage, hvis svinget ellers tvinger cyklisten til at bremse eller standse."},"v1-b1de82e10dacf30e":{"src":"assets/voice/jeppe-neural-v1/v1-b1de82e10dacf30e.mp3","text":"Du vil sætte en passager af fire meter før et fodgængerfelt og regner med at holde under ét minut."},"v1-b11dac720ef05b59":{"src":"assets/voice/jeppe-neural-v1/v1-b11dac720ef05b59.mp3","text":"Med servoen aktiveret bevæges rattet, mens man ser, om forhjulene straks følger rattets bevægelse."},"v1-b12f6c9e636e14da":{"src":"assets/voice/jeppe-neural-v1/v1-b12f6c9e636e14da.mp3","text":"Juletræ vibes er ikke en lygtegodkendelse."},"v1-b17a542a9b6395b1":{"src":"assets/voice/jeppe-neural-v1/v1-b17a542a9b6395b1.mp3","text":"Det er tegn på en defekt bremsekreds. Bremserne skal straks efterses, og normal videre kørsel er ikke forsvarlig."},"v1-b2607c490be754f8":{"src":"assets/voice/jeppe-neural-v1/v1-b2607c490be754f8.mp3","text":"Den løse pynteliste har en skarp kant, som kan skade andre trafikanter."},"v1-b3507a1e812933fa":{"src":"assets/voice/jeppe-neural-v1/v1-b3507a1e812933fa.mp3","text":"De skal have set bilen, have givet plads, og ingen må kunne komme farligt nær bilen."},"v1-b34d7ee18ad30024":{"src":"assets/voice/jeppe-neural-v1/v1-b34d7ee18ad30024.mp3","text":"Sikkerhedsselens fastgørelsespunkter hører til 1.1.1.4, mens 1.1.1.3 også kræver gearplaceringerne og rattet."},"v1-b27dead84be67c86":{"src":"assets/voice/jeppe-neural-v1/v1-b27dead84be67c86.mp3","text":"Punkt 1.2.8.3 kræver låse, som kan holde døre, fronthjelm og bagageklap lukkede under kørsel."},"v1-b3c77c7ebf2d9052":{"src":"assets/voice/jeppe-neural-v1/v1-b3c77c7ebf2d9052.mp3","text":"Udsagnet beskriver et reelt problem, men det hører til skade- og rustkravet i 1.2.8.2."},"v1-b594e6d31ad1f15b":{"src":"assets/voice/jeppe-neural-v1/v1-b594e6d31ad1f15b.mp3","text":"Du vil dreje til venstre, men en modkørende motorcykel ses kortvarigt mellem biler, og dens fart er vanskelig at bedømme."},"v1-b625cf185e2ab9ed":{"src":"assets/voice/jeppe-neural-v1/v1-b625cf185e2ab9ed.mp3","text":"Om en trafikant kan nå ind i din planlagte bane, mens igangsætningen gennemføres."},"v1-b5d5df8d4816c344":{"src":"assets/voice/jeppe-neural-v1/v1-b5d5df8d4816c344.mp3","text":"I forbrændingsbilen driver batteriet hjulene gennem gear; i elbilen bruges batteriet kun under motorstart."},"v1-b8362fb9e8e82f00":{"src":"assets/voice/jeppe-neural-v1/v1-b8362fb9e8e82f00.mp3","text":"Stands, vurder og begræns ny fare, hjælp tilskadekomne, tilkald hjælp og opfyld oplysningspligterne."},"v1-b7a4412c45720b36":{"src":"assets/voice/jeppe-neural-v1/v1-b7a4412c45720b36.mp3","text":"Motoren tager omdrejninger uden tilsvarende fart, og gearskiftet er vanskeligt med kraftige mislyde. Hvilken fejlkobling følger Plan B?"},"v1-b8913e5986427030":{"src":"assets/voice/jeppe-neural-v1/v1-b8913e5986427030.mp3","text":"Sænk farten og hold tilbage efter den synlige vigepligtsafmærkning. Det defekte signal ophæver ikke B 11; tværtrafikken må ikke tvinges til at bremse."},"v1-b6c390cfb2425b25":{"src":"assets/voice/jeppe-neural-v1/v1-b6c390cfb2425b25.mp3","text":"Mere fart giver både mindre tid til at reagere og langt mere energi, der skal bremses væk. To strækninger. Standselængden består af reaktionsstrækning og bremselængde. Højere fart øger begge dele væsentligt: bilen kører længere, mens føreren reagerer, og bremserne skal fjerne mere bevægelsesenergi. Distraktion forlænger den første del yderligere. Firedoblet bremselængde. Når hastigheden fordobles under sammenlignelige forhold, bliver bremselængden omtrent firedoblet. Sammenhængen forklarer, hvorfor en beskeden fartreduktion før en kurve eller synlig risiko kan give en stor ekstra sikkerhedsmargin i praksis. Føre og bakke. Våd asfalt, grus, sne, is og nedkørsel øger bremselængden. Tilpas farten før underlaget eller bakken, og skab større afstand. ABS hjælper med hjulenes rotation, men ophæver ikke den begrænsede friktion."},"v1-bae73cf0ffd5ea0a":{"src":"assets/voice/jeppe-neural-v1/v1-bae73cf0ffd5ea0a.mp3","text":"Du opdager sent, at din frakørsel begynder nu, men en bil ligger i blind vinkel til højre."},"v1-b95d4f5c2a71b486":{"src":"assets/voice/jeppe-neural-v1/v1-b95d4f5c2a71b486.mp3","text":"Hvorfor er 30 teori- og 24 praktiklektioner ikke en automatisk færdigmelding?"},"v1-bb77f25bb75a6c59":{"src":"assets/voice/jeppe-neural-v1/v1-bb77f25bb75a6c59.mp3","text":"Det viser normalt, at blinklygterne lyser for kraftigt, selv om alle fortsat virker."},"v1-bbc74f7777b512a5":{"src":"assets/voice/jeppe-neural-v1/v1-bbc74f7777b512a5.mp3","text":"Fare, ulempe og hensyn. Alle trafikanter skal optræde hensynsfuldt og agtpågivende. Man må ikke skabe fare eller unødig ulempe for andre. Regler giver ikke ret til at fremtvinge en manøvre, hvis situationen er farlig."},"v1-bcb48bd1052162ee":{"src":"assets/voice/jeppe-neural-v1/v1-bcb48bd1052162ee.mp3","text":"Fordi fronten svinger ud til siden under drejningen og kan ramme noget, som ikke ligger bag bilen."},"v1-bcb50688002be2cc":{"src":"assets/voice/jeppe-neural-v1/v1-bcb50688002be2cc.mp3","text":"Navigationen mister ruten lige før et kompliceret kryds, og telefonen ligger løst på passagersædet."},"v1-bc655ca27024b711":{"src":"assets/voice/jeppe-neural-v1/v1-bc655ca27024b711.mp3","text":"Hvordan kan mange ture uden uheld gøre en dårlig vane mere risikabel?"},"v1-bc8789d002ad8d09":{"src":"assets/voice/jeppe-neural-v1/v1-bc8789d002ad8d09.mp3","text":"B 13 kræver fuld standsning ved stoplinjen; B 11 kræver kun standsning, når trafikken eller udsynet gør det nødvendigt."},"v1-bd09f51e3a1a775a":{"src":"assets/voice/jeppe-neural-v1/v1-bd09f51e3a1a775a.mp3","text":"Kontrollamper og dokumenter varierer mellem biler og skal gennemgås på det konkrete køretøj."},"v1-bd40d5f77d2bcd8d":{"src":"assets/voice/jeppe-neural-v1/v1-bd40d5f77d2bcd8d.mp3","text":"Motoren leverer kraft. Din selvtillid er ikke et brændstof."},"v1-bd27cd03517f6178":{"src":"assets/voice/jeppe-neural-v1/v1-bd27cd03517f6178.mp3","text":"Planen giver ikke en generel adgang til nødvendige ture; den eneste angivne fortsatte kørsel er til nærmeste værksted."},"v1-bdbb32a9328882e9":{"src":"assets/voice/jeppe-neural-v1/v1-bdbb32a9328882e9.mp3","text":"Den officielle teoriprøve tester anvendt regel- og risikoforståelse i 25 trafikale scenarier. Formatet. Kategori B-prøven viser 25 forskellige scenarier med fire svarmuligheder til hvert. Der er mindst ét korrekt svar og kan være flere. Opgaven er derfor at vurdere hvert udsagn selvstændigt, ikke at finde ét samlet svar. Tid og fejlgrænse. Både digital og analog kategori B-prøve varer 25 minutter, og højst fem fejl giver bestået. Brug tiden på fuld vurdering af alle udsagn; et ubesvaret valg kan ikke forventes at blive vurderet som korrekt. Prøven er én del. Køreprøven består af teori og en praktisk prøve. En bestået teoriprøve er gyldig i 18 måneder, men giver ikke i sig selv førerret. Uddannelsens praktiske mål og den praktiske prøve skal også gennemføres."},"v1-beec5efb6e67bf2a":{"src":"assets/voice/jeppe-neural-v1/v1-beec5efb6e67bf2a.mp3","text":"På anlægget kommer højre hjul over kanten ved for høj fart til en sikker tilbageføring."},"v1-c01443cf62e28200":{"src":"assets/voice/jeppe-neural-v1/v1-c01443cf62e28200.mp3","text":"Blikføring, ratgreb og samspil mellem hænderne skal trænes fysisk på lukket øvelsesplads."},"v1-c0442974c109bb50":{"src":"assets/voice/jeppe-neural-v1/v1-c0442974c109bb50.mp3","text":"Bilen skal være stabil, og hastigheden så lav, at tilbageføringen kan ske kontrolleret uden risiko."},"v1-bde966c68adeaccb":{"src":"assets/voice/jeppe-neural-v1/v1-bde966c68adeaccb.mp3","text":"Sænk farten, skab afstand til bussen og vær klar til at standse for en person, der kommer frem foran den. Den brede vej ændrer ikke, at bussen skjuler gående, som kan nå kørebanen med meget kort varsel."},"v1-c12a59589d33aea0":{"src":"assets/voice/jeppe-neural-v1/v1-c12a59589d33aea0.mp3","text":"Hvilke tre afstande knytter sig til fjernlys, nærlys og positionslys?"},"v1-c0b228a72f0a0447":{"src":"assets/voice/jeppe-neural-v1/v1-c0b228a72f0a0447.mp3","text":"Lave gear giver den ønskede trækkraft, høje gear bruges ved høj fart, og bakgear muliggør baglæns kørsel."},"v1-c1171a566af65f75":{"src":"assets/voice/jeppe-neural-v1/v1-c1171a566af65f75.mp3","text":"Sænk farten jævnt, øg afstanden, brug korrekt lys og undgå at følge den forankørendes tempo som målestok. Den anden førers valg udvider ikke dit udsyn; din fart skal give mulighed for at reagere på det, du selv kan opdage."},"v1-c13e48cee3da1595":{"src":"assets/voice/jeppe-neural-v1/v1-c13e48cee3da1595.mp3","text":"Stands ved din stoplinje og vent på signalet for bilens retning. Det særskilte hvide signal gælder ikke automatisk din bil, og toget kan ikke undvige sporet eller bremse som en personbil, hvis du kører frem."},"v1-c27a64b3f8f14efc":{"src":"assets/voice/jeppe-neural-v1/v1-c27a64b3f8f14efc.mp3","text":"Fordi der også skal være plads til at komme helt fri af sporet uden unødigt ophold."},"v1-c2b321b09675bf50":{"src":"assets/voice/jeppe-neural-v1/v1-c2b321b09675bf50.mp3","text":"Venteposition, udsyn og rømning ved signalskift skal øves i flere krydstyper med kørelærer."},"v1-c2d1e022f3e501db":{"src":"assets/voice/jeppe-neural-v1/v1-c2d1e022f3e501db.mp3","text":"Til- og frakørsel, afstand og baneskift skal gennemføres fysisk med kørelærer på motorvej eller relevant motortrafikvej."},"v1-c26681c9bc56e6d9":{"src":"assets/voice/jeppe-neural-v1/v1-c26681c9bc56e6d9.mp3","text":"Fordi bilens trækevne, faktisk belastning, kobling, registreringsdata og førerens kørekortret også indgår i den lovlige og sikre kombination."},"v1-c2e4aea560e448bc":{"src":"assets/voice/jeppe-neural-v1/v1-c2e4aea560e448bc.mp3","text":"Det viser kun hensigten; du skal stadig opdage og holde tilbage for trafikanter, hvis linje du krydser."},"v1-c3527c54b426bc8c":{"src":"assets/voice/jeppe-neural-v1/v1-c3527c54b426bc8c.mp3","text":"Kørelæreren beder dig skelne kontrollys i 1.1.2.2 fra målere i 1.1.2.1 og øvrige displayoplysninger i 1.1.2.3. Hvilken gruppe består kun af kontrollys fra 1.1.2.2?"},"v1-c37275f1e0d0c146":{"src":"assets/voice/jeppe-neural-v1/v1-c37275f1e0d0c146.mp3","text":"En fører planlægger én tur i Danmark og én tur til udlandet med påhængskøretøj. Hvilken sammenligning af registreringsattester følger Plan B?"},"v1-c4d3c6b437887180":{"src":"assets/voice/jeppe-neural-v1/v1-c4d3c6b437887180.mp3","text":"Kør ikke, før passende godkendt udstyr er monteret korrekt. Højden udløser som hovedregel krav om tilpasset sikkerhedsudstyr, og føreren har ansvaret. En løs sele over halsen giver ikke den beskyttelse, korrekt montering skal skabe."},"v1-c53e72a437979fa6":{"src":"assets/voice/jeppe-neural-v1/v1-c53e72a437979fa6.mp3","text":"Hvad bestemmer den sikre fart ud over tavlen?"},"v1-c52266f2ce53932c":{"src":"assets/voice/jeppe-neural-v1/v1-c52266f2ce53932c.mp3","text":"Hvad gør du først, hvis en assistent advarer, men årsagen ikke er tydelig?"},"v1-c4ddf6b03865d1c9":{"src":"assets/voice/jeppe-neural-v1/v1-c4ddf6b03865d1c9.mp3","text":"Hvorfor er farttilpasning før kurven vigtigere end en redningsmanøvre i kurven?"},"v1-c545df11e1eb296b":{"src":"assets/voice/jeppe-neural-v1/v1-c545df11e1eb296b.mp3","text":"Placering og fart. Man skal normalt holde så langt til højre som forholdene tillader. Den skiltede hastighed er en øvre grænse, ikke et mål under alle forhold. Hastigheden skal give mulighed for at standse for en påregnelig hindring."},"v1-c5f58df8a3c6b77c":{"src":"assets/voice/jeppe-neural-v1/v1-c5f58df8a3c6b77c.mp3","text":"Bilen må godt have personlighed. Skarpe kanter er ikke en personlighed."},"v1-c7aff0dee1ba91d8":{"src":"assets/voice/jeppe-neural-v1/v1-c7aff0dee1ba91d8.mp3","text":"Afstandsbedømmelse og møde skal trænes ved forskellige hastigheder og vejbredder med kørelærer."},"v1-c77506476463b704":{"src":"assets/voice/jeppe-neural-v1/v1-c77506476463b704.mp3","text":"Type og særkrav. Gennemgå med kørelæreren et konkret køretøjs type, relevante dokumenter og de regler, der gælder for typen. Peg på krav til mål, vægt, bremser, lygter, dæk, spejle, hjelm eller tilkobling, hvor de er relevante."},"v1-c7762554ae43c5ea":{"src":"assets/voice/jeppe-neural-v1/v1-c7762554ae43c5ea.mp3","text":"Advarsler og registreringsoplysninger hjælper føreren med at afgøre, om bilen passer til turen og må bruges sikkert. Advarsler kræver fortolkning. En kontrollampe fortæller, at et system kræver opmærksomhed, men farve og symbol har forskellig betydning fra bil til bil. Brug bilens vejledning, og skeln mellem information, snarlig kontrol og forhold, der kræver øjeblikkelig standsning. Lyd, lugt og røg er også signaler. Motorens tilstand aflæses ikke kun i instrumenthuset. Ny mekanisk støj, brændt lugt eller røg kan pege på en fejl, selv uden en lampe. Stands sikkert og undersøg situationen frem for at vente på et tydeligere svigt. Dokumentet sætter rammer. Registreringsattesten indeholder oplysninger om køretøjet, som er relevante ved blandt andet trailer og belastning. Sammenhold bilens og påhængskøretøjets data med opgaven og førerretten; udseendet alene fortæller ikke, hvad kombinationen må."},"v1-c920994c03b960ed":{"src":"assets/voice/jeppe-neural-v1/v1-c920994c03b960ed.mp3","text":"Hvornår begynder og slutter den lave promillegrænse?"},"v1-c8ebcfdb0be68092":{"src":"assets/voice/jeppe-neural-v1/v1-c8ebcfdb0be68092.mp3","text":"Det er normalt ved servostyring, hvis rattet ellers kan drejes uden mislyde ved lav fart."},"v1-ca12ab5d3421b79a":{"src":"assets/voice/jeppe-neural-v1/v1-ca12ab5d3421b79a.mp3","text":"For lidt servovæske kan give tung styring, men forsinket hjulreaktion er særskilt tegn på slør i styreforbindelserne."},"v1-c90a0047dd4f98c8":{"src":"assets/voice/jeppe-neural-v1/v1-c90a0047dd4f98c8.mp3","text":"En tynd film kan blive stærkt synshæmmende ved lav sol eller blændende lygter og i værste fald gøre udsynet umuligt."},"v1-ca483f2b6051e990":{"src":"assets/voice/jeppe-neural-v1/v1-ca483f2b6051e990.mp3","text":"På øvelsespladsen ser du konstant på kantlinjen tæt ved forhjulet, og bilen slingrer trods mange små rettelser."},"v1-cadd51e44b961e35":{"src":"assets/voice/jeppe-neural-v1/v1-cadd51e44b961e35.mp3","text":"Finder den gældende tavle eller vejafmærkning; uden sådan regulering følger du de almindelige vigepligtsregler."},"v1-cbdf1b3c58b2db59":{"src":"assets/voice/jeppe-neural-v1/v1-cbdf1b3c58b2db59.mp3","text":"I undervisningsbilen sidder gearvælgeren ved rattet, og parkeringsbremsen er en kontakt på midterkonsollen. Hvilken gruppe skal du kunne udpege under planpunkt 1.1.1.3?"},"v1-ca429c60b6b22ab9":{"src":"assets/voice/jeppe-neural-v1/v1-ca429c60b6b22ab9.mp3","text":"En 32-årig fik sit første B-kørekort for ét år siden og mener, at 0,2-reglen kun gælder unge."},"v1-cf0012232384b4b3":{"src":"assets/voice/jeppe-neural-v1/v1-cf0012232384b4b3.mp3","text":"Begge attester skal med ved kørsel med påhængskøretøj; Danmark tillader kopier, mens udlandet kræver originaler eller officiel genpart."},"v1-cda87bbcbba5a715":{"src":"assets/voice/jeppe-neural-v1/v1-cda87bbcbba5a715.mp3","text":"At sænke farten kan være forsigtigt, men ingen førerassistent overtager førerens ansvar for kørslen eller tavlefortolkningen."},"v1-ce407403cece3f58":{"src":"assets/voice/jeppe-neural-v1/v1-ce407403cece3f58.mp3","text":"ATV-typen kan have særregler om blandt andet mål, vægt, bremser, lygter, dæk, spejle og styrthjelm."},"v1-cf129a7972938695":{"src":"assets/voice/jeppe-neural-v1/v1-cf129a7972938695.mp3","text":"De gør det muligt at se, hvor hurtigt motorcyklens placering ændrer sig, i stedet for kun at vurdere dens lille silhuet."},"v1-cfb4aebba22a2a49":{"src":"assets/voice/jeppe-neural-v1/v1-cfb4aebba22a2a49.mp3","text":"På en bil med aktiveret servo følger forhjulene ikke straks en lille ratbevægelse. Hvilken vurdering gengiver Plan B?"},"v1-d006a1da2e7b0924":{"src":"assets/voice/jeppe-neural-v1/v1-d006a1da2e7b0924.mp3","text":"Bagageklappens lås kan ikke holde klappen lukket under kørslen."},"v1-d07688ba8ede12c8":{"src":"assets/voice/jeppe-neural-v1/v1-d07688ba8ede12c8.mp3","text":"Ubetinget vigepligt. Hajtænder og tavlen for ubetinget vigepligt kræver, at man holder tilbage for trafikken på den vej, man kører ind på. Man har også ubetinget vigepligt ved blandt andet udkørsel fra ejendom, parkeringsplads eller tankstation. Man skal vælge et ophold, så andre ikke tvinges til at bremse eller ændre placering."},"v1-d04b579d71f4621a":{"src":"assets/voice/jeppe-neural-v1/v1-d04b579d71f4621a.mp3","text":"Bremsernes funktion, kontrollamper og fysiske kontrol skal tilsammen afsløre fejl, før sikkerheden svigter. Tryk bliver til bremsekraft. Når pedalen trædes ned, skaber hovedcylinderen væsketryk, som føres gennem rør og slanger til hjulbremserne. Belægninger presses mod skiver eller tromler. En forstærker hjælper føreren; svigter den, kan fortsat kørsel være uforsvarlig og ulovlig. Kredse og nødbremse. Tokredsbremsen har to adskilte kredse. Hvis én bliver utæt, kan den anden yde nødbremsevirkning, men fortsat kørsel er uforsvarlig og ulovlig. Nødbremsen skal kunne bremse bilen sikkert, hvis driftsbremsen svigter under kørslen. ABS, assistent og ESC. Hjulfølere sender hjulenes omdrejninger til en elektronisk styreboks, som regulerer bremsetrykket og modvirker blokering. Reguleringen giver vibrationer i pedalen og muliggør i en vis udstrækning styring under bremsning. Bremseassistent hjælper ved kraftig opbremsning. Vedvarende ABS-lampe tillader kun kørsel til nærmeste værksted; konstant ESC-lampe kræver fabrikantens anvisning. Elbilens særlige bremser. One-pedal-funktion findes på elbiler og kan ofte slås til og fra. Når speederen løftes, aktiveres regenerativ bremsning, som samtidig lader batteriet. Er virkningen utilstrækkelig, skal bremsepedalen bruges. Elbilens bremser kræver mere vedligeholdelsesopmærksomhed for at bevare en effektiv funktion. Tre bremsekrav. Driftsbremsen skal virke på alle hjul og bremse sikkert, hurtigt og virksomt ved alle hastigheder og belastninger. Parkeringsbremsen skal holde bilen på hældende vej og kan være elektrisk. En hydraulisk driftsbremse kan være vakuum- eller elektrisk forstærket. Pedal og væske. Ved fysisk kontrol må bremsepedalen ikke gå i bund ved hårdt tryk eller normalt synke under et konstant tryk. Bremsevæsken skal stå mellem min- og maxmærket, eller den tilhørende kontrollampe skal være slukket. Pedalvandringen varierer mellem biler. Fejl mærkes i bilen. Skævtrækning, hug, ujævn bremsning eller pludseligt længere pedalvandring er fejltegn. Fugt efter bilvask kan kortvarigt påvirke belægningerne, men vedvarende afvigelser, for lidt væske eller en tændt bremselampe kræver straks eftersyn."},"v1-d173100a6eab8b03":{"src":"assets/voice/jeppe-neural-v1/v1-d173100a6eab8b03.mp3","text":"Blinklygterne blinker væsentligt hurtigere end sædvanligt. Hvad er dette normalt tegn på ifølge Plan B?"},"v1-d1f0884c7a85beab":{"src":"assets/voice/jeppe-neural-v1/v1-d1f0884c7a85beab.mp3","text":"Udsagnet beskriver et reelt problem, men det hører til kravet om skarpe eller udragende dele i 1.2.8.1."},"v1-d1ca351f008782dc":{"src":"assets/voice/jeppe-neural-v1/v1-d1ca351f008782dc.mp3","text":"De kan få føreren til at forveksle held med sikkerhed og gradvist acceptere mindre margin."},"v1-d0fc2a3ba6bd9532":{"src":"assets/voice/jeppe-neural-v1/v1-d0fc2a3ba6bd9532.mp3","text":"Kontrollér pedalvandring. I den holdende bil og efter kørelærerens anvisning: tryk hårdt på pedalen og hold derefter et konstant tryk. Vurder, om pedalen går i bund eller normalt synker under det konstante tryk. Kontrollér bremsevæske. Find med kørelæreren beholderens min- og maxmærker eller den relevante kontrollampe. Følg bilens løsning uden værktøj; den fysiske kontrol skal læres og vurderes på den konkrete bil."},"v1-d308c2a9b82d83c7":{"src":"assets/voice/jeppe-neural-v1/v1-d308c2a9b82d83c7.mp3","text":"Hvad skal du gøre ved ujævnt eller skævt dækslid, selv om mønsterdybden stadig er lovlig?"},"v1-d20d8f7e84b595c2":{"src":"assets/voice/jeppe-neural-v1/v1-d20d8f7e84b595c2.mp3","text":"Før afgang holder du et jævnt tryk på bremsepedalen, men pedalen fortsætter langsomt længere ned end normalt."},"v1-d4723109ae2ecb6f":{"src":"assets/voice/jeppe-neural-v1/v1-d4723109ae2ecb6f.mp3","text":"Systemet kan vise forkert; føreren vurderer tavlen og beholder ansvaret, også ved automatisk hastighedsændring."},"v1-d2f3f6dc0ac35c60":{"src":"assets/voice/jeppe-neural-v1/v1-d2f3f6dc0ac35c60.mp3","text":"Udrykning og fri passage. Trafikanter skal give fri passage for køretøjer under udrykning. Man skal handle roligt, orientere sig og undgå at skabe en ny farlig situation. Et rødt signal bliver ikke automatisk grønt, fordi en ambulance kommer bagfra."},"v1-d6ae40a63bf564ec":{"src":"assets/voice/jeppe-neural-v1/v1-d6ae40a63bf564ec.mp3","text":"En parkeret varebil spærrer din side af en smal vej, mens en bus nærmer sig modsat."},"v1-d63bdbf36165013b":{"src":"assets/voice/jeppe-neural-v1/v1-d63bdbf36165013b.mp3","text":"Begge tegn skyldes normalt for lidt kølervæske og skal derfor vurderes som en motorfejl."},"v1-d76ecc9263b80ba8":{"src":"assets/voice/jeppe-neural-v1/v1-d76ecc9263b80ba8.mp3","text":"Det skaber usikkerhed om placeringen og kræver ny orientering; det er ikke bevis for, at området er frit."},"v1-d69ef33e0b480d8a":{"src":"assets/voice/jeppe-neural-v1/v1-d69ef33e0b480d8a.mp3","text":"Bakning. Bakning må kun ske, når det kan udføres uden fare eller ulempe for andre. Føreren skal orientere sig hele vejen rundt og være særlig opmærksom på lave og små trafikanter. Bakkamera og sensorer er hjælpemidler og erstatter ikke direkte orientering."},"v1-d94c53637fbd0f18":{"src":"assets/voice/jeppe-neural-v1/v1-d94c53637fbd0f18.mp3","text":"Hvad ændrer en aktiv førerassistent ved førerens ansvar?"},"v1-d949b19d01854b14":{"src":"assets/voice/jeppe-neural-v1/v1-d949b19d01854b14.mp3","text":"Skævslid kræver kun dækombytning på akslen; fabrikantens dæktryk og øvrige mulige fejl er uden betydning."},"v1-d889900b8af1e328":{"src":"assets/voice/jeppe-neural-v1/v1-d889900b8af1e328.mp3","text":"Ubetinget vigepligt handler om virkningen på den trafik, du vil ind på eller krydse. Hvem holdes der tilbage for? Ved hajtænder eller B 11 skal du holde tilbage for al kørende trafik på den vej, du kører ind på eller over. Vælg et ophold, så de ikke tvinges til at bremse, undvige eller ændre placering. Vigepligt uden tavle. Ubetinget vigepligt kan følge af vejens udformning: udkørsel fra ejendom, parkeringsplads, tankstation, markvej eller over fortov, cykelsti eller hævet rabat. Se derfor på belægning og forløb, ikke kun efter en tavle. Fremkørsel i trin. Dårligt udsyn kan kræve langsom fremkørsel i flere trin. Vis tydeligt, at du vil holde tilbage, og stands om nødvendigt først ved hajtænderne og derefter igen nærmere skæringen, uden at spærre den trafik du skal vige for."},"v1-d7eb8293c0d6e990":{"src":"assets/voice/jeppe-neural-v1/v1-d7eb8293c0d6e990.mp3","text":"Læs og trailer ændrer bilens bevægelse, udsyn og lovlige rammer, før kombinationen overhovedet sættes i gang. Last skal blive, hvor den er placeret. Last, der kan forskyde sig ved sving eller bremsning, ændrer bilens balance og kan ramme personer eller vej. Fordel og fastgør lasten efter dens vægt og form, og kontrollér sikringen igen under en længere tur. Traileren følger en anden kurve. I et sving følger trailerens hjul ofte en snævrere linje end bilens. Giv ekstra plads ved hjørner og kantsten, og kontrollér spejlene gennem svinget, så du opdager en afvigelse, før den bliver fastlåst. Kombinationen skal passe sammen. Kontrollér registreringsoplysningerne for bil og trailer før afgang. Bilens tilladte påhængsvægt, trailerens tilladte totalvægt, den faktiske belastning og din førerret skal passe sammen; én tilladt værdi afgør ikke hele kombinationen. Selve koblingen og udstyret kontrolleres efter fabrikantens anvisninger."},"v1-dab42be3f75fedd4":{"src":"assets/voice/jeppe-neural-v1/v1-dab42be3f75fedd4.mp3","text":"Hvad sker der mellem stemplernes bevægelse og hjulenes bevægelse i en forbrændingsbil?"},"v1-d9a70e5813c6f920":{"src":"assets/voice/jeppe-neural-v1/v1-d9a70e5813c6f920.mp3","text":"Aktiveret servo er netop forudsætningen for ratslørskontrollen. Let styring uden mislyd ophæver ikke kravet om, at hjulene straks følger rattet."},"v1-da7072ef0671bb4f":{"src":"assets/voice/jeppe-neural-v1/v1-da7072ef0671bb4f.mp3","text":"Indplacering, orientering og udkørsel skal øves i rundkørsler med forskellig størrelse og cykelføring."},"v1-dae3076e4fc90088":{"src":"assets/voice/jeppe-neural-v1/v1-dae3076e4fc90088.mp3","text":"Alkohol og andre påvirkende stoffer svækker netop de evner, føreren bruger til at vurdere sin egen sikkerhed. Påvirkning og selvvurdering hænger dårligt sammen. Alkohol kan forringe opmærksomhed, reaktion og dømmekraft, samtidig med at føreren føler sig mere sikker. Planlæg derfor transporten før indtagelse i stedet for at lade en senere følelse afgøre, om bilen bruges. Lovgrænsen er ikke et personligt mål. Den almindelige grænse er overskredet, når alkoholkoncentrationen er over 0,50 promille i blodet eller over 0,25 milligram pr. liter udåndingsluft. I de første tre år efter førstegangserhvervelse af retten til kategori B gælder over 0,20 promille eller over 0,10 milligram pr. liter. Spirituskørsel kan også straffes under talgrænsen, hvis alkoholen hindrer betryggende kørsel. Andre stoffer kan også udelukke kørsel. Euforiserende stoffer og andre påvirkende midler kan gøre kørsel ulovlig eller uforsvarlig. Kombinationer og eftervirkning er ikke en situation, som bør testes bag rattet; vælg en transportform uden egen kørsel."},"v1-dc12a3d71acb670c":{"src":"assets/voice/jeppe-neural-v1/v1-dc12a3d71acb670c.mp3","text":"Gearkassen har en plan. “Jeg vibeser bare” er ikke et gear."},"v1-db9a855dfd54289e":{"src":"assets/voice/jeppe-neural-v1/v1-db9a855dfd54289e.mp3","text":"Tændingskontakten skal også udpeges, men den hører til 1.1.1.1; 1.1.1.3 kræver parkeringsbremsens betjening."},"v1-dd5bdf290d9eeaff":{"src":"assets/voice/jeppe-neural-v1/v1-dd5bdf290d9eeaff.mp3","text":"Våd eller glat vej reducerer den samlede reserve til at bremse, styre og ændre fart på samme tid. Vejgrebet er et fælles budget. Dækkene bruger vejgreb til både sideføring og bremsning. Kraftig opbremsning midt i et sving kræver begge dele samtidig. Sænk derfor farten før kurven, og udfør styring og fartændring så roligt som forholdene kræver. Tilpas før den glatte del. Broer, skyggepartier, blade, vand eller skiftende belægning kan ændre vejgrebet lokalt. Opdag tegnene tidligt, sænk farten og øg afstanden, mens bilen stadig har stabilt greb, frem for at reagere brat på området. Dækkene kan ikke ophæve forholdene. Korrekt dæktryk og tilstrækkeligt mønster støtter kontakten med vejen, men fjerner ikke risikoen ved vand, sne eller is. Føreren skal stadig tilpasse fart, afstand og bevægelser til den friktion, der faktisk er til rådighed."},"v1-dc16d7e8cc05d93a":{"src":"assets/voice/jeppe-neural-v1/v1-dc16d7e8cc05d93a.mp3","text":"Højre vigepligt gælder, når ingen anden regulering fordeler vigepligten i krydset. Udgangspunktet. Hvor ingen af parterne har ubetinget vigepligt, skal du som udgangspunkt holde tilbage for kørende fra højre. Kig efter tavler, hajtænder, belægningsskift og overkørsler først; de kan vise, at en anden regel gælder. Sne skjuler ikke reglen. Når vejafmærkningen er skjult af sne, bruges højre vigepligt, hvis ingen anden regulering kan genkendes. Sænk farten ekstra, fordi andre kan tolke krydset anderledes, og fordi bremselængden samtidig kan være større. Ikke ved baneskift. Højre vigepligt erstatter ikke reglerne om vognbaneskift eller sammenfletning. En bil i højre bane får ikke automatisk forrang, når baner føres sammen; afmærkningen og manøvrens art afgør, hvem der skal tilpasse sig."},"v1-dd870a6c7ac95736":{"src":"assets/voice/jeppe-neural-v1/v1-dd870a6c7ac95736.mp3","text":"Hvorfor giver et fast blik lige foran bilen ofte mere slingren?"},"v1-dd9f92113d138eab":{"src":"assets/voice/jeppe-neural-v1/v1-dd9f92113d138eab.mp3","text":"Hvad skal være opnået, før du styrer tilbage over kanten?"},"v1-dd84b140c6d33a0b":{"src":"assets/voice/jeppe-neural-v1/v1-dd84b140c6d33a0b.mp3","text":"Det gør gående og skjult bevægelse mere sandsynlig, så søgningen, farten og bremseberedskabet bør tilpasses før en konflikt opstår."},"v1-dd6f61066843420b":{"src":"assets/voice/jeppe-neural-v1/v1-dd6f61066843420b.mp3","text":"Afstand køber tid, mens lav fart og tydelig placering gør et vanskeligt møde løseligt. Afstand til forankørende. Hold så stor afstand, at du kan reagere, hvis den forankørende bremser pludseligt. Afstanden skal øges ved glat vej, dårlig sigt, tung last eller distraktionsrisiko, fordi både opdagelse og standsning kan tage længere tid. Møde på smal vej. Se tidligt efter indsnævringer, parkerede biler og bløde rabatter. Sænk farten før mødet og aftal forløbet gennem tydelig placering. Har du hindringen på din side, må du ofte vente, men sikkerheden gælder uanset retten. Store køretøjer. Busser og lastbiler kræver mere plads i sving og kan skabe lufttryk ved møde. Øg sideafstand og sænk farten, især på smal landevej. Undgå at bruge rabatten, hvis bæreevne eller høj kant er usikker."},"v1-e01b4e98be8355e4":{"src":"assets/voice/jeppe-neural-v1/v1-e01b4e98be8355e4.mp3","text":"Hvorfor kan en regelmæssigt korrekt manøvre stadig være forkert?"},"v1-ddf52ebe6ab2bd79":{"src":"assets/voice/jeppe-neural-v1/v1-ddf52ebe6ab2bd79.mp3","text":"Lastbiler og busser. Et langt køretøj kan bruge ekstra plads ved sving og kan komme tæt på kantstenen. Tunge køretøjer kan accelerere langsommere og kræver længere plads til visse manøvrer. Man bør undgå at opholde sig unødigt i områder, hvor den tunge fører kan have blindzone."},"v1-df7d064e624ee654":{"src":"assets/voice/jeppe-neural-v1/v1-df7d064e624ee654.mp3","text":"Kurver og bakker. Bakketoppe og skarpe kurver begrænser udsynet og kræver hastighedstilpasning før stedet. Man må ikke bygge en overhaling på gæt om, at vejen er fri bag toppen eller kurven. Lavt vejgreb øger risikoen, fordi både styring og bremsning bruger af det samme greb."},"v1-ddf54386d3239e80":{"src":"assets/voice/jeppe-neural-v1/v1-ddf54386d3239e80.mp3","text":"Distraktion kan flytte blik, hænder eller tanker væk fra den opgave, som trafiksituationen kræver nu. Opmærksomhed kan være væk med øjnene fremme. En samtale eller besked kan optage den mentale bearbejdning, selv når blikket peger mod vejen. Tegn kan blive set uden at blive forstået. Reducér sekundære opgaver, før trafikken bliver kompleks. Håndholdt udstyr er forbudt under kørsel. Færdselsloven forbyder føreren at benytte håndholdt teleudstyr og andre håndholdte kommunikationsapparater under kørsel. Håndfri betjening gør ikke automatisk enhver brug forsvarlig; den generelle pligt til opmærksom og hensynsfuld kørsel gælder stadig. Planlæg et sikkert stop. Hvis navigation, en besked eller en genstand kræver opmærksomhed, så find et lovligt sted og afslut kørslen, før udstyret betjenes håndholdt. Håndholdt brug er også ulovlig, mens du holder for rødt eller i kø, fordi du stadig anses for kørende."},"v1-e04d8a338e158c78":{"src":"assets/voice/jeppe-neural-v1/v1-e04d8a338e158c78.mp3","text":"Hvad betyder det, når en trafikant, du fulgte i spejlet, pludselig ikke længere kan ses?"},"v1-e0be9caa46c9f9d0":{"src":"assets/voice/jeppe-neural-v1/v1-e0be9caa46c9f9d0.mp3","text":"En bestemt ATV kan føres med kategori B. Hvilken konklusion om indretning og udstyr følger Plan B?"},"v1-e1a1160cb3a8566b":{"src":"assets/voice/jeppe-neural-v1/v1-e1a1160cb3a8566b.mp3","text":"Kørsel ved letbane er fysisk undervisning, når 45-minuttersbetingelsen kan opfyldes; ellers underviser kørelæreren i færdighederne i teorilokalet."},"v1-e149419fb2bdfd92":{"src":"assets/voice/jeppe-neural-v1/v1-e149419fb2bdfd92.mp3","text":"Indstilling og udsyn. Sæde, rat og spejle indstilles før kørslen, så føreren kan styre sikkert og orientere sig effektivt. Nakkestøtten skal passe til førerens højde og mindske risikoen for nakkeskade. Løse genstande kan flyve frem ved en hård opbremsning og bør sikres."},"v1-e2632e353c94c45a":{"src":"assets/voice/jeppe-neural-v1/v1-e2632e353c94c45a.mp3","text":"Kulilte er lugtfri og farlig selv i små mængder; en utæt udstødning eller åben bagklap kan føre den ind i kabinen."},"v1-e20a0a97a8a38071":{"src":"assets/voice/jeppe-neural-v1/v1-e20a0a97a8a38071.mp3","text":"Venstresving i kryds. Før venstresving skal føreren orientere sig bagud til venstre og efter modkørende, tværgående trafik og trafikanter på den vej, der svinges ind på. Tegn til venstre skal gives i god tid, og bilen placeres i den venstre del af egen kørselsretning eller i den anviste svingbane. Den venstresvingende skal holde tilbage for modkørende, der fortsætter ligeud eller svinger til højre. Svinget må ikke fuldføres, mens en foranholdende venstresvinger spærrer udsynet; efter frit udsyn og et tilstrækkeligt ophold afsluttes svinget uden unødigt ophold. Fodgængere samt cyklister og knallertkørere på den vej, der svinges ind på, skal om nødvendigt have plads først, og bilen føres ind i den korrekte bane."},"v1-e1e54ae45be56649":{"src":"assets/voice/jeppe-neural-v1/v1-e1e54ae45be56649.mp3","text":"Blik og ratføring skal arbejde sammen, så bilen følger den valgte linje uden sene, store korrektioner. Se mod den vej, du vil følge. Et blik tæt foran motorhjelmen opdager afvigelser sent og fremkalder mange små ratbevægelser. Flyt blikket længere frem langs den ønskede bane, og brug korte kontrolblik nær bilen, når afstand til kant eller forhindring skal vurderes. Rattet skal kunne korrigeres. Hold rattet, så begge hænder kan styre præcist og hurtigt uden at spænde kroppen. Lad hænderne samarbejde gennem svinget, og ret op i takt med bilens bevægelse frem for at slippe kontrollen brat. Lav fart giver læringstid. Ved grundmanøvrer skal farten være så lav, at du kan standse ved usikkerhed og nå at se virkningen af en ratbevægelse. Højere fart forstørrer en forkert kurs og reducerer tiden til at rette den."},"v1-e1afc45af44fb309":{"src":"assets/voice/jeppe-neural-v1/v1-e1afc45af44fb309.mp3","text":"Færdselsregler sætter rammer, men agtpågivenhed afgør, om handlingen faktisk er sikker. Fare og ulempe. Alle skal optræde hensynsfuldt og agtpågivende, så der ikke opstår fare eller skade, og så andre ikke unødigt hindres eller forstyrres. En lovlig placering kan derfor stadig være forkert, hvis den presser en sårbar trafikant. Ret er ikke fripas. At en anden har vigepligt, giver ikke ret til at fremtvinge passage. Tegn på fejl, usikkerhed eller manglende opmærksomhed skal udløse mere afstand og lavere fart. Målet er at undgå sammenstødet, ikke at bevise reglen. Sikkerhedsmargin. Planlæg med plads til, at andre kan reagere sent eller forkert. En sikkerhedsmargin består af tid, afstand og en mulig flugtvej. Jo dårligere udsyn eller vejgreb, desto større margin bør du skabe før manøvren."},"v1-e4dbd8eef342d9f3":{"src":"assets/voice/jeppe-neural-v1/v1-e4dbd8eef342d9f3.mp3","text":"Hvorfor er det bedre at reducere farten før en glat kurve end midt i den?"},"v1-e50e614f6c22bb33":{"src":"assets/voice/jeppe-neural-v1/v1-e50e614f6c22bb33.mp3","text":"Hvornår skal afstanden til den forankørende øges?"},"v1-e4d4e8204d6c9f3b":{"src":"assets/voice/jeppe-neural-v1/v1-e4d4e8204d6c9f3b.mp3","text":"Start umiddelbart før afgang, undgå længere tomgang, accelerér kvikt med cirka halv speeder, skift tidligt højt og tilpas farten før signalet."},"v1-e54c47883ab9a77d":{"src":"assets/voice/jeppe-neural-v1/v1-e54c47883ab9a77d.mp3","text":"Når anvisninger strider mod hinanden, skal du først afgøre, hvilken der står højest. Rækkefølgen. En politibetjents anvisning går foran signaler, tavler, vejafmærkning og almindelige regler. Et fungerende lyssignal går foran modstridende vigepligtstavler. Rækkefølgen forhindrer i praksis, at to samtidige beskeder styrer samme bevægelse forskelligt. Når signalet svigter. Et slukket eller tydeligt defekt lyssignal giver ikke fri bane. Se efter tavler og hajtænder; findes ingen vigepligtsafmærkning, bruges de almindelige regler, typisk højre vigepligt. Sænk farten, fordi andre kan være i tvivl. Grønt er betinget. Grønt betyder kør, hvis vejen er fri. Du må ikke køre ind, hvis køen forhindrer dig i at komme ud før tværtrafikken får grønt. Signalet løser altså vigepligten, men ikke risikoen for at blokere krydset."},"v1-e62279efc0225883":{"src":"assets/voice/jeppe-neural-v1/v1-e62279efc0225883.mp3","text":"På en aftentur opdager du, at du har overset to vejvisninger og har svært ved at fastholde opmærksomheden."},"v1-e60dcc357f45dda9":{"src":"assets/voice/jeppe-neural-v1/v1-e60dcc357f45dda9.mp3","text":"Eleven skal kunne aflæse og forstå systemerne i undervisningsbilen. En eventuel demonstration skal følge kørelærerens og fabrikantens anvisninger og må aldrig fremprovokeres ved at skabe en faresituation."},"v1-e58353d17465a565":{"src":"assets/voice/jeppe-neural-v1/v1-e58353d17465a565.mp3","text":"Blindzoner. Spejle viser ikke nødvendigvis hele området ved siden af og bag bilen. Et kort skulderblik kan være nødvendigt før vognbaneskift eller sving. Store køretøjer har store områder, hvor føreren kan have svært ved at se andre."},"v1-e61dce7b221063b5":{"src":"assets/voice/jeppe-neural-v1/v1-e61dce7b221063b5.mp3","text":"En parkeringsmanøvre bliver overskuelig, når den deles i langsomme observationer, referencepunkter og kontrollerede korrektioner. Vælg plads før du styrer. Vurder pladsens længde, bredde, adgang og trafikken omkring den, før manøvren begynder. Et lovligt felt er ikke nødvendigvis let at nå sikkert. Vælg en anden plads, hvis udsyn eller arbejdsrum ikke passer til dine færdigheder. Brug referencepunkter som kontrol. Et spejlpunkt eller en linje i ruden kan hjælpe med afstand, men virker kun fra en fast siddestilling og for den konkrete bil. Bekræft placeringen ved at se flere steder og korrigér, hvis virkeligheden ikke passer til referencepunktet. Slutplaceringen skal være brugbar. På øvelsespladsen skal bilen blandt andet kunne placeres parallelt med kanten med højre hjulpar højst 20 cm fra den. Målet træner præcision, men føreren skal samtidig bevare observation og mulighed for at standse."},"v1-e72f1fec21a9634a":{"src":"assets/voice/jeppe-neural-v1/v1-e72f1fec21a9634a.mp3","text":"Hvorfor skal ruder rengøres indvendigt, selv når de ser acceptable ud i gråvejr?"},"v1-e70d179b827092c6":{"src":"assets/voice/jeppe-neural-v1/v1-e70d179b827092c6.mp3","text":"Et barn på 128 cm sidder med voksenbæltet løst over halsen, fordi selepuden ligger i bagagerummet."},"v1-e69aab507eb7e7d0":{"src":"assets/voice/jeppe-neural-v1/v1-e69aab507eb7e7d0.mp3","text":"Aflæs undervisningsbilens instrumenter. I den standsede undervisningsbil gennemgår du sammen med kørelæreren speedometer, eventuelle øvrige målere samt de kontrollys, displaybeskeder og lydalarmer, bilen kan vise. Du forklarer betydning og nødvendig reaktion."},"v1-e74bed403a75209e":{"src":"assets/voice/jeppe-neural-v1/v1-e74bed403a75209e.mp3","text":"Gennemgå undervisningsbilens assistenter. I den standsede undervisningsbil åbner kørelæreren bilens relevante visninger og gennemgår hvert installeret førerassistentsystem. Du aflæser symboler og status, forklarer advarsler og beskriver, hvordan føreren skal reagere. Kobl signal til system uden at aktivere kørsel. Med kørelæreren matcher du bilens egne symboler og indstillinger til de systemtyper, bilen faktisk har. I taler også om systemer, bilen ikke har, så fravær ikke forveksles med fejl. Øvelsen udføres uden at fremkalde farlige situationer."},"v1-e8c7746a92361b3a":{"src":"assets/voice/jeppe-neural-v1/v1-e8c7746a92361b3a.mp3","text":"Planen kræver pedalen i bund under gearskift og langsom opløftning; halv nedtrædning og hurtig opløftning matcher ikke funktionen."},"v1-e97d923483c7d6b1":{"src":"assets/voice/jeppe-neural-v1/v1-e97d923483c7d6b1.mp3","text":"Udstødningsfejl forbindes med unormal støj ved gasgivning, og batterikapacitet med rækkevidde; ingen af dem matcher de beskrevne tegn."},"v1-e83cfe6f377294fa":{"src":"assets/voice/jeppe-neural-v1/v1-e83cfe6f377294fa.mp3","text":"To små veje krydser uden tavler eller hajtænder. En bil nærmer sig fra din højre side med samme fart."},"v1-e7fbc7ce71a0ac1f":{"src":"assets/voice/jeppe-neural-v1/v1-e7fbc7ce71a0ac1f.mp3","text":"Overhaling. Overhaling kræver frit udsyn, tilstrækkelig plads og sikker tilbagevenden. Man må ikke begynde, hvis en bagvedkørende allerede er ved at overhale. Hvis forholdene ændrer sig, skal man kunne afbryde uden at presse andre."},"v1-eb92de894d4e8e6f":{"src":"assets/voice/jeppe-neural-v1/v1-eb92de894d4e8e6f.mp3","text":"Hvem har ansvaret for en 14-årigs selebrug under kørslen?"},"v1-eae3d43272411153":{"src":"assets/voice/jeppe-neural-v1/v1-eae3d43272411153.mp3","text":"Sprinklervæsken skal være tilstrækkelig, viskerne skal kunne holde ruden ren, og filmen bør fjernes på grund af modlys."},"v1-ea143e000cb31b33":{"src":"assets/voice/jeppe-neural-v1/v1-ea143e000cb31b33.mp3","text":"Reducer kravene til dækkene med rolig styring og kontrolleret fartreduktion. Samtidig maksimal styring og bremsning kan overskride det begrænsede vejgreb, især på den våde overflade; lavere fart før kurven ville have bevaret mere reserve."},"v1-eb479ac4b733431f":{"src":"assets/voice/jeppe-neural-v1/v1-eb479ac4b733431f.mp3","text":"Førerassistenter kan varsle og støtte, men føreren skal stadig forstå situationen og vælge den sikre handling. Støtte er ikke overtagelse. En assistent reagerer på de oplysninger, dens sensorer og data kan registrere. Afmærkning, vejarbejde, snavs eller usædvanlige forløb kan begrænse hjælpen. Hold derfor selv øje med vej, færdsel og tegn, også når systemet er aktivt. Kontrollér signalet. En advarsel er en anledning til at undersøge situationen, ikke til en automatisk bevægelse med rat eller pedaler. Se, hvad der udløste signalet, orientér dig omkring bilen, og reagér kun på en måde, der passer til den faktiske trafik. Når vej og skærm er uenige. Et kort eller en hastighedsvisning kan være forældet eller have aflæst et tegn forkert. Synlig, gældende regulering og de aktuelle forhold skal styre kørslen. Usikkerhed bør føre til mere observation og en forsigtig tilpasning."},"v1-ebe8db8fa4888b23":{"src":"assets/voice/jeppe-neural-v1/v1-ebe8db8fa4888b23.mp3","text":"Hvordan ved du, at et ophold er stort nok?"},"v1-ed3b5abccada5d79":{"src":"assets/voice/jeppe-neural-v1/v1-ed3b5abccada5d79.mp3","text":"Fart og samspil i trafiksanerede områder skal trænes med kørelærer under respekt for lokale adgangsregler."},"v1-ece4a8b5082eb851":{"src":"assets/voice/jeppe-neural-v1/v1-ece4a8b5082eb851.mp3","text":"Fordi kursafvigelser opdages sent, så føreren reagerer med hyppige og større korrektioner."},"v1-ed5eb2a418d754b0":{"src":"assets/voice/jeppe-neural-v1/v1-ed5eb2a418d754b0.mp3","text":"Høj vejkant. Hvis hjulene kommer ud over en høj vejkant, kan en brat tilbageføring ved høj fart få føreren til at miste kontrollen. Føreren skal først holde rattet roligt og styre bilen langs kanten uden pludselige bevægelser. Hastigheden reduceres forsigtigt, mens bilen holdes stabil langs kanten. Bilen styres først tilbage over kanten, når hastigheden er så lav, at manøvren kan gennemføres kontrolleret. Situationen kan opstå ved både højre og venstre vejkant; øvelsen trænes på køreteknisk anlæg med kørelærer og må ikke selvafprøves på offentlig vej."},"v1-edb2c2bdc43d2185":{"src":"assets/voice/jeppe-neural-v1/v1-edb2c2bdc43d2185.mp3","text":"Hvorfor er det utilstrækkeligt kun at kontrollere, om bilen kan standse ved lav fart?"},"v1-edc2edc932c60fef":{"src":"assets/voice/jeppe-neural-v1/v1-edc2edc932c60fef.mp3","text":"Du overtager en delebil, hvor sædet står langt tilbage, og sidespejlene viser mest af bilens egne sider."},"v1-edb13e2de8745a65":{"src":"assets/voice/jeppe-neural-v1/v1-edb13e2de8745a65.mp3","text":"Afmærkning, spejlsekvens og valg af ophold skal trænes i virkelige bane- og fletteforløb med kørelærer."},"v1-edc8076ff2583fef":{"src":"assets/voice/jeppe-neural-v1/v1-edc8076ff2583fef.mp3","text":"En langsom traktor kører foran dig lige før en bakketop, og der er ingen synlig modkørende."},"v1-f02688822b94b18c":{"src":"assets/voice/jeppe-neural-v1/v1-f02688822b94b18c.mp3","text":"Kontrollys for ABS, ESC og airbag."},"v1-edd4c19a4caa8578":{"src":"assets/voice/jeppe-neural-v1/v1-edd4c19a4caa8578.mp3","text":"Hvilke tre betingelser skal være opfyldt før du passerer legende børn?"},"v1-ee8e9e810c0eaa81":{"src":"assets/voice/jeppe-neural-v1/v1-ee8e9e810c0eaa81.mp3","text":"Hvorfor gør et ophold under tre minutter ikke altid stedet lovligt?"},"v1-ef9c62a9815eb543":{"src":"assets/voice/jeppe-neural-v1/v1-ef9c62a9815eb543.mp3","text":"Energi- og miljørigtig kørsel. Jævn kørsel og færre unødvendige hastighedsændringer reducerer energiforbruget. For lavt dæktryk, unødig vægt og tagboks kan øge energiforbruget. Miljøhensyn må aldrig føre til, at sikker acceleration eller bremsning undlades."},"v1-f0a111357595bf30":{"src":"assets/voice/jeppe-neural-v1/v1-f0a111357595bf30.mp3","text":"Føreren skal opdage og reagere på, at bilen ikke længere er sikkerhedsmæssigt forsvarlig, selv om ejeren har ansvaret for den lovlige stand."},"v1-f1d2cc9f6444658a":{"src":"assets/voice/jeppe-neural-v1/v1-f1d2cc9f6444658a.mp3","text":"Nedtrædning afbryder forbindelsen i stedet for at forstærke den, og bevægelsen overføres først blødt, når pedalen løftes langsomt."},"v1-f1c0ad0a750a195d":{"src":"assets/voice/jeppe-neural-v1/v1-f1c0ad0a750a195d.mp3","text":"Den forudser trafikken og undgår unødige ændringer, men udfører nødvendige accelerationer og bremsninger sikkert og beslutsomt."},"v1-f2dbe1836dca5347":{"src":"assets/voice/jeppe-neural-v1/v1-f2dbe1836dca5347.mp3","text":"Placering og fart skal give udsyn, plads og mulighed for at standse før det forventelige. Hold til højre med mening. Hold normalt så langt til højre, som vej, føre og øvrig trafik tillader. Kør ikke så tæt på kant, parkerede biler eller cyklister, at sikkerhedsmarginen forsvinder. Placeringen skal også give udsyn gennem kurver og over bakker. Maksimum er ikke målfart. Den skiltede grænse er et loft under gode forhold. Mørke, regn, børn ved vejen, en skarp kurve eller begrænset udsyn kan kræve lavere fart. Tilpasningen skal ske før risikoen, ikke midt i den. Stands på den synlige strækning. Vælg fart, så du kan standse for en hindring, der med rimelighed kan forventes. Når udsynet halveres af tåge eller bakketop, skal din mulige standsestrækning også passe til den kortere synlige vej."},"v1-f3ef90a930ccffcf":{"src":"assets/voice/jeppe-neural-v1/v1-f3ef90a930ccffcf.mp3","text":"Regnen tiltager før en kurve, og vand samler sig i sporene, mens bilen foran sænker farten."},"v1-f2f951d411ce722f":{"src":"assets/voice/jeppe-neural-v1/v1-f2f951d411ce722f.mp3","text":"Du er på vej ud af rundkørslen. En gående nærmer sig feltet, og en cyklist fortsætter på stien rundt om rundkørslen."},"v1-f2dc46a61f75cf61":{"src":"assets/voice/jeppe-neural-v1/v1-f2dc46a61f75cf61.mp3","text":"Fordi sikker kørsel også kræver, at tegn, risici og ændringer opdages og bearbejdes i tide."},"v1-f2f233e34caddca9":{"src":"assets/voice/jeppe-neural-v1/v1-f2f233e34caddca9.mp3","text":"I trafiksanerede områder er bilen gæst, og den laveste relevante fart kan være langt under tavlens tal. Ophold og leg. I opholds- og legeområde er kørende færdsel underordnet. Kør normalt under 15 km/t, hold tilbage for gående, og fortsæt først når de har set bilen, givet plads og ingen kan komme farligt nær den. Gågade og cykelgade. I gågade skal tilladt bilkørsel ske med særlig hensyn til gående og meget lav fart. I cykelgade skal bilisten tilpasse sig cyklisterne og må ikke unødigt hindre andre kørende. Undertavlen afgør, om bilkørsel er tilladt. Udgang og parkering. Parkering i gågade, cykelgade og opholds- og legeområde må ikke ske uden for afmærkede pladser. Ved udkørsel fra områderne har den kørende ubetinget vigepligt. Se derfor efter cyklister og gående før vejens øvrige trafik."},"v1-f473cb22c6fedcdd":{"src":"assets/voice/jeppe-neural-v1/v1-f473cb22c6fedcdd.mp3","text":"Hvad betyder det, at bremsning og styring deler vejgrebet?"},"v1-f5d309b93b9a983f":{"src":"assets/voice/jeppe-neural-v1/v1-f5d309b93b9a983f.mp3","text":"Efter en fest siger en ven, at du virker upåvirket, og foreslår, at du kører den korte vej hjem."},"v1-f47873b2c181d9a3":{"src":"assets/voice/jeppe-neural-v1/v1-f47873b2c181d9a3.mp3","text":"Kontrollér ratslør. På en holdende bil og efter kørelærerens anvisning: aktivér eventuel servo, bevæg rattet lidt, og se udefra om forhjulene straks følger rattets bevægelse. Kontrollér servosystemet. Find med kørelæreren bilens relevante servokontrol: væskebeholder med min- og maxmærke eller kontrollampe efter fabrikantens forskrift. Metoden afhænger af bilen, og den fysiske udførelse vurderes ved bilen."},"v1-f57f27f241db6377":{"src":"assets/voice/jeppe-neural-v1/v1-f57f27f241db6377.mp3","text":"Tegn skal gøre din hensigt forståelig uden at love, at manøvren allerede kan gennemføres. Tegn før handling. Blink i passende afstand, så andre kan forstå og bruge informationen. Et meget sent tegn giver ingen planlægningstid; et for tidligt tegn kan forveksles med en anden vej. Kontroller stadig spejle og blind vinkel før retningen ændres. Blink giver ingen ret. Blinklyset fortæller om en hensigt, men flytter ikke vigepligten. Ved vognbaneskift skal du stadig sikre, at manøvren kan ske uden fare eller unødig ulempe. Vent, hvis trafikken i den nye bane ikke giver plads. Signal kun ved behov. Horn og blink med forlygterne er advarselssignaler, ikke middel til at kræve plads eller udtrykke irritation. Brug signalet kort, når det er nødvendigt for at afværge fare; kombiner det med fartnedsættelse og sikker placering."},"v1-f6003899c0098751":{"src":"assets/voice/jeppe-neural-v1/v1-f6003899c0098751.mp3","text":"Udsyn er en feature. En fedtet forrude er et nerf."},"v1-f67d2da548711e7e":{"src":"assets/voice/jeppe-neural-v1/v1-f67d2da548711e7e.mp3","text":"Omdrejningstæller, dørlukning og en relevant akustisk alarm."},"v1-f64f9b754388edfc":{"src":"assets/voice/jeppe-neural-v1/v1-f64f9b754388edfc.mp3","text":"Bliv roligt holdende og undgå at køre over stoplinjen. Ambulancen har allerede en sikker vej; en ulovlig fremkørsel kan skabe krydsende fare."},"v1-f6e0d4c6e6419663":{"src":"assets/voice/jeppe-neural-v1/v1-f6e0d4c6e6419663.mp3","text":"Cykler og små køretøjer. Cykler, elcykler og små motoriserede køretøjer kan nærme sig hurtigere end forventet. De kan være skjult af parkerede biler, stolper og bilens egne spejle. Ved sving skal føreren orientere sig efter cyklister både før og under manøvren."},"v1-fa7e72d8a6a10bf8":{"src":"assets/voice/jeppe-neural-v1/v1-fa7e72d8a6a10bf8.mp3","text":"Planen forbyder al egen kørsel og kræver transport af bilen direkte til et værksted."},"v1-fa72687cf530a813":{"src":"assets/voice/jeppe-neural-v1/v1-fa72687cf530a813.mp3","text":"Bliv bag lastbilen og uden for svingområdet, indtil køretøjet har afsluttet manøvren. Pladsen kan være nødvendig for lastbilens sving, mens baghjulene bevæger sig ind over området på højre side."},"v1-f883772701c022ef":{"src":"assets/voice/jeppe-neural-v1/v1-f883772701c022ef.mp3","text":"Du kører fra en tankstation over et fortov. Ingen hajtænder eller tavle er synlige, og en cyklist kommer fra venstre."},"v1-f8c54b1d5389e59e":{"src":"assets/voice/jeppe-neural-v1/v1-f8c54b1d5389e59e.mp3","text":"Energirigtig kørsel virker bedst, når den bygger på forudseenhed og aldrig reducerer sikkerhedsmarginen. Se langt frem. Forudseende kørsel begrænser unødvendig acceleration og bremsning. Hold afstand, slip speederen tidligt og bevar en jævn fart, når trafikken tillader det. Det sænker forbruget og giver samtidig mere tid til at reagere. Bilens modstand. For lavt dæktryk, unødig last og tagudstyr øger rulle- eller luftmodstanden. Kontroller dæktryk efter bilens anvisning og fjern udstyr, der ikke bruges. Energibesparelsen må ikke ske ved ulovligt eller usikkert dæktryk. Sikkerhed først. Undlad aldrig nødvendig acceleration ved indkørsel eller kraftig bremsning i fare for at spare energi. Miljøkørsel handler om at undgå unødige ændringer, ikke om at gøre nødvendige manøvrer langsomme eller tøvende."},"v1-fb724d8a0d623e3e":{"src":"assets/voice/jeppe-neural-v1/v1-fb724d8a0d623e3e.mp3","text":"Hvorfor bliver en lille fartreduktion mere værdifuld end tallet antyder?"},"v1-fab378e3ffc5590f":{"src":"assets/voice/jeppe-neural-v1/v1-fab378e3ffc5590f.mp3","text":"Føreren har ansvaret for passagerer under 15 år."},"v1-fb41a78f4538ff34":{"src":"assets/voice/jeppe-neural-v1/v1-fb41a78f4538ff34.mp3","text":"Øvelsen kræver fysisk instruktion på køreteknisk anlæg og må ikke selvafprøves på offentlig vej."},"v1-fbd9cab7def7ba3f":{"src":"assets/voice/jeppe-neural-v1/v1-fbd9cab7def7ba3f.mp3","text":"Det er normalt en selvtest, som viser, at alle blinklygter og havariblink virker korrekt."},"v1-fc1dab2db8f2d2df":{"src":"assets/voice/jeppe-neural-v1/v1-fc1dab2db8f2d2df.mp3","text":"Hvornår er et lavere gear typisk relevant?"},"v1-fca9e3f15fa466a7":{"src":"assets/voice/jeppe-neural-v1/v1-fca9e3f15fa466a7.mp3","text":"Bliv holdende, indstil sæde og ryglæn, og indstil derefter spejlene fra din endelige position. Så kan du nå betjeningen sikkert og stole på, at spejlbilledet passer til den stilling, du faktisk kører i."},"v1-fc6720d236afc46e":{"src":"assets/voice/jeppe-neural-v1/v1-fc6720d236afc46e.mp3","text":"Praktisk tunnelkørsel er kun obligatorisk, når en lektion på mindst 45 minutter tillader turen til, gennem og tilbage fra en angivet tunnel; ellers undervises færdighederne i teorilokalet. Her dokumenteres heller ingen praktisk passage af jernbaneoverkørsel."},"v1-fc525fd632a2c4ce":{"src":"assets/voice/jeppe-neural-v1/v1-fc525fd632a2c4ce.mp3","text":"Når hjulene er kommet ud over en høj kant, er en langsom genopretning sikrere end et hurtigt ryk tilbage. Den farlige refleks. Et kraftigt ratudslag tilbage mod vejen ved høj fart kan få hjulene til pludseligt at gribe kanten og sende bilen ukontrolleret over kørebanen. Modstå derfor refleksen til straks at tvinge bilen op. Stabiliser og sænk farten. Styr roligt lige frem langs kanten og brems forsigtigt. Målet er først at stabilisere bilen og reducere hastigheden, ikke at komme tilbage øjeblikkeligt. Kontroller samtidig den øvrige trafik, hvis situationen sker i virkeligheden. Tilbage ved lav fart. Styr først kontrolleret op over kanten, når hastigheden er så lav, at det kan ske uden risiko. Planen lader eleven erfare forløbet flere gange og om muligt med kanten i både højre og venstre side."},"v1-fcdb6be27080bd4c":{"src":"assets/voice/jeppe-neural-v1/v1-fcdb6be27080bd4c.mp3","text":"Fordi tilladte vægte og kombinationer følger registrerede oplysninger og førerret, ikke et visuelt skøn."},"v1-fcbe1ab26fd0bd86":{"src":"assets/voice/jeppe-neural-v1/v1-fcbe1ab26fd0bd86.mp3","text":"Den indvendige film er kun relevant ved rudeskade; rene spejle kan ellers erstatte en ren forrude."},"v1-fcdb25d356348a2a":{"src":"assets/voice/jeppe-neural-v1/v1-fcdb25d356348a2a.mp3","text":"Dækkenes vejgreb er en begrænset ressource, som bremsning og styring skal dele. Friktionens budget. Dækket kan kun overføre en begrænset samlet kraft. Hård bremsning samtidig med kraftig styring kan overskride grebet, især på glat vej. Reducer derfor fart før kurven og gør styringen jævn. ABS ved hård bremsning. I en bil med ABS skal bremsepedalen ved maksimal bremsning trædes helt ned og holdes nede. Vibrationer i pedalen kan være systemets regulering. ABS hjælper med styrbarhed, men skaber ikke bedre vejgreb. Dæk og belæsning. Dæktype, dæktryk, slid og belæsning påvirker vejgreb og bilens reaktion. Tung eller højt placeret last ændrer stabiliteten. Kontroller bilen og sænk hastigheden, før du forventer, at elektroniske systemer retter en fysisk ubalance."},"v1-fcfb98a8fa7c3bb7":{"src":"assets/voice/jeppe-neural-v1/v1-fcfb98a8fa7c3bb7.mp3","text":"Tag, sider, skærme, hætter, klapper, døre og vognbund må ikke skabe fare. Ingen farlige kanter. Karrosseriet omfatter blandt andet tag, sider, skærme, front- eller motorhjelm, bagageklap, døre og vognbund. Delene må ikke have skarpe kanter eller stikke ud på en måde, der skaber unødig fare for cyklister, gående eller andre trafikanter. Skade og rust vurderes efter fare. En bule eller en rustplet er ikke i sig selv den afgørende vurdering. Spørgsmålet er, om skade eller rust har et sådant omfang, at karrosseriet er til fare for færdselssikkerheden. Kriteriet er faren, ikke om skaden sidder i en bestemt type del. Låse skal holde under kørslen. Døre, front- eller motorhjelm og bagageklap skal have låse, der kan holde dem lukkede, mens bilen kører. En klap, der ser lukket ud, men ikke fastholdes, kan åbne og skabe fare eller spærre førerens udsyn."},"v1-fdca8a9efd7497da":{"src":"assets/voice/jeppe-neural-v1/v1-fdca8a9efd7497da.mp3","text":"Egen bils blinde områder skal findes og øves fysisk fra den faktiske førerplads."},"v1-fd598631f48be43a":{"src":"assets/voice/jeppe-neural-v1/v1-fd598631f48be43a.mp3","text":"Ved højresving har du set en cyklist bagude, men cyklisten forsvinder bag en parkeret varebil, mens du venter."},"v1-fe8253acdc4124e7":{"src":"assets/voice/jeppe-neural-v1/v1-fe8253acdc4124e7.mp3","text":"Vent med at fuldføre svinget, til udsynet og opholdet er sikkert. Grønt ophæver ikke pligten over for modkørende, og varebilen skjuler en væsentlig risiko."},"v1-fdaf7e56ac38a0fa":{"src":"assets/voice/jeppe-neural-v1/v1-fdaf7e56ac38a0fa.mp3","text":"Slip speederen, øg afstanden gradvist og undgå en brat korrektion. Både vådt føre og nedkørsel kan forlænge bremsningen, mens større afstand giver tid til en jævn reaktion, hvis bilen foran pludselig sænker farten."},"v1-aacb669a942147c1":{"src":"assets/voice/jeppe-neural-v1/v1-aacb669a942147c1.mp3","text":"Hvorfor er det utilstrækkeligt at vurdere træthed ud fra, om du stadig kan holde bilen på vejen?"},"v1-faa9a36612a53787":{"src":"assets/voice/jeppe-neural-v1/v1-faa9a36612a53787.mp3","text":"Læs en øvelsesattest. Brug en anonymiseret øvelsesattest til at finde egenvægt eller køreklar vægt, tilladt totalvægt, tilladt påhængsvægt og eventuel vogntogsvægt. Forklar derefter, hvilke to attester der skal sammenholdes ved en tænkt sammenkobling. Vælg dokumenter til turen. Sammenlign en tur i Danmark med en tur til udlandet med påhængskøretøj. Udpeg for hver tur, hvilke registreringsattester der skal med, og om kopi, original eller en genpart fra Motorstyrelsen er relevant."},"v1-ff4e005842919866":{"src":"assets/voice/jeppe-neural-v1/v1-ff4e005842919866.mp3","text":"Udpeg kontakter og åbninger i undervisningsbilen. Sammen med kørelæreren og i den standsede undervisningsbil udpeger du én for én ratlås, tænding, elektrisk starter, visker og vasker, horn, lygter, klima, el-bagrude og spejlindstilling. Udpeg også hver betjeningsanordning til fronthjelm, motorhjelm og låge til drivmiddel, som findes i bilen. Udpeg førerpladsens betjening. Med kørelæreren viser du i undervisningsbilen pedaler, gearplaceringer, parkeringsbremse, rat, selelås og fastgørelsespunkter. Kørelæreren forklarer bilens særlige løsning, før du rører udstyr, der kan sætte bilen i bevægelse. Udpeg relevante væskedæksler. Med motoren slukket og efter kørelærerens anvisning udpeger du sprinklervæske og de olie- eller væskepåfyldninger, som faktisk findes i undervisningsbilen. Åbn ikke varme eller tryksatte beholdere."}}};
